TURATH_CHUNK(6,[{"num":1200,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَقُصُّ إِلَّا أَمِيرٌ، أَوْ مَأْمُورٌ، أَوْ مُتَكَلِّفٌ."],"takhrij":"حسن: رواه الطبراني في الكبير (140)، كما نقله عنه ابن كثير في جامع المسانيد والسنن (٥٨٦٦)، عن أحمد بن عبد الوهاب بن نجدة الحوطي، حدثنا أبو المغيرة (وهو عبد القدوس بن الحجاج)، حدثنا إسماعيل بن عياش، عن ثعلبة بن مسلم، عن أبي عمران الأنصاري، عن عبادة بن الصامت فذكره.","grade":"حسن","chapter_ar":"باب لا يقص إلا أمير أو مأمور","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr, as transmitted from him by Ibn Kathīr in Jāmiʿ al-Masānīd wa-l-Sunan (4991).","chapter_en":"No One Should Give Public Exhortation Except a Ruler or One Authorized to Do So","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":41,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit, may Allah be pleased with him, reported that the Prophet ﷺ said: “No one should give public exhortation except a ruler, one who has been authorized to do so, or one who takes it upon himself without proper right or qualification.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير، كما نقله عنه ابن كثير في جامع المسانيد والسنن (4991)."},{"num":1201,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: لَمْ يُقَصَّ فِي زَمَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلا أَبِي بَكْرٍ، وَلا عُمَرَ، وَلا عُثْمَانَ، إِنَّمَا كَانَ الْقَصَصُ زَمَنَ الْفِتْنَةِ."],"takhrij":"صحيح: رواه ابن حبان (6261)، والسياق له، وابن أبي شيبة (26714) كلاهما من طريق سفيان، عن عبيد الله بن عمر، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب لا يقص إلا أمير أو مأمور","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Ḥibbān (6261), whose wording is cited here, Ibn Abī Shaybah (26714), and Ibn Mājah (3754).","chapter_en":"No One Should Give Public Exhortation Except a Ruler or One Authorized to Do So","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":41,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, said: “Public exhortation by storytellers was not practiced during the time of the Prophet ﷺ, nor during the time of Abū Bakr, ʿUmar, or ʿUthmān. Rather, this form of public storytelling arose during the time of tribulation.”"]},"buhuth":{"en":["The expression “he gives qaṣaṣ” means that he gives admonition and instruction. Among the important lessons derived from this is that public preaching and teaching in mosques or other public places should be connected to authorization from the legitimate authority, out of concern that tribulations and deviant ideas may be spread within the Muslim community. Accordingly, the authority delegated by the ruler may supervise those who violate this rule and prevent them from giving public exhortation in such places."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (6261)، والسياق له، وابن أبي شيبة (26714)، ورواه ابن ماجه (3754)."},{"num":1202,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ وَأَبِي أُسَيْدٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تَعْرِفُهُ قُلُوبُكُمْ، وَتَلِينُ لَهُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ، وَتَرَوْنَ أَنَّهُ مِنْكُمْ قَرِيبٌ، فَأَنَا أَوْلَاكُمْ بِهِ، وَإِذَا سَمِعْتُمْ الْحَدِيثَ عَنِّي تُنْكِرُهُ قُلُوبُكُمْ، وَتَنْفِرُ أَشْعَارُكُمْ وَأَبْشَارُكُمْ، وَتَرَوْنَ أَنَّهُ مِنْكُمْ بَعِيدٌ، فَأَنَا أَبْعَدُكُمْ مِنْهُ."],"takhrij":"صحيح: رواه أحمد (16058)، والبزار-كشف الأستار (187)، وابن حبان (63) كلهم من طريق أبي عامر العقدي، ثنا سليمان بن بلال، عن ربيعة بن أبي عبدالرحمن، عن عبد الملك بن سعيد بن سويد، عن أبي حميد وأبي أُسيد، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب معرفة أهل العلم بالحديث لصحيحه وضعيفه","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (16058) and al-Bazzār in Kashf al-Astār (187), and authenticated by Ibn Ḥibbān (63).","chapter_en":"The Knowledge of the Scholars Concerning Authentic and Weak Ḥadīth","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Abū Ḥumayd and Abū Usayd, may Allah be pleased with them, reported that the Prophet ﷺ said: “When you hear a ḥadīth attributed to me which your hearts recognize, toward which your hair and skin become receptive, and which you perceive to be close to you, then I am the most entitled to such a report. But when you hear a ḥadīth attributed to me which your hearts reject, from which your hair and skin recoil, and which you perceive to be far from you, then I am the farthest of you from such a report.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16058)، والبزار في كشف الأستار (187)، وصححه ابن حبان (63)."},{"num":1203,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ بَنِي إِسْرَائِيلَ كَتَبُوا كِتَابًا، فَاتَّبَعُوهُ، وَتَرَكُوا التَّوْرَاةَ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (٥٥٤٨) عن محمد بن عثمان بن أبي شيبة، قال: حدثنا جندل بن والق، قال: حدثنا عبيد الله بن عمرو، عن عبد الملك بن عمير، عن أبي بردة، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب قوله تعالى: ﴿فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَذَا مِنْ عِنْدِ اللَّهِ﴾","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (5544).","chapter_en":"The Saying of Allah Most High: “So Woe to Those Who Write the Book With Their Own Hands, Then Say: ‘This Is From Allah’”","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":43,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, the Children of Israel wrote a book, then followed it and abandoned the Torah.”"]},"intro":{"ar":["قال الله تعالى:","﴿فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَذَا مِنْ عِنْدِ اللَّهِ﴾","[البقرة: ٧٩]"],"en":["Allah Most High said:","“So woe to those who write the Book with their own hands, then say: ‘This is from Allah.’”","[Sūrat al-Baqarah 2:79]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (5544)."},{"num":1204,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: النَّاسُ مَعَادِنُ خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا، تَجِدُونَ مِنْ خَيْرِ النَّاسِ أَشَدَّ النَّاسِ كَرَاهِيَةً لِهَذَا الشَّأْنِ حَتَّى يَقَعَ فِيهِ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3496)، ومسلم في الإمارة (2526) كلاهما من طريق أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب خيار الناس في الجاهلية خيارهم في الإسلام إذا فقهوا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3496) and Muslim (2526).","chapter_en":"The Best People in the Pre-Islamic Era Are the Best in Islam If They Gain Understanding","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “People are like mines. The best of them in the pre-Islamic era are the best of them in Islam when they gain understanding of the religion. And among the best of people you will find those who are most averse to this matter of authority until they become involved in it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3496)، ومسلم (2526)."},{"num":1205,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، مَنْ أَكْرَمُ النَّاسِ؟ قَالَ: أَتْقَاهُمْ، قَالُوا: لَيْسَ عَنْ هَذَا نَسْأَلُكَ، قَالَ: فَيُوسُفُ نَبِيُّ اللَّهِ ابْنُ نَبِيِّ اللَّهِ ابْنِ نَبِيِّ اللَّهِ ابْنِ خَلِيلِ اللَّهِ، قَالُوا: لَيْسَ عَنْ هَذَا نَسْأَلُكَ، قَالَ: فَعَنْ مَعَادِنِ الْعَرَبِ تَسْأَلُونِي؟ خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقُهُوا."],"takhrij":"متفق عليه: رواه البخاريّ في كتاب الأنبياء (3353)، ومسلم في الفضائل (2378) كلاهما من حديث يحيى بن سعيد، حدّثنا عبيد الله، قال: حدّثني سعيد ابن أبي سعيد، عن أبيه، عن أبي هريرة، فذكر الحديث، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب خيار الناس في الجاهلية خيارهم في الإسلام إذا فقهوا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3353) and Muslim (2378), and their wording is the same.","chapter_en":"The Best People in the Pre-Islamic Era Are the Best in Islam If They Gain Understanding","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: It was asked: “O Messenger of Allah ﷺ, who are the noblest of people?” He replied: “Those who have the most taqwā.” They said: “That is not what we are asking about.” He said: “Then Yūsuf, the Prophet of Allah, son of a Prophet of Allah, son of the intimate friend of Allah.” They said: “That is not what we are asking about.” He said: “Then are you asking about the ancestral stocks of the Arabs? The best of them in the pre-Islamic era are the best of them in Islam when they gain understanding of the religion.”"]}},"tuhfa":{},"full":1,"rep":[12563],"tks":"متفق عليه: رواه البخاري (3353)، ومسلم (2378)، ولفظهما سواء."},{"num":1206,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: خِيَارُ النَّاسِ فِي الْجَاهِلِيَّةِ، خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا."],"takhrij":"حسن: رواه أحمد (15112) عن روح، حدثنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله، يقول (فذكر الحديث).","grade":"حسن","chapter_ar":"باب خيار الناس في الجاهلية خيارهم في الإسلام إذا فقهوا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (15112).","chapter_en":"The Best People in the Pre-Islamic Era Are the Best in Islam If They Gain Understanding","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: I heard the Messenger of Allah ﷺ say: “The best of people in the pre-Islamic era are the best of them in Islam when they gain understanding of the religion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15112)."},{"num":1207,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ الْخَبَرُ كَالْمُعَايَنَةِ، إِنَّ اللَّهَ عَزَّ وَجَلَّ أَخْبَرَ مُوسَى بِمَا صَنَعَ قَوْمُهُ فِي الْعِجْلِ، فَلَمْ يُلْقِ الْأَلْوَاحَ، فَلَمَّا عَايَنَ مَا صَنَعُوا، أَلْقَى الْأَلْوَاحَ فَانْكَسَرَتْ."],"takhrij":"صحيح: رواه أحمد (2447)، والطبراني في الأوسط (25)، وفي الكبير (1183، 1184)، والبزّار - كما في كشف الأستار (200)، كلّهم من طريق أبي بشر، عن سعيد بن جبير، عن ابن عباس، فذكر نحوه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في زيادة العلم بالمعاينة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (2447), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (25) and al-Muʿjam al-Kabīr (1183, 1184), and al-Bazzār in Kashf al-Astār (200).","chapter_en":"What Has Been Reported Concerning Knowledge Increasing Through Direct Observation","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Being informed is not like seeing directly. Allah, Mighty and Majestic, informed Mūsā of what his people had done with the calf, yet he did not cast down the Tablets. But when he saw directly what they had done, he cast down the Tablets and they broke.”"]},"intro":{"ar":["كما حكى الله تعالى عن خليله إبراهيم عليه السلام:","﴿وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي﴾","[البقرة: ٢٦٠]"],"en":["As Allah Most High related concerning His intimate friend Ibrāhīm عليه السلام:","“And when Ibrāhīm said, ‘My Lord, show me how You give life to the dead.’ He said, ‘Do you not believe?’ He said, ‘Yes, but so that my heart may be reassured.’”","[Sūrat al-Baqarah 2:260]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[652,12338],"tks":"صحيح: رواه أحمد (2447)، والطبراني في الأوسط (25)، وفي الكبير (1183، 1184)، والبزار في كشف الأستار (200)."},{"num":1208,"demo":false,"sanad":"","matn":["عَنْ حُمَيْد بْنِ أَبِي حُمَيْدٍ الطَّوِيلِ قَالَ: كُنَّا مَعَ أَنَسَ بْنَ مَالِكٍ، فَقَالَ: وَاللهِ مَا كُلُّ مَا نُحَدِّثُكُمْ عَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعْنَاهُ مِنْهُ، وَلَكِنْ لَمْ يَكُنْ يَكْذِبُ بَعْضُنَا بَعْضًا."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (699) عن يوسف القاضي، ثنا أبو الرّبيع الزّهرانيّ، ثنا أبو شهاب، عن حميد فذكره. ورواه الحاكم (6458) من وجه آخر عن حميد، به.","grade":"حسن","chapter_ar":"باب رواية الصحابة بعضهم عن بعض ولم يكن فيهم الكذب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī (699).","chapter_en":"The Companions Narrating From One Another, and There Was No Lying Among Them","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":46,"content":{"translation":{"en":["Ḥumayd ibn Abī Ḥumayd al-Ṭawīl reported: We were with Anas ibn Mālik may Allah be pleased with him, and he said: “By Allah, not everything we narrate to you from the Messenger of Allah ﷺ did we hear directly from him. Rather, we narrated from one another, and none of us used to lie to another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (699)."},{"num":1209,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: مَا كُلُّ مَا نُحَدِّثُكُمُوهُ سَمِعْنَاهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنْ حَدَّثَنَا أَصْحَابُنَا، وَكَانَتْ تَشْغَلُنَا رَعِيَّةُ الْإِبِلِ."],"takhrij":"صحيح: رواه أحمد (18498) عن أبي أحمد، حدثنا سفيان، عن أبي إسحاق، عن البراء بن عازب فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب رواية الصحابة بعضهم عن بعض ولم يكن فيهم الكذب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (18498).","chapter_en":"The Companions Narrating From One Another, and There Was No Lying Among Them","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":46,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib, may Allah be pleased with them, said: “Not everything we narrate to you did we hear directly from the Messenger of Allah ﷺ. Rather, our fellow Companions narrated to us, while tending the camels sometimes occupied us.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (18498)."},{"num":1210,"demo":false,"sanad":"","matn":["عَنْ شَدَّادِ بْنِ أَوْسٍ قَالَ: كَانَ أَبُو ذَرٍّ يَسْمَعُ الْحَدِيثَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ الشِّدَّةُ، ثُمَّ يَخْرُجُ إِلَى قَوْمِهِ يُسَلِّمُ عَلَيْهِمْ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرَخِّصُ فِيهِ بَعْدُ، فَلَمْ يَسْمَعْهُ أَبُو ذَرٍّ، فَيَتَعَلَّقَ أَبُو ذَرٍّ بِالْأَمْرِ الشَّدِيدِ."],"takhrij":"حسن: رواه أحمد (17137) عن حسن الأشيب، ثنا ابن لهيعة، ثنا عبيد الله ابن المغيرة، عن يعلى بن شدّاد بن أوس، قال: قال شدّاد بن أوس، فذكره.","grade":"حسن","chapter_ar":"باب في معرفة الناسخ والمنسوخ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (17137) and al-Ṭabarānī (7166).","chapter_en":"Concerning Knowledge of the Abrogating and the Abrogated","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Shaddād ibn Aws, may Allah be pleased with him, reported: Abū Dharr may Allah be pleased with him would sometimes hear from the Messenger of Allah ﷺ a ḥadīth containing strictness. Then he would go out to his people and greet them. Later, the Messenger of Allah ﷺ would grant a concession concerning that matter, but Abū Dharr would not hear it, so he would continue adhering to the earlier, stricter ruling."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17137)، والطبراني (7166)."},{"num":1211,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَامَ فِينَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَقَامًا، مَا تَرَكَ شَيْئًا يَكُونُ فِي مَقَامِهِ ذَلِكَ إِلَى قِيَامِ السَّاعَةِ، إِلَّا حَدَّثَ بِهِ حَفِظَهُ مَنْ حَفِظَهُ، وَنَسِيَهُ مَنْ نَسِيَهُ، قَدْ عَلِمَهُ أَصْحَابِي هَؤُلَاءِ، وَإِنَّهُ لَيَكُونُ مِنْهُ الشَّيْءُ قَدْ نَسِيتُهُ، فَأَرَاهُ فَأَذْكُرُهُ كَمَا يَذْكُرُ الرَّجُلُ وَجْهَ الرَّجُلِ إِذَا غَابَ عَنْهُ، ثُمَّ إِذَا رَآهُ عَرَفَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في القدر (6604)، ومسلم في الفتن (2891: 23) كلاهما من طريق الأعمش، عن أبي وائل (شقيق بن سلمة)، عن حذيفة، فذكره.","grade":"متفق عليه","chapter_ar":"باب إخبار النبي ﷺ بما هو كائن إلى يوم القيامة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6604) and Muslim (2891).","chapter_en":"The Prophet ﷺ Informing of What Would Occur Until the Day of Resurrection","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":48,"content":{"translation":{"en":["Ḥudhayfah, may Allah be pleased with him, said: The Messenger of Allah ﷺ stood before us on one occasion and did not leave out anything that would occur from that time until the establishment of the Hour except that he informed us of it. Whoever retained it retained it, and whoever forgot it forgot it. These Companions of his knew it. Sometimes an event from among those matters would occur after I had forgotten it, then when I saw it I would remember it, just as a man remembers the face of another man who has been absent from him and then recognizes him when he sees him again."]},"buhuth":{"en":["This is Muslim’s wording, while al-Bukhārī’s wording is similar.","In another wording in Muslim:","“The Messenger of Allah ﷺ informed me of everything that would occur until the establishment of the Hour. There was nothing among those matters except that I asked him about it, except that I did not ask him what would drive the people of Madinah out of Madinah.”","Al-Bazzār narrated in Kashf al-Astār (148):","“The Ummah of the Messenger of Allah ﷺ was presented before him, and I stood behind him. When he had finished, he turned toward me and asked, ‘Were you here? Did you hear?’","I replied, ‘Yes.’”","Ḥudhayfah used to say:","“Could any person fully retain all of this?”","He said:","Then the Messenger of Allah ﷺ stood among us and informed us of what would occur until the Day of Resurrection—or he said: he informed us of everything between us and the Hour. Whoever retained it retained it, and whoever forgot it forgot it."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15746],"tks":"متفق عليه: رواه البخاري (6604)، ومسلم (2891)."},{"num":1212,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أَخْطَبَ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْفَجْرَ وَصَعِدَ الْمِنْبَرَ، فَخَطَبَنَا حَتَّى حَضَرَتِ الظُّهْرُ، فَنَزَلَ فَصَلَّى ثُمَّ صَعِدَ الْمِنْبَرَ، فَخَطَبَنَا حَتَّى حَضَرَتِ الْعَصْرُ ثُمَّ نَزَلَ، فَصَلَّى ثُمَّ صَعِدَ الْمِنْبَرَ، فَخَطَبَنَا حَتَّى غَرَبَتِ الشَّمْسُ، فَأَخْبَرَنَا بِمَا كَانَ وَبِمَا هُوَ كَائِنٌ فَأَعْلَمُنَا أَحْفَظُنَا."],"takhrij":"صحيح: رواه مسلم في الفتن (2892) من طريقين عن أبي عاصم، عن عزرة ابن ثابت، أخبرنا علباء بن أحمر، حدثني أبو زيد، يعني عمرو بن أخطب، فذكره.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ بما هو كائن إلى يوم القيامة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2892).","chapter_en":"The Prophet ﷺ Informing of What Would Occur Until the Day of Resurrection","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":48,"content":{"translation":{"en":["ʿAmr ibn Akhṭab, may Allah be pleased with him, reported: The Messenger of Allah ﷺ led us in the Fajr prayer, then ascended the pulpit and addressed us until the time for Ẓuhr arrived. He descended and prayed, then ascended the pulpit again and addressed us until the time for ʿAṣr arrived. He descended and prayed, then ascended the pulpit again and addressed us until the sun set. He informed us of what had already occurred and what would occur in the future. The most knowledgeable among us concerning those matters was the one who remembered the most."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2892)."},{"num":1213,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ قَالَ: تَرَكَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَا طَائِرٌ يَطِيرُ بِجَنَاحَيْهِ إِلا عِنْدَنَا مِنْهُ عِلْمٌ."],"takhrij":"صحيح: رواه البزّار - كشف الأستار (147) قال: كتب إليَّ محمد بن عبدالله بن يزيد المقرئ يخبرني في كتابه، أنّ ابن عيينة حدّثه، عن فطر بن خليفة، عن أبي الطّفيل، عن أبي ذرّ، فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ بما هو كائن إلى يوم القيامة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bazzār in Kashf al-Astār (147) and al-Ṭabarānī (1647).","chapter_en":"The Prophet ﷺ Informing of What Would Occur Until the Day of Resurrection","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":48,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, said: “The Messenger of Allah ﷺ left us, and there was not even a bird flying with its two wings except that we had been given some knowledge concerning it.”"]},"buhuth":{"en":["An additional wording states:","“Nothing remains that brings one closer to Paradise and distances one from the Fire except that it has already been made clear to you.”","Ibn Ḥibbān authenticated it (65).","Regarding the statement, “except that we had knowledge concerning it,” Ibn Ḥibbān said:","“That is, knowledge of his commands and prohibitions, his reports, his actions, and what he permitted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (147)، والطبراني (1647)."},{"num":1214,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَ فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَ أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ."],"takhrij":"حسن: رواه الترمذيّ (2417) عن عبدالله بن عبدالرحمن، أخبرنا الأسود بن عامر، حدثنا أبو بكر بن عياش، عن الأعمش، عن سعيد بن عبدالله بن جريج، عن أبي برزة الأسلميّ، فذكره. قال الترمذيّ: هذا حديث حسن صحيح.","grade":"حسن","chapter_ar":"باب كل عالم يُسأل عن علمه يوم القيامة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2417), who said: “This ḥadīth is Ḥasan Ṣaḥīḥ.”","chapter_en":"Every Person of Knowledge Will Be Questioned About His Knowledge on the Day of Resurrection","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":49,"content":{"translation":{"en":["Abū Barzah al-Aslamī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The feet of a servant will not move on the Day of Resurrection until he is questioned about his life and how he spent it, about his knowledge and what he did with it, about his wealth—where he acquired it and how he spent it—and about his body and how he wore it out.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1306],"tks":"حسن: رواه الترمذي (2417)، وقال: «هذا حديث حسن صحيح»."},{"num":1215,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ أَرْبَعِ خِصَالٍ: عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ وَشَبَابِهِ فِيمَا أَبْلَاهُ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ، وَفِيمَا أَنْفَقَهُ وَعَنْ عِلْمِهِ مَاذَا عَمِلَ فِيهِ."],"takhrij":"حسن: رواه أبو بكر الآجريّ في أخلاق العلماء (114)، والبيهقيّ في المدخل (493)، والخطيب في اقتضاء العلم العمل (2) كلّهم من طريق المفضّل بن محمد الجنديّ، أخبرنا الصّامت بن معاذ، أخبرنا عبد المجيد، عن سفيان الثوريّ، عن صفوان بن سليم، عن عدي بن عدي، عن الصُّنابحيّ، عن معاذ بن جبل، فذكره.","grade":"حسن","chapter_ar":"باب كل عالم يُسأل عن علمه يوم القيامة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ājurrī in Akhlāq al-ʿUlamāʾ (114) and al-Bayhaqī in al-Madkhal (493).","chapter_en":"Every Person of Knowledge Will Be Questioned About His Knowledge on the Day of Resurrection","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":49,"content":{"translation":{"en":["Muʿādh ibn Jabal, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The feet of a servant will not move on the Day of Resurrection until he is questioned about four matters: his life and how he spent it; his youth and how he wore it out; his wealth—where he acquired it and how he spent it; and his knowledge—what he did with it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الآجري في أخلاق العلماء (114)، والبيهقي في المدخل (493)."},{"num":1216,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّمَا رَجُلٍ كَانَتْ عِنْدَهُ وَلِيدَةٌ فَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا، وَأَدَّبَهَا فَأَحْسَنَ تَأْدِيبَهَا، ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا فَلَهُ أَجْرَانِ، وَأَيُّمَا رَجُلٍ مِنْ أَهْلِ الْكِتَابِ آمَنَ بِنَبِيِّهِ وَآمَنَ بِي فَلَهُ أَجْرَانِ، وَأَيُّمَا مَمْلُوكٍ أَدَّى حَقَّ مَوَالِيهِ وَحَقَّ رَبِّهِ فَلَهُ أَجْرَانِ.","قَالَ الشَّعْبِيُّ: خُذْهَا بِغَيْرِ شَيْءٍ قَدْ كَانَ الرَّجُلُ يَرْحَلُ فِيمَا دُونَهِ إِلَى الْمَدِينَةِ، وَقَالَ أَبُو بَكْرٍ: عَنْ أَبِي حَصِينٍ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْتَقَهَا ثُمَّ أَصْدَقَهَا."],"takhrij":"متفق عليه: رواه البخاريّ في النّكاح (5083) ومسلم في الإيمان (154: 241) كلاهما من حديث صالح بن صالح الهمداني، ثنا الشعبيّ، قال: حدثني أبو بردة، عن أبيه، فذكر الحديث، واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تعليم الوليدة وتأديبها","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5083) and Muslim (154), and the wording is that of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning Teaching and Disciplining a Female Slave","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Mūsā, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Any man who possesses a female slave and teaches her, giving her excellent instruction, and disciplines her, giving her excellent discipline, then frees her and marries her, will have two rewards. And any man from the People of the Book who believes in his own prophet and then believes in me will have two rewards. And any slave who fulfills the rights of his masters and the right of his Lord will have two rewards.”","Al-Shaʿbī said: “Take this knowledge without paying anything for it, for a man used to travel to Madinah for something less significant than this.” Abū Bakr also narrated from Abū Ḥuṣayn, from Abū Burdah, from his father, from the Prophet ﷺ: “He frees her and then gives her her bridal gift.”"]},"buhuth":{"en":["The word walīdah means a young girl and is also used for a female slave. Its plural is walāʾid."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5083)، ومسلم (154)، واللفظ للبخاري."},{"num":1217,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: هَلَاكُ أُمَّتِي فِي الْكِتَابِ وَاللَّبَنِ، قَالُوا: يَا رَسُولَ اللَّهِ، مَا الْكِتَابُ وَاللَّبَنُ؟ قَالَ: يَتَعَلَّمُونَ الْقُرْآنَ فَيَتَأَوَّلُونَهُ عَلَى غَيْرِ مَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ، وَيُحِبُّونَ اللَّبَنَ فَيَدَعُونَ الْجَمَاعَاتِ وَالْجُمَعَ وَيَبْدُونَ."],"takhrij":"حسن: رواه أحمد (17415) عن أبي عبدالرحمن (عبدالله بن يزيد المقرئ)، ثنا ابن لهيعة، عن أبي قبيل، قال: لم أسمع من عقبة بن عامر إلاّ هذا الحديث.","grade":"حسن","chapter_ar":"باب ذم من تعلم القرآن وتأوله على غير ما أنزل الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (17415) and Abū Yaʿlā in al-Maqṣad al-ʿAlī (369).","chapter_en":"Condemning the One Who Learns the Qurʾān and Interprets It Contrary to How Allah Revealed It","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir al-Juhanī, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “The destruction of my Ummah will be through the Book and milk.” They asked: “O Messenger of Allah ﷺ, what are the Book and milk?” He replied: “They will learn the Qurʾān and interpret it in a manner other than that in which Allah revealed it. And they will love milk, so they will abandon the congregational prayers and Friday prayers and go out to live in the desert.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17415)، وأبو يعلى في المقصد العلي (369)."},{"num":1218,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَكُونُ خَلْفٌ من بَعْدَ سِتِّينَ سَنَةً أَضَاعُوا الصَّلَاةَ، وَاتَّبَعُوا الشَّهَوَاتِ، فَسَوْفَ يَلْقَوْنَ غَيًّا، ثُمَّ يَكُونُ خَلْفٌ يَقْرَءُونَ الْقُرْآنَ لَا يَعْدُو تَرَاقِيَهُمْ، وَيَقْرَأُ الْقُرْآنَ ثَلَاثَةٌ مُؤْمِنٌ، وَمُنَافِقٌ، وَفَاجِرٌ.","قَالَ بَشِيرٌ: فَقُلْتُ لِلْوَلِيدِ: مَا هَؤُلَاءِ الثَّلَاثَةُ؟ فَقَالَ: الْمُنَافِقُ كَافِرٌ بِهِ، وَالْفَاجِرُ يَتَأَكَّلُ بِهِ، وَالْمُؤْمِنُ يُؤْمِنُ بِهِ."],"takhrij":"حسن: رواه أحمد (11340) عن أبي عبدالرحمن، حدثنا حيوة، أخبرني بشير بن أبي عمرو الخولانيّ، أنّ الوليد بن قيس حدّثه أنه سمع أبا سعيد يقول (فذكر الحديث).","grade":"حسن","chapter_ar":"باب ذم من تعلم القرآن وتأوله على غير ما أنزل الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (11340), and authenticated by Ibn Ḥibbān (755) and al-Ḥākim (2/74).","chapter_en":"Condemning the One Who Learns the Qurʾān and Interprets It Contrary to How Allah Revealed It","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “There will come a later generation after sixty years who will neglect the prayer and follow their desires, so they will soon encounter ruin. Then there will come another generation who recite the Qurʾān, but it will not pass beyond their collarbones. Three types of people recite the Qurʾān: a believer, a hypocrite, and an immoral sinner.” Bashīr said:","I asked al-Walīd: “Who are these three?” He replied: “The hypocrite disbelieves in it, the immoral sinner uses it as a means of earning worldly benefit, and the believer truly believes in it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11340)، وصححه ابن حبان (755)، والحاكم (8643)."},{"num":1219,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَعَلَّمُوا مِنْ أَنْسَابِكُمْ مَا تَصِلُونَ بِهِ أَرْحَامَكُمْ، فَإِنَّ صِلَةَ الرَّحِمِ مَحَبَّةٌ فِي الْأَهْلِ، مَثْرَاةٌ فِي الْمَالِ، مَنْسَأَةٌ فِي الْأَثَرِ."],"takhrij":"حسن: رواه الترمذيّ (1979) عن أحمد بن محمد، أخبرنا عبدالله بن المبارك، عن عبد الملك بن عيسى الثقفيّ، عن يزيد مولى المنبعث، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب في الحث على تعلم الأنساب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (1979), Aḥmad (8868), and al-Ḥākim (7284).","chapter_en":"Encouragement to Learn Genealogies","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":52,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “Learn enough of your genealogies to enable you to maintain your ties of kinship. Maintaining ties of kinship brings love among one’s family, increase in wealth, and extension of one’s lifespan.”"]},"buhuth":{"en":["The phrase “an extension in one’s trace” means an increase in lifespan."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13367],"tks":"حسن: رواه الترمذي (1979)، وأحمد (8868)، والحاكم (7284)."},{"num":1220,"demo":false,"sanad":"","matn":["عَنِ الْعَلَاءِ بْنِ خَارِجَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَعَلَّمُوا مِنْ أَنْسَابِكُمْ مَا تَصِلُونَ بِهِ أَرْحَامَكُمْ، فَإِنَّ صِلَةَ الرَّحِمِ مَحَبَّةٌ لِلْأَهْلِ، وَثَرَاءٌ لِلْمَالِ وَمَنْسَأَةٌ لِلْأَجَلِ."],"takhrij":"حسن: رواه الطبراني (176) –وعنه أبو نعيم في معرفة الصحابة (5511) عن علي بن عبد العزيز، حدثنا مسلم بن إبراهيم، حدثنا وهيب (هو ابن خالد)، حدثنا عبد الرحمن بن حرملة، عن عبد الملك بن يعلى، عن العلاء بن خارجة فذكره.","grade":"حسن","chapter_ar":"باب في الحث على تعلم الأنساب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī (18/98), and through him by Abū Nuʿaym in Maʿrifat al-Ṣaḥābah (5511).","chapter_en":"Encouragement to Learn Genealogies","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":52,"content":{"translation":{"en":["Al-ʿAlāʾ ibn Khārijah, may Allah be pleased with him, reported that the Prophet ﷺ said: “Learn enough of your genealogies to enable you to maintain your ties of kinship. Maintaining ties of kinship brings love among one’s family and an extension of one’s appointed lifespan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (176)، وعنه أبو نعيم في معرفة الصحابة (5511)."},{"num":1221,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ عَمْرٍو بْنِ الْعَاصِ قَالَ: كُنْتُ عِنْدَ ابْنِ عَبَّاسٍ، فَأَتَاهُ رَجُلٌ فَقَالَ: مَنْ أَنْتَ؟ قَالَ: فَمَتَّ لَهُ بِرَحِمٍ بَعِيدَةٍ، فَأَلَانَ لَهُ الْقَوْلَ، فَقَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اعْرِفُوا أَنْسَابَكُمْ تَصِلُوا أَرْحَامَكُمْ، فَإِنَّهُ لَا قُرْبَ بِالرَّحِمِ إِذَا قُطِعَتْ وَإِنْ كَانَتْ قَرِيبَةً، وَلَا بُعْدَ بِهَا إِذَا وُصِلَتْ وَإِنْ كَانَتْ بَعِيدَةً."],"takhrij":"صحيح: رواه أبو داود الطّيالسيّ (2880) عن إسحاق بن سعيد، حدثني أبي، فذكر الحديث. وصحّحه الحاكم (300)، فرواه من طريق الطّيالسيّ، به. ثم قال: صحيح على شرط الشيخين، وصحّحه أيضا الحافظ في المطالب العالية (2519).","grade":"صحيح","chapter_ar":"باب في الحث على تعلم الأنساب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd al-Ṭayālisī (2880).","chapter_en":"Encouragement to Learn Genealogies","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":52,"content":{"translation":{"en":["Saʿīd ibn ʿAmr ibn al-ʿĀṣ reported: I was with Ibn ʿAbbās may Allah be pleased with them when a man came to him. Ibn ʿAbbās asked: “Who are you?” The man mentioned a distant family connection between them, so Ibn ʿAbbās spoke gently to him and then said: The Messenger of Allah ﷺ said: “Know your genealogies so that you may maintain your ties of kinship. There is no true closeness through kinship when it is severed, even if the blood relationship is near; and there is no true distance when it is maintained, even if the blood relationship is distant.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود الطيالسي (2880)."},{"num":1222,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ قَالَ: قَدِمَ رَجُلَانِ مِنَ الْمَشْرِقِ فَخَطَبَا فَعَجِبَ النَّاسُ لِبَيَانِهِمَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنَ الْبَيَانِ لَسِحْرًا. أَوْ قَالَ: إِنَّ بَعْضَ الْبَيَانِ لَسِحْرٌ."],"takhrij":"صحيح: رواه مالك في كتاب الكلام والغيبة (7) عن زيد بن أسلم، عن","grade":"صحيح","chapter_ar":"باب إن من البيان سحرًا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (7) and al-Bukhārī (5767).","chapter_en":"Indeed, Some Eloquent Speech Is Like Magic","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":53,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: Two men came from the East and delivered speeches, and the people were impressed by their eloquence. The Prophet ﷺ said: “Indeed, some eloquent speech is like magic.” Or he said: “Indeed, some forms of eloquent speech are like magic.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (7)، والبخاري (5767)."},{"num":1223,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ يَتَكَلَّمُ بِكَلَامٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنَ الْبَيَانِ سِحْرًا، وَإِنَّ مِنَ الشِّعْرِ حُكْمًا."],"takhrij":"حسن: رواه أبو داود (5011)، والترمذيّ (2845)، وابن ماجه (3756) كلهم عن سماك، عن عكرمة، عن ابن عباس، فذكر الحديث، واللّفظ لأبي داود.","grade":"حسن","chapter_ar":"باب إن من البيان سحرًا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (5011), al-Tirmidhī (2845), and Ibn Mājah (3756).","chapter_en":"Indeed, Some Eloquent Speech Is Like Magic","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":53,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: A Bedouin came to the Prophet ﷺ and began speaking eloquently. The Messenger of Allah ﷺ said: “Indeed, some eloquent speech is like magic, and indeed some poetry contains wisdom.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14576],"tks":"حسن: رواه أبو داود (5011)، والترمذي (2845)، وابن ماجه (3756)."},{"num":1224,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْبَرَكَةُ مَعَ أَكَابِرِكُمْ."],"takhrij":"صحيح: رواه الطبرانيّ في الأوسط (211، مجمع البحرين) من طريق الوليد ابن مسلم، عن عبدالله بن المبارك، عن خالد الحذّاء، عن عكرمة، عن ابن عباس، فذكره. وصحّحه ابن حبان (559)، والحاكم (210) فروياه من طرق عن ابن المبارك، به.","grade":"صحيح","chapter_ar":"باب الترغيب في طلب العلم من الأكابر دون الأصاغر","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (211), and authenticated by Ibn Ḥibbān (559).","chapter_en":"Encouragement to Seek Knowledge From Senior Scholars Rather Than the Young or Unqualified","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":54,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported that the Prophet ﷺ said: “Blessing is with your elders.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط، كما في مجمع البحرين (211)، وصححه ابن حبان (559)."},{"num":1225,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَيَّةَ الْجُمَحِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ ثَلَاثًا: إِحْدَاهُنَّ أَنْ يُلْتَمَسَ الْعِلْمُ عِنْدَ الْأَصَاغِرِ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (908)، وابن عبد البر في جامع بيان العلم (1052) من طريق ابن المبارك، وهو عنده في الزّهد (61)، عن","grade":"حسن","chapter_ar":"باب الترغيب في طلب العلم من الأكابر دون الأصاغر","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī (22/361–362) and Ibn ʿAbd al-Barr in Jāmiʿ Bayān al-ʿIlm (1052).","chapter_en":"Encouragement to Seek Knowledge From Senior Scholars Rather Than the Young or Unqualified","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":54,"content":{"translation":{"en":["Abū Umayyah al-Jumaḥī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, among the signs of the Hour are three things, one of which is that knowledge will be sought from the young or unqualified.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (22/361–362)، وابن عبد البر في جامع بيان العلم (1052)."},{"num":1226,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ فِي ثَوْبٍ وَاحِدٍ - (يَعْنِي فِي الْقَبْرِ) - ثُمَّ يَقُولُ: أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ؟ فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ."],"takhrij":"صحيح: رواه البخاريّ في الجنائز (1343) عن عبدالله بن يوسف، عن الليث، حدثني ابن شهاب، عن عبدالرحمن بن كعب بن مالك، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب الترغيب في إكرام العلماء وإجلالهم وتوقيرهم","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (1343).","chapter_en":"Encouragement to Honor Scholars, Revere Them, and Show Them Due Respect","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":55,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: The Prophet ﷺ used to place two of the martyrs of Uḥud together in one grave, then ask: “Which of the two had learned more of the Qurʾān?” When one of them was indicated, he would place him first in the niche of the grave."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1343)."},{"num":1227,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ إِجْلَالِ اللَّهِ إِكْرَامَ ذِي الشَّيْبَةِ الْمُسْلِمِ، وَحَامِلِ الْقُرْآنِ غَيْرِ الْغَالِي فِيهِ وَالْجَافِي عَنْهُ، وَإِكْرَامَ ذِي السُّلْطَانِ الْمُقْسِطِ."],"takhrij":"حسن: رواه أبو داود (4843) عن إسحاق بن إبراهيم الصواف، عن","grade":"حسن","chapter_ar":"باب الترغيب في إكرام العلماء وإجلالهم وتوقيرهم","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4843).","chapter_en":"Encouragement to Honor Scholars, Revere Them, and Show Them Due Respect","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":55,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, part of venerating Allah is honoring the elderly Muslim; honoring the bearer of the Qurʾān who is neither excessive concerning it nor neglectful of it; and honoring the just ruler.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13932,14280],"tks":"حسن: رواه أبو داود (4843)."},{"num":1228,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: لَمَّا نَزَلَتْ بَنُو قُرَيْظَةَ عَلَى حُكْمِ سَعْدٍ هُوَ ابْنُ مُعَاذٍ، بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَ قَرِيبًا مِنْهُ فَجَاءَ عَلَى حِمَارٍ فَلَمَّا دَنَا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قُومُوا إِلَى سَيِّدِكُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الجهاد والسير (3043)، ومسلم في الجهاد والسير (1768) كلاهما من حديث شعبة، عن سعد بن إبراهيم، عن أبي أمامة وهو ابن سهل بن حُنيف، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب القيام لأهل العلم وغيرهم على وجه الإكرام","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3043) and Muslim (1768).","chapter_en":"Standing for People of Knowledge and Others as a Form of Respect","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":56,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: When Banū Qurayẓah agreed to accept the judgment of Saʿd may Allah be pleased with him, the Messenger of Allah ﷺ sent for him. He was nearby and came riding upon a donkey. When he drew near, the Prophet ﷺ said: “Stand up for your leader.”"]},"buhuth":{"en":["Muslim ibn al-Ḥajjāj said:","“I do not know of any ḥadīth concerning a man standing for another man that is more authentic than this one. This standing was by way of kindness and respect, not by way of excessive glorification. The Prophet ﷺ commanded the Anṣār to stand for their leader.”","Narrated by al-Bayhaqī in al-Madkhal (708) with his chain to Muslim ibn al-Ḥajjāj.","Al-Khaṭṭābī said in Maʿālim al-Sunan (5/390):","“A person standing before a virtuous leader or a just governor, and a student standing for a scholar, is recommended and not disliked. The prohibition or dislike applies to those who do not possess such qualities.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13934],"tks":"متفق عليه: رواه البخاري (3043)، ومسلم (1768)."},{"num":1229,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ مَالِكٍ يُحَدِّثُ حِينَ تَخَلَّفَ عَنْ قِصَّةِ تَبُوكَ. فَذَكَرَ الْحَدِيثَ بِطُولِهِ. قَالَ فِيهِ لَمَّا بُشِّر بِالتَّوْبَة: انْطَلَقْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَتَلَقَّانِي النَّاسُ فَوْجًا فَوْجًا يُهَنُّونِي بِالتَّوْبَةِ، يَقُولُونَ: لِتَهْنِكَ تَوْبَةُ اللَّهِ عَلَيْكَ، قَالَ كَعْبٌ: حَتَّى دَخَلْتُ الْمَسْجِدَ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ حَوْلَهُ النَّاسُ، فَقَامَ إِلَيَّ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ يُهَرْوِلُ حَتَّى صَافَحَنِي وَهَنَّانِي، وَاللَّهِ مَا قَامَ إِلَيَّ رَجُلٌ مِنْ الْمُهَاجِرِينَ غَيْرَهُ وَلَا أَنْسَاهَا لِطَلْحَةَ."],"takhrij":"متفق عليه: رواه البخاريّ (4418)، ومسلم (2769) كلاهما من طريق ابن شهاب، عن عبدالرحمن بن عبدالله بن كعب بن مالك، أنّ عبدالله بن كعب قائد كعب حين عمي من بنيه قال: سمعت كعب بن مالك، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب القيام لأهل العلم وغيرهم على وجه الإكرام","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4418) and Muslim (2769).","chapter_en":"Standing for People of Knowledge and Others as a Form of Respect","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":56,"content":{"translation":{"en":["Kaʿb ibn Mālik may Allah be pleased with him, while relating the account of his remaining behind from the Messenger of Allah ﷺ during the expedition of Tabūk, said: When I was given the glad tidings that my repentance had been accepted, I set out for the Messenger of Allah ﷺ. The people met me group after group, congratulating me upon my repentance and saying: “May Allah’s acceptance of your repentance bring you joy.” When I entered the mosque, Ṭalḥah ibn ʿUbaydillāh, may Allah be pleased with him, stood and hurried toward me until he shook my hand and congratulated me. No other man among the Muhājirūn stood for me besides him, and I never forgot that gesture from Ṭalḥah."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4418)، ومسلم (2769)."},{"num":1230,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ قَالَتْ: مَا رَأَيْتُ أَحَدًا أَشْبَهَ سَمْتًا وَدَلًّا وَهَدْيًا بِرَسُولِ اللَّهِ فِي قِيَامِهَا وَقُعُودِهَا مِنْ فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: وَكَانَتْ إِذَا دَخَلَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ إِلَيْهَا فَقَبَّلَهَا، وَأَجْلَسَهَا فِي مَجْلِسِهِ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ عَلَيْهَا قَامَتْ مِنْ مَجْلِسِهَا فَقَبَّلَتْهُ وَأَجْلَسَتْهُ فِي مَجْلِسِهَا، فَلَمَّا مَرِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَتْ فَاطِمَةُ، فَأَكَبَّتْ عَلَيْهِ فَقَبَّلَتْهُ، ثُمَّ رَفَعَتْ رَأْسَهَا فَبَكَتْ، ثُمَّ أَكَبَّتْ عَلَيْهِ ثُمَّ رَفَعَتْ رَأْسَهَا فَضَحِكَتْ، فَقُلْتُ: إِنْ كُنْتُ لَأَظُنُّ أَنَّ هَذِهِ مِنْ أَعْقَلِ نِسَائِنَا فَإِذَا هِيَ مِنَ النِّسَاءِ، فَلَمَّا تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ لَهَا: أَرَأَيْتِ حِينَ أَكْبَبْتِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَفَعْتِ رَأْسَكِ فَبَكَيْتِ، ثُمَّ أَكْبَبْتِ عَلَيْهِ فَرَفَعْتِ رَأْسَكِ فَضَحِكْتِ مَا حَمَلَكِ عَلَى ذَلِكَ؟ قَالَتْ: إِنِّي إِذًا لَبَذِرَةٌ أَخْبَرَنِي أَنَّهُ مَيِّتٌ مِنْ وَجَعِهِ هَذَا فَبَكَيْتُ، ثُمَّ أَخْبَرَنِي أَنِّي أَسْرَعُ أَهْلِهِ لُحُوقًا بِهِ فَذَاكَ حِينَ ضَحِكْتُ."],"takhrij":"صحيح: رواه أبو داود (5217)، والترمذي (3872)، والبخاري في الأدب المفرد (947)، والنسائي في الكبرى (8311)، وصححه ابن حبان (6953)، والحاكم (7715) كلهم من طريق إسرائيل، أخبرنا ميسرة بن حبيب، أخبرني المتهال بن عمرو، حدثتني عائشة بنت طلحة، عن عائشة أم المؤمنين فذكرته.","grade":"صحيح","chapter_ar":"باب القيام لأهل العلم وغيرهم على وجه الإكرام","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (5217), al-Tirmidhī (3872), al-Bukhārī in al-Adab al-Mufrad (947), and al-Nasāʾī in al-Sunan al-Kubrā (8311). It was authenticated by Ibn Ḥibbān (6953) and al-Ḥākim (7715).","chapter_en":"Standing for People of Knowledge and Others as a Form of Respect","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":56,"content":{"translation":{"en":["ʿĀʾishah, Mother of the Believers may Allah be pleased with her, said: “I never saw anyone whose manner, bearing, and conduct in standing and sitting more closely resembled the Messenger of Allah ﷺ than Fāṭimah, the daughter of the Messenger of Allah ﷺ. Whenever she entered upon the Prophet ﷺ, he would stand for her, kiss her, and seat her in his place. And whenever the Prophet ﷺ entered upon her, she would rise from her seat, kiss him, and seat him in her place. When the Prophet ﷺ became ill, Fāṭimah entered and leaned over him and kissed him. She then raised her head and cried. Then she leaned over him again, raised her head, and laughed. I said to myself: ‘I used to think that she was among the most intelligent of our women, but here she is behaving like other women!’ After the Prophet ﷺ passed away, I asked her: ‘When you leaned over the Prophet ﷺ and then raised your head and cried, and afterward leaned over him again, raised your head, and laughed—what caused you to do that?’ She replied: ‘When I leaned over him the first time, he informed me that he would die from this illness, so I cried. Then he informed me that I would be the first of his family to join him, and that was when I laughed.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5217)، والترمذي (3872)، والبخاري في الأدب المفرد (947)، والنسائي في الكبرى (8311)، وصححه ابن حبان (6953)، والحاكم (7715)."},{"num":1231,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ، وَأَبُو بَكْرٍ يُسْمِعُ النَّاسَ تَكْبِيرَهُ، فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا، فَأَشَارَ إِلَيْنَا فَقَعَدْنَا فَصَلَّيْنَا بِصَلَاتِهِ قُعُودًا، فَلَمَّا سَلَّمَ قَالَ: إِنْ كِدْتُمْ آنِفًا لَتَفْعَلُونَ فِعْلَ فَارِسَ وَالرُّومِ يَقُومُونَ عَلَى مُلُوكِهِمْ وَهُمْ قُعُودٌ فَلَا تَفْعَلُوا، ائْتَمُّوا بِأَئِمَّتِكُمْ إِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (413) عن قتيبة بن سعيد، عن الليث، عن أبي الزبير، عن أبي جابر، فذكره.","grade":"صحيح","chapter_ar":"باب من كره أن يُقام له على وجه التعظيم مخافة الكبر","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (413).","chapter_en":"Whoever Disliked That People Stand for Him as a Form of Exaltation, Out of Fear of Arrogance","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":57,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: The Messenger of Allah ﷺ became ill, so we prayed behind him while he was seated, and Abū Bakr, may Allah be pleased with him, was making the people hear the Prophet’s takbīr. The Prophet ﷺ turned and saw us standing, so he gestured to us and we sat down. We then completed the prayer seated, following his prayer. When he finished with salām, he said: “You were just about to do what the Persians and Romans do: they stand over their kings while their kings are seated. Do not do that. Follow your imāms. If the imām prays standing, then pray standing; and if he prays seated, then pray seated.”"]}},"tuhfa":{},"full":1,"rep":[2283,2608,13937],"tks":"صحيح: رواه مسلم (413)."},{"num":1232,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَحَبَّ أَنْ يَمْثُلَ لَهُ الرِّجَالُ قِيَامًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه أبو داود (5229)، والترمذي (2755) كلاهما من حديث حبيب بن الشّهيد، عن أبي مِجْلز، قال: خرج معاوية على ابن الزبير وابن عامر، فقام إليه ابن عامر، وجلس ابن الزبير، فقال معاوية لابن عامر: اجلسْ فإنّي سمعت رسول الله صلى الله عليه وسلم يقول فذكره.","grade":"صحيح","chapter_ar":"باب من كره أن يُقام له على وجه التعظيم مخافة الكبر","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (5229) and al-Tirmidhī (2755).","chapter_en":"Whoever Disliked That People Stand for Him as a Form of Exaltation, Out of Fear of Arrogance","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":57,"content":{"translation":{"en":["Muʿāwiyah, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “Whoever loves that men should stand before him in attendance, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13938],"tks":"صحيح: رواه أبو داود (5229)، والترمذي (2755)."},{"num":1233,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: مَا كَانَ شَخْصٌ أَحَبَّ إِلَيْهِمْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانُوا إِذَا رَأَوْهُ لَمْ يَقُومُوا، لِمَا يَعْلَمُوا مِنْ كَرَاهِيَتِهِ لِذَلِكَ."],"takhrij":"صحيح: رواه الترمذي (2754)، وأحمد (12345)، والبخاري في الأدب المفرد (946)، وأبو يعلى (3784) كلهم من طرق عن حماد بن سلمة، عن حميد، عن أنس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من كره أن يُقام له على وجه التعظيم مخافة الكبر","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2754), Aḥmad (12345), al-Bukhārī in al-Adab al-Mufrad (946), and Abū Yaʿlā (3784).","chapter_en":"Whoever Disliked That People Stand for Him as a Form of Exaltation, Out of Fear of Arrogance","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد في الترغيب في العلم","group_en":"Collection of Chapters on What Has Been Reported Encouraging Knowledge","part_no":3,"group_no":1,"chapter_no":57,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: “No person was more beloved to them than the Messenger of Allah ﷺ, yet when they saw him they would not stand up for him, because they knew that he disliked that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2754)، وأحمد (12345)، والبخاري في الأدب المفرد (946)، وأبو يعلى (3784)."},{"num":1234,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مِنْ أَشْرَاطِ السَّاعَةِ، أَنْ يَقِلَّ الْعِلْمُ، وَيَظْهَرَ الْجَهْلُ، وَيَظْهَرَ الزِّنَا، وَتَكْثُرَ النِّسَاءُ، وَيَقِلَّ الرِّجَالُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً الْقَيِّمُ الْوَاحِدُ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (81)، ومسلم في العلم (2671: 9) كلاهما من طريق شعبة، عن قتادة، عن أنس قال: لَأُحَدِّثَنَّكُمْ حَدِيثًا لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي، فذكره.","grade":"متفق عليه","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (81) and Muslim (2671).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: I heard the Messenger of Allah ﷺ say: “Among the signs of the Hour are that knowledge will diminish, ignorance will appear, fornication will become widespread, women will become numerous, and men will become few, until one man will be responsible for fifty women.”"]}},"tuhfa":{},"full":1,"rep":[15931],"tks":"متفق عليه: رواه البخاري (81)، ومسلم (2671)."},{"num":1235,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ وَأَبِي مُوسَى، فَقَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ بَيْنَ يَدَيِ السَّاعَةِ أَيَّامًا يُرْفَعُ فِيهَا الْعِلْمُ، وَيَنْزِلُ فِيهَا الْجَهْلُ، وَيَكْثُرُ فِيهَا الْهَرْجُ وَالْهَرْجُ الْقَتْلُ."],"takhrij":"متفق عليه: رواه البخاريّ في الفتن (7062)، ومسلم في العلم (2672) كلاهما من طريق الأعمش، عن أبي وائل شقيق بن سلمة، قَالَ: كُنْتُ جَالِسًا مَعَ عَبْدِ اللَّهِ وَأَبِي مُوسَى، فَقَالَا (فذكراه).","grade":"متفق عليه","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7062) and Muslim (2672).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh and Abū Mūsā, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Before the Hour there will be days in which knowledge will be lifted, ignorance will descend, and harj will become widespread.” Harj means killing."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7062)، ومسلم (2672)."},{"num":1236,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنَ النَّاسِ، وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ، حَتَّى إِذَا لَمْ يَتْرُكْ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا، فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا."],"takhrij":"متفق عليه: رواه البخاري في العلم (100) عن إسماعيل بن أبي أويس، قال: حدثني مالك، عن هشام بن عروة، عن أبيه، عن عبدالله بن عمرو.","grade":"متفق عليه","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (100) and Muslim (2673).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported: I heard the Messenger of Allah ﷺ say: “Allah does not take away knowledge by snatching it out of the people. Rather, He takes away knowledge by taking away the scholars. When no scholar remains, people will take ignorant leaders. They will be asked questions and will give religious verdicts without knowledge, so they will go astray and lead others astray.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (100)، ومسلم (2673)."},{"num":1237,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ قَالَ: قَالَتْ لِي عَائِشَةُ: يَا ابْنَ أُخْتِي بَلَغَنِي، أَنَّ عَبْدَ اللَّهِ بْنَ عَمْرٍو مَارٌّ بِنَا إِلَى الْحَجِّ، فَالْقَهُ فَسَائِلْهُ، فَإِنَّهُ قَدْ حَمَلَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِلْمًا كَثِيرًا، قَالَ: فَلَقِيتُهُ فَسَاءَلْتُهُ عَنْ أَشْيَاءَ يَذْكُرُهَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ عُرْوَةُ: فَكَانَ فِيمَا ذَكَرَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ لَا يَنْتَزِعُ الْعِلْمَ مِنَ النَّاسِ انْتِزَاعًا، وَلَكِنْ يَقْبِضُ الْعُلَمَاءَ، فَيَرْفَعُ الْعِلْمَ مَعَهُمْ وَيُبْقِي فِي النَّاسِ رُءُوسًا جُهَّالًا يُفْتُونَهُمْ بِغَيْرِ عِلْمٍ، فَيَضِلُّونَ وَيُضِلُّونَ.","قَالَ عُرْوَةُ: فَلَمَّا حَدَّثْتُ عَائِشَةَ بِذَلِكَ، أَعْظَمَتْ ذَلِكَ وَأَنْكَرَتْهُ قَالَتْ: أَحَدَّثَكَ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ هَذَا، قَالَ عُرْوَةُ: حَتَّى إِذَا كَانَ قَابِلٌ؟ قَالَتْ لَهُ: إِنَّ ابْنَ عَمْرٍ وَقَدْ قَدِمَ، فَالْقَهُ ثُمَّ فَاتِحْهُ، حَتَّى تَسْأَلَهُ عَنِ الْحَدِيثِ الَّذِي ذَكَرَهُ لَكَ فِي الْعِلْمِ قَالَ: فَلَقِيتُهُ فَسَاءَلْتُهُ، فَذَكَرَهُ لِي نَحْوَ مَا حَدَّثَنِي بِهِ فِي مَرَّتِهِ الْأُولَى.","قَالَ عُرْوَةُ: فَلَمَّا أَخْبَرْتُهَا بِذَلِكَ قَالَتْ: مَا أَحْسَبُهُ إِلَّا قَدْ صَدَقَ أَرَاهُ لَمْ يَزِدْ فِيهِ شَيْئًا وَلَمْ يَنْقُصْ."],"takhrij":"متفق عليه: رواه مسلم في العلم (2673) عن حرملة بن يحيى التّجيبيّ، أخبرنا عبدالله بن وهب، حدّثني أبو شريح، أنّ أبا الأسود حدّثه عن عروة بن الزبير، قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2673).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿUrwah ibn al-Zubayr reported: ʿĀʾishah, may Allah be pleased with her, said: “O son of my sister, I have been informed that ʿAbdullāh ibn ʿAmr will pass by us on his way to Ḥajj. Meet him and ask him questions, for he has preserved much knowledge from the Prophet ﷺ.” ʿUrwah said: So I met him and asked him about matters that he narrated from the Messenger of Allah ﷺ. Among what he mentioned was that the Prophet ﷺ said: “Allah does not remove knowledge from people by forcibly snatching it away. Rather, He takes away the scholars, so knowledge is lifted along with them. He then leaves among the people ignorant leaders who issue religious verdicts without knowledge, so they go astray and lead others astray.” ʿUrwah said:","When I told ʿĀʾishah about this, she regarded the matter as serious and questioned it. She asked: “Did he tell you that he heard the Prophet ﷺ say this?” Then when the following year came, she said: “Ibn ʿAmr has arrived. Meet him, begin speaking with him, and then ask him about the ḥadīth concerning knowledge that he previously narrated to you.” So I met him and asked him, and he narrated it to me in essentially the same way as he had narrated it the first time. When I informed ʿĀʾishah, she said:","“I think he has indeed spoken truthfully. I see that he neither added anything to it nor omitted anything from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2673)."},{"num":1238,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَتَقَارَبُ الزَّمَانُ وَيُقْبَضُ الْعِلْمُ، وَتَظْهَرُ الْفِتَنُ، وَيُلْقَى الشُّحُّ، وَيَكْثُرُ الْهَرْجُ، قَالُوا: وَمَا الْهَرْجُ؟ قَالَ: الْقَتْلُ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (85)، ومسلم أيضاً في العلم (157) كلاهما من طريق الزّهريّ، حدّثني حميد بن عبدالرحمن بن عوف، أنّ أبا هريرة قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (85) and Muslim (157).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Time will draw closer together, knowledge will be taken away, tribulations will appear, miserliness will be cast into people’s hearts, and harj will become widespread.” They asked: “What is harj?” He replied: “Killing.”"]},"buhuth":{"en":["The meaning of “the taking away of knowledge” was also explained by ʿUmar ibn al-Khaṭṭāb may Allah be pleased with him in al-Bazzār’s Kashf al-Astār (236). He said:","“Indeed, the taking away of knowledge is not something that is pulled out from the chests of men. Rather, it is the passing away of the scholars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (85)، ومسلم (157)."},{"num":1239,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَظْهَرُ الْفِتَنُ، وَيَكْثُرُ الْهَرْجُ، وَيُرْفَعُ الْعِلْمُ، فَلَمَّا سَمِعَ عُمَرُ أَبَا هُرَيْرَةَ يَقُولُ: يُرْفَعُ الْعِلْمُ، قَالَ عُمَرُ: أَمَا إِنَّهُ لَيْسَ يُنْزَعُ مِنْ صُدُورِ الْعُلَمَاءِ، وَلَكِنْ يَذْهَبُ الْعُلَمَاءُ."],"takhrij":"صحيح: رواه الإمام أحمد (10231) عن وكيع، عن جعفر بن برقان، عن يزيد بن الأصمّ، عن أبي هريرة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (10231).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Tribulations will appear, harj will become widespread, and knowledge will be lifted.” When ʿUmar, may Allah be pleased with him, heard Abū Hurayrah say, “Knowledge will be lifted,” he said: “It is not pulled out from the chests of the scholars. Rather, the scholars themselves pass away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (10231)."},{"num":1240,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَيَأْتِي عَلَى أُمَّتِي زَمَانٌ، يَكْثُرُ الْقُرَّاءُ، وَيَقِلُّ الْفُقَهَاءُ، وَيُقْبَضُ الْعِلْمُ، وَيَكْثُرُ الْهَرْجُ. قَالُوا: وَمَا الْهَرْجُ؟ قَالَ: الْقَتْلُ بَيْنَكُمْ، ثُمَّ يَأْتِي بَعْدَ ذَلِكَ زَمَانٌ يَقْرَأُ الْقُرْآنَ رِجَالٌ لَا يُجَاوِزُ تَرَاقِيَهُمْ، ثُمَّ يَأْتِي زَمَانٌ يُجَادِلُ الْمُنَافِقُ الْمُشْرِكُ الْمُؤْمِنَ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (٣٢٧٧)، مجمع البحرين (273) عن بكر بن سهل، ثنا عبدالله بن يوسف، ثنا ابن لهيعة، ثنا دراج، عن عبدالرحمن بن حُجيرة، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (273).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “A time will come upon my Ummah when reciters of the Qurʾān will be numerous, while jurists and people of deep understanding will be few. Knowledge will be taken away and harj will increase.” They asked: “What is harj?” He replied: “Killing among yourselves.” Then after that will come a time when men will recite the Qurʾān, but it will not go beyond their collarbones. Then there will come a time when the hypocrite and polytheist will argue against the believer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (273)."},{"num":1241,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ لَا يَنْزِعُ الْعِلْمَ مِنْكُمْ بَعْدَمَا أَعْطَاكُمُوهُ انْتِزَاعًا، وَلَكِنْ يَقْبِضُ الْعُلَمَاءَ بِعِلْمِهِمْ، وَيَبْقَى النَّاسُ جُهَّالًا فَيَسْأَلُونَ فَيُفْتُونَ فَيَضِلُّونَ وَيُضِلُّونَ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (٨٧٣٧)، مجمع البحرين (334) عن مطلب، ثنا عبدالله، حدّثني الليث، عن عمر بن السّائب، عن أسامة بن زيد، عن يعقوب بن الأشجّ، عن سعيد بن أبي سعيد، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (334).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Allah will not take knowledge away from you after having given it to you by forcibly pulling it out. Rather, He will take away the scholars together with their knowledge. Ignorant people will remain. They will be asked questions and will issue religious verdicts, so they will go astray and lead others astray.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (334)."},{"num":1242,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ، أنّ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَظَرَ إِلَى السَّمَاءِ يَوْمًا فَقَالَ: هَذَا أَوَانٌ يُرْفَعُ الْعِلْمُ، فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ يُقَالُ لَهُ: لَبِيدُ بْنُ زِيَادٍ: يَا رَسُولَ اللهِ يُرْفَعُ الْعِلْمُ وَقَدْ أُثْبِتَ وَوَعَتْهُ الْقُلُوبُ؟ فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ كُنْتُ لَأَحْسَبُكَ مِنْ أَفْقَهِ أَهْلِ الْمَدِينَةِ، وَذَكَرَ لَهُ ضَلَالَةَ الْيَهُودِ وَالنَّصَارَى عَلَى مَا فِي أَيْدِيهِمْ مِنْ كِتَابِ اللهِ، قَالَ: فَلَقِيتُ شَدَّادَ بْنَ أَوْسٍ، فَحَدَّثْتُهُ بِحَدِيثِ عَوْفِ بْنِ مَالِكٍ، فَقَالَ: صَدَقَ عَوْفٌ أَلَا أُخْبِرُكَ بِأَوَّلِ ذَلِكَ يُرْفَعُ؟ قُلْتُ: بَلَى، قَالَ: الْخُشُوعُ حَتَّى لَا تَرَى خَاشِعًا."],"takhrij":"صحيح: رواه النسائيّ في السنن الكبرى (5878) عن الربيع بن سليمان، ثنا عبدالله بن وهب، قال: سمعت اللّيث بن سعد، يقول: حدّثني إبراهيم بن أبي عبلة، عن الوليد بن عبدالرحمن الجرشيّ، عن جبير بن نفير، قال: حدّثني عوفُ بن مالك الأشجعيّ، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (5878).","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī, may Allah be pleased with him, reported: The Messenger of Allah ﷺ looked toward the sky one day and said: “This is the time when knowledge will be lifted.” A man from the Anṣār named Labīd ibn Ziyād asked: “O Messenger of Allah ﷺ, will knowledge be lifted after it has been firmly established and retained in people’s hearts?” The Messenger of Allah ﷺ said to him: “I used to consider you among the most knowledgeable people of Madinah.” He then mentioned to him the misguidance of the Jews and Christians despite the Book of Allah being in their possession. ʿAwf said: I later met Shaddād ibn Aws and related to him the ḥadīth of ʿAwf ibn Mālik. He said: “ʿAwf has spoken the truth. Shall I tell you the first part of it that will be lifted?” I said: “Yes.” He said: “Khushūʿ—humble devotion—until you will no longer see a person possessing khushūʿ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في السنن الكبرى (5878)."},{"num":1243,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَشَخَصَ بِبَصَرِهِ إِلَى السَّمَاءِ ثُمَّ قَالَ: هَذَا أَوَانُ يُخْتَلَسُ الْعِلْمُ مِنَ النَّاسِ حَتَّى لَا يَقْدِرُوا مِنْهُ عَلَى شَيْءٍ، فَقَالَ زِيَادُ بْنُ لَبِيدٍ الْأَنْصَارِيُّ: كَيْفَ يُخْتَلَسُ مِنَّا وَقَدْ قَرَأْنَا الْقُرْآنَ؟ فَوَاللَّهِ لَنَقْرَأَنَّهُ، وَلَنُقْرِئَنَّهُ نِسَاءَنَا، وَأَبْنَاءَنَا، فَقَالَ: ثَكِلَتْكَ أُمُّكَ يَا زِيَادُ إِنْ كُنْتُ لَأَعُدُّكَ مِنْ فُقَهَاءِ أَهْلِ الْمَدِينَةِ، هَذِهِ التَّوْرَاةُ وَالْإِنْجِيلُ عِنْدَ الْيَهُودِ، وَالنَّصَارَى فَمَاذَا تُغْنِي عَنْهُمْ ؟!.","قَالَ جُبَيْرٌ: فَلَقِيتُ عُبَادَةَ بْنَ الصَّامِتِ، قُلْتُ: أَلَا تَسْمَعُ إِلَى مَا يَقُولُ أَخُوكَ أَبُو الدَّرْدَاءِ؟ فَأَخْبَرْتُهُ بِالَّذِي قَالَ أَبُو الدَّرْدَاءِ، قَالَ: صَدَقَ أَبُو الدَّرْدَاءِ إِنْ شِئْتَ لَأُحَدِّثَنَّكَ بِأَوَّلِ عِلْمٍ يُرْفَعُ مِنَ النَّاسِ الْخُشُوعُ يُوشِكُ أَنْ تَدْخُلَ مَسْجِدَ جَمَاعَةٍ فَلَا تَرَى فِيهِ رَجُلًا خَاشِعًا."],"takhrij":"حسن: رواه الترمذي (2653) عن عبدالله بن عبدالرحمن، أخبرنا عبدالله بن صالح، حدّثني معاوية بن صالح، عن عبدالرحمن بن جبير بن نفير، عن أبيه جبير بن نفير، عن أبي الدّرداء، فذكره.","grade":"حسن","chapter_ar":"باب رفع العلم وظهور الجهل والفتن في آخر الزمان","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2653), who said: “This is a ḥasan gharīb ḥadīth.”","chapter_en":"The Lifting of Knowledge and the Appearance of Ignorance and Tribulations at the End of Time","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū al-Dardāʾ, may Allah be pleased with him, reported: We were with the Messenger of Allah ﷺ when he raised his gaze toward the sky and said: “This is the time when knowledge will be snatched away from the people until they will be unable to retain anything of it.” Ziyād ibn Labīd al-Anṣārī asked: “How can it be snatched away from us when we have recited the Qurʾān? By Allah, we will certainly continue to recite it and teach it to our women and children.” He said: “May your mother lose you, O Ziyād! I used to consider you among the jurists of the people of Madinah. The Torah and the Gospel are in the possession of the Jews and Christians, yet what benefit have they brought them?”","Jubayr said: I met ʿUbādah ibn al-Ṣāmit and said: “Do you not hear what your brother Abū al-Dardāʾ is saying?” I then told him what Abū al-Dardāʾ had said. He replied: “Abū al-Dardāʾ has spoken the truth. If you wish, I will tell you the first knowledge that will be lifted from the people: khushūʿ. Soon you will enter a congregational mosque and not see a single man in it possessing khushūʿ.”"]},"buhuth":{"en":["Al-Aʿẓamī said: Its chain is ḥasan.","Al-Ḥākim authenticated it (1/99) and stated the basis for his authentication. Al-Aʿẓamī said: “This is sound and acceptable reasoning, built upon the principles of the specialists in this field.”","It was also narrated from Ziyād ibn Labīd by Ibn Mājah (4048), Aḥmad (17473, 17919), Abū Khaythamah (52), and al-Ḥākim (3/590), although Sālim ibn Abī al-Jaʿd did not hear from Ziyād ibn Labīd."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2653)، وقال: «هذا حديث حسن غريب»."},{"num":1244,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أُفْتِيَ بِغَيْرِ عِلْمٍ كَانَ إِثْمُهُ عَلَى مَنْ أَفْتَاهُ."],"takhrij":"حسن: رواه أبو داود (3657) عن الحسن بن علي، حدّثنا أبو عبدالرحمن المقرئ، حدّثنا سعيد، يعني ابن أبي أيوب، ، عن بكر بن عمرو، عن مسلم بن يسار، أبي عثمان، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في كراهة الفتوى بغير علم","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (3657) and Ibn Mājah (53).","chapter_en":"What Has Been Reported Concerning the Disapproval of Giving Religious Verdicts Without Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever is given a religious verdict without knowledge, its sin is upon the one who gave him that verdict.”"]},"buhuth":{"en":["Abū Dāwūd also narrated it through another route with the addition: “Whoever advises his brother to do something while knowing that right guidance lies elsewhere has betrayed him.” This addition is weak because of ʿAmr ibn Abī Nuʿaymah.","Al-Aʿẓamī discussed the differing routes and the issue of an additional narrator in a connected chain, then cited statements of the early Muslims concerning caution in issuing religious verdicts, including the statement of Ibn ʿAbbās: “Whoever gives a verdict concerning a matter while being blind to it bears its sin,” and the statement of Ibn Masʿūd that whoever possesses knowledge should speak, and whoever does not should say: Allah knows best."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3657)، ورواه ابن ماجه (53)."},{"num":1245,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمًا يَتَدَارَءُونَ، فَقَالَ: إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِهَذَا، ضَرَبُوا كِتَابَ اللَّهِ بَعْضَهُ بِبَعْضٍ، وَإِنَّمَا نَزَلَ كِتَابُ اللَّهِ يُصَدِّقُ بَعْضُهُ بَعْضًا، فَلَا تُكَذِّبُوا بَعْضَهُ بِبَعْضٍ، فَمَا عَلِمْتُمْ مِنْهُ فَقُولُوا، وَمَا جَهِلْتُمْ فَكِلُوهُ إِلَى عَالِمِهِ."],"takhrij":"حسن: رواه الإمام أحمد (6741) عن عبد الرزّاق - وهو في مصنفه (20367)، قال: أخبرنا معمر، عن الزّهريّ، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من المراء والجدال في كتاب الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (6741) from ʿAbd al-Razzāq, and it is also found in his Muṣannaf (20367).","chapter_en":"Warning Against Contentious Disputation and Arguing Concerning the Book of Allah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather: The Prophet ﷺ heard some people disputing and contradicting one another, so he said: “Those before you were destroyed because of this: they set one part of the Book of Allah against another. The Book of Allah was revealed such that one part confirms another, so do not use one part to declare another false. Whatever you know of it, speak concerning it; and whatever you do not know, refer it to one who knows it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11767],"tks":"حسن: رواه الإمام أحمد (6741) عن عبد الرزاق، وهو في مصنفه (20367)."},{"num":1246,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمِرَاءُ فِي الْقُرْآنِ كُفْرٌ."],"takhrij":"صحيح: رواه أبو داود (4603) عن أحمد بن حنبل، حدثنا يزيد، يعني ابن هارون، أخبرنا محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من المراء والجدال في كتاب الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4603).","chapter_en":"Warning Against Contentious Disputation and Arguing Concerning the Book of Allah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “Contentious disputation concerning the Qurʾān is disbelief.”"]},"buhuth":{"en":["Aḥmad (7508) narrated it with the wording: “Disputation concerning the Qurʾān is disbelief,” with a strong chain.","Aḥmad (7989) narrated a longer wording: “The Qurʾān was revealed according to seven modes; disputation concerning the Qurʾān is disbelief”—three times—“so act upon what you know of it, and refer what you do not know to one who knows it.”","Ibn Ḥibbān (74) authenticated it, and al-Bazzār narrated an expanded wording in Kashf al-Astār (2313)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4603)."},{"num":1247,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تَلَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الْآيَةَ: ﴿هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ هُنَّ أُمُّ الْكِتَابِ وَأُخَرُ مُتَشَابِهَاتٌ فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ وَمَا يَعْلَمُ تَأْوِيلَهُ إِلَّا اللَّهُ وَالرَّاسِخُونَ فِي الْعِلْمِ يَقُولُونَ آمَنَّا بِهِ كُلٌّ مِنْ عِنْدِ رَبِّنَا وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ﴾ [سورة آل عمران: 7]، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِذَا رَأَيْتِ الَّذِينَ يَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ فَأُولَئِكِ الَّذِينَ سَمَّى اللَّهُ فَاحْذَرُوهُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4547)، ومسلم في العلم (2665) كلاهما عن عبدالله بن مسلمة، حدّثنا يزيد بن إبراهيم التسْتريّ، عن ابن أبي مليكة، عن القاسم بن محمد، عن عائشة، فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن تتبع المتشابه من القرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4547) and Muslim (2665).","chapter_en":"The Prohibition of Pursuing the Ambiguous Verses of the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: The Messenger of Allah ﷺ recited: “He is the One who sent down to you the Book. In it are verses that are precise and decisive—they are the foundation of the Book—and others that are ambiguous. As for those in whose hearts is deviation, they follow what is ambiguous from it, seeking tribulation and seeking its interpretation. No one knows its interpretation except Allah. And those firmly grounded in knowledge say, ‘We believe in it; all of it is from our Lord.’ And none take heed except people of understanding.” [Sūrat Āl ʿImrān 3:7] Then the Messenger of Allah ﷺ said: “When you see those who follow what is ambiguous from it, they are the ones whom Allah has named, so beware of them.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4547)، ومسلم (2665)."},{"num":1248,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اقْرَءُوا الْقُرْآنَ مَا ائْتَلَفَتْ عَلَيْهِ قُلُوبُكُمْ فَإِذَا اخْتَلَفْتُمْ فِيهِ فَقُومُوا."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل القرآن (5060)، ومسلم في العلم (2667) كلاهما من حديث أبي عمران الجوني، عن جندب بن عبدالله البجليّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن تتبع المتشابه من القرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5060) and Muslim (2667).","chapter_en":"The Prohibition of Pursuing the Ambiguous Verses of the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Jundub ibn ʿAbdullāh al-Bajalī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Recite the Qurʾān as long as your hearts remain united concerning it. But when you begin to differ concerning it, then rise and leave it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5060)، ومسلم (2667)."},{"num":1249,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّهُ سَمِعَ رَجُلًا يَقْرَأُ آَيَةً سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خِلَافَهَا، فَأَخَذْتُ بِيَدِهِ فَانْطَلَقْتُ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كِلَاكُمَا مُحْسِنٌ فَاقْرَءَا أَكْبَرُ عِلْمِي قَالَ: فَإِنَّ مَنْ كَانَ قَبْلَكُمُ اخْتَلَفُوا فَأَهْلَكَهُمْ."],"takhrij":"صحيح: رواه البخاريّ في فضائل القرآن (5062) عن سليمان بن حرب، حدّثنا شعبة، عن عبد الملك بن ميسرة، عن النـزال بن سبرة، عن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن تتبع المتشابه من القرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (5062).","chapter_en":"The Prohibition of Pursuing the Ambiguous Verses of the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, heard a man reciting a verse differently from the way he had heard the Prophet ﷺ recite it. He took the man by the hand and brought him to the Prophet ﷺ. The Prophet ﷺ said: “Both of you have recited correctly, so recite.” Then he said: “Those who came before you differed, and so they were destroyed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5062)."},{"num":1250,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: هَجَّرْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا قَالَ: فَسَمِعَ أَصْوَاتَ رَجُلَيْنِ اخْتَلَفَا فِي آيَةٍ، فَخَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعْرَفُ فِي وَجْهِهِ الْغَضَبُ فَقَالَ: إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِاخْتِلَافِهِمْ فِي الْكِتَابِ."],"takhrij":"صحيح: رواه مسلم في العلم (2666) عن أبي كامل فضيل بن حسين الجحدريّ، حدّثنا حماد بن زيد، حدّثنا أبو عمران الجونيّ، قال: كتب إليَّ عبدالله ابن رباح الأنصاريّ، أنّ عبدالله بن عمرو، قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن تتبع المتشابه من القرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2666).","chapter_en":"The Prohibition of Pursuing the Ambiguous Verses of the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: I went early to the Messenger of Allah ﷺ one day. He heard the voices of two men who had disagreed concerning a verse. The Messenger of Allah ﷺ came out, and anger could be seen upon his face. He said: “Those who came before you were destroyed only because of their disagreement concerning the Book.”"]}},"tuhfa":{},"full":1,"rep":[11746],"tks":"صحيح: رواه مسلم (2666)."},{"num":1251,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: كُنَّا جُلُوسًا عَلَى بَابِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَتَذَاكَرُ، يَنْزِعُ هَذَا بِآيَةٍ ويَنْزِعُ هَذَا بِآيَةٍ، فَخَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنَّمَا تَفَقَّأَ فِي وَجْهِهِ حَبُّ الرُّمَّانِ، فَقَالَ: يَا هَؤُلَاءِ أَبِهَذَا بُعِثْتُمْ؟ أَمْ بِهَذَا أُمِرْتُمْ؟ لَا تَرْجِعُوا بَعْدِي كُفَّارًا، يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ."],"takhrij":"حسن: رواه البزّار-كشف الأستار (179)، والطبراني في الكبير (5442) كلاهما من طريق عبدالرحمن بن المبارك العيشيّ، ثنا سويد أبو حاتم، عن قتادة، عن أبي نضرة، عن أبي سعيد فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن تتبع المتشابه من القرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (179) and al-Ṭabarānī (6/45).","chapter_en":"The Prohibition of Pursuing the Ambiguous Verses of the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Abū Saʿīd, may Allah be pleased with him, reported: We were sitting at the door of the Messenger of Allah ﷺ discussing matters. One person would draw an argument from one verse, and another would draw an argument from another verse. The Messenger of Allah ﷺ came out to us, and it was as though pomegranate seeds had burst upon his face because of the intensity of his anger. He said: “O people! Is this what you were sent for? Or is this what you were commanded to do? Do not return after me as disbelievers, striking the necks of one another.”"]},"buhuth":{"en":["The expression “one would draw from a verse” means that each person would derive an argument or meaning from a verse.","The expression “as though pomegranate seeds had burst upon his face” is a figurative description of the visible change in the facial features of the Prophet ﷺ and the intensity of his anger."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (179)، والطبراني (5442)."},{"num":1252,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ، سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ مُحَرِّمَ الْحَلَالِ كَمُحِلِّ الْحَرَامِ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (٧٩٨٢)، مجمع البحرين (268): ثنا موسى بن هارون، ثنا أبو موسى الأنصاريّ، ثنا عاصم بن عبد العزيز الأشجعيّ، عن الحارث بن عبدالرحمن بن أبي ذباب، عن عبدالله بن عبدالله بن عمر، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من تحريم الحلال، وتحليل الحرام","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (268).","chapter_en":"Warning Against Declaring the Lawful Unlawful and the Unlawful Lawful","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported that he heard the Messenger of Allah ﷺ say: “Indeed, the one who declares the lawful unlawful is like the one who declares the unlawful lawful.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَلَا تَقُولُوا لِمَا تَصِفُ أَلْسِنَتُكُمُ الْكَذِبَ هَذَا حَلَالٌ وَهَذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللَّهِ الْكَذِبَ ۚ إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ﴾","[النحل: ١١٦]"],"en":["Allah Most High said:","“And do not say, based upon the falsehood uttered by your tongues, ‘This is lawful and this is unlawful,’ thereby fabricating lies against Allah. Indeed, those who fabricate lies against Allah will not succeed.”","[Sūrat al-Naḥl 16:116]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط، كما في مجمع البحرين (268)."},{"num":1253,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَامَ مُوسَى النَّبِيُّ خَطِيبًا فِي بَنِي إِسْرَائِيلَ، فَسُئِلَ أَيُّ النَّاسِ أَعْلَمُ؟ فَقَالَ: أَنَا أَعْلَمُ، فَعَتَبَ اللَّهُ عَلَيْهِ إِذْ لَمْ يَرُدَّ الْعِلْمَ إِلَيْهِ، فَأَوْحَى اللَّهُ إِلَيْهِ أَنَّ عَبْدًا مِنْ عِبَادِي بِمَجْمَعِ الْبَحْرَيْنِ هُوَ أَعْلَمُ مِنْكَ، قَالَ: يَا رَبِّ، وَكَيْفَ بِهِ؟ فَقِيلَ لَهُ: احْمِلْ حُوتًا فِي مِكْتَلٍ، فَإِذَا فَقَدْتَهُ فَهُوَ ثَمَّ. فَذَكَرَ الْحَدِيثَ بِطُولِهِ فِي اجْتِمَاعِهِ بِالْخَضِر إلَى أَنْ قَالَ: فَانْطَلَقَا يَمْشِيَانِ عَلَى سَاحِلِ الْبَحْرِ لَيْسَ لَهُمَا سَفِينَةٌ، فَمَرَّتْ بِهِمَا سَفِينَةٌ فَكَلَّمُوهُمْ أَنْ يَحْمِلُوهُمَا، فَعُرِفَ الْخَضِرُ فَحَمَلُوهُمَا بِغَيْرِ نَوْلٍ، فَجَاءَ عُصْفُورٌ فَوَقَعَ عَلَى حَرْفِ السَّفِينَةِ فَنَقَرَ نَقْرَةً أَوْ نَقْرَتَيْنِ فِي الْبَحْرِ، فَقَالَ الْخَضِرُ: يَا مُوسَى، مَا نَقَصَ عِلْمِي وَعِلْمُكَ مِنْ عِلْمِ اللَّهِ إِلَّا كَنَقْرَةِ هَذَا الْعُصْفُورِ فِي الْبَحْرِ... الْحَدِيثَ بِطُولِهِ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (122)، ومسلم في الفضائل (2380) كلاهما من حديث سفيان بن عيينة، حدثنا عمرو بن دينار، عن سعيد بن جبير، قال: قلت لابن عباس: إنّ نوفاً البكاليّ يزعم أنّ موسى عليه السّلام صاحب بني إسرائيل ليس هو موسى صاحب الخضر عليه السلام! فقال: كذب عدوّ الله، سمعتُ أبي بن كعب يقول: سمعت رسول الله صلى الله عليه وسلم يقول (فذكر الحديث بطوله)، وسيأتي في موضعه بكامله.","grade":"متفق عليه","chapter_ar":"باب الترهيب من الدعوى في العلم والقرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (122) and Muslim (2380).","chapter_en":"Warning Against Claiming Status in Knowledge and the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ubayy ibn Kaʿb, may Allah be pleased with him, reported from the Prophet ﷺ: “Mūsā peace be upon him stood to address the Children of Israel and was asked, ‘Who is the most knowledgeable of people?’ He replied, ‘I am the most knowledgeable.’ Allah reproached him because he did not attribute knowledge back to Him. Allah then revealed to him: ‘Indeed, I have a servant at the meeting place of the two seas who is more knowledgeable than you.’ Mūsā asked: ‘My Lord, how can I find him?’ He was told: ‘Carry a fish in a basket. When you lose it, he will be there.’” The lengthy narration then mentions his meeting with al-Khiḍr, until it states: “They set out walking along the seashore, having no boat. A boat passed them, and they spoke to its people asking them to carry them. Al-Khiḍr was recognized, so they carried them without charging any fare. A small bird came and landed on the edge of the boat and pecked once or twice into the sea. Al-Khiḍr said: ‘O Mūsā, my knowledge and your knowledge compared with the knowledge of Allah are no more than what this bird has taken from this sea with its peck.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (122)، ومسلم (2380)."},{"num":1254,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَظْهَرُ الإِسْلامُ حَتَّى تَخُوضَ الْخَيْلُ الْبِحَارَ، وَحَتَّى يَخْتِلَفَ التُّجَّارُ فِي الْبَحْرِ، ثُمَّ يَظْهَر قَوْمٌ يَقْرَءُونَ الْقُرْآنَ يَقُولُونَ: مَنْ أَقْرَأُ مِنَّا، مَنْ أَفْقَهُ مِنَّا؟ ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ فِي أُولَئِكَ خَيْرٌ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ: أُولَئِكَ وَقُودُ النَّارِ، أُولَئِكَ مِنْكُمْ مِنْ هَذِهِ الأُمَّةِ."],"takhrij":"حسن: رواه البزّار-كشف الأستار (173) عن عبدالله بن شبيب، ثنا إسحاق بن محمد الفروي، ثنا عبدالله بن زيد بن أسلم، عن أبيه، عن جدّه، عن عمر، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من الدعوى في العلم والقرآن","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (173).","chapter_en":"Warning Against Claiming Status in Knowledge and the Qurʾān","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Islam will spread until horses wade through the seas and merchants contend upon the sea. Then there will appear people who recite the Qurʾān and say: ‘Who among us recites better? Who among us possesses greater understanding?’” Then the Messenger of Allah ﷺ asked: “Is there any good in those people?” They replied: “Allah and His Messenger know best.” He said: “Those are fuel for the Fire. Those are from among you—from this Ummah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (173)."},{"num":1255,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَكْذِبُوا عَلَيَّ، فَإِنَّهُ مَنْ كَذَبَ عَلَيَّ فَلْيَلِجْ النَّارَ."],"takhrij":"صحيح: رواه البخاريّ في العلم (106)، ومسلم في المقدمة (1) كلاهما من طرق عن شعبة، عن منصور، عن ربعي بن حراش، أنّه سمع عليّاً، فذكره. واللّفظ للبخاريّ، ولفظ مسلم مثله إلاّ في قوله: فليلج النار. فعند مسلم: يلج النار.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-ʿIlm (106) and Muslim in his Introduction (1). The wording is that of al-Bukhārī; Muslim has the same wording except that where al-Bukhārī has “then let him enter the Fire,” Muslim has “he will enter the Fire.”","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib, may Allah be pleased with him, reported that the Prophet ﷺ said: “Do not lie about me, for whoever lies about me shall enter the Fire.”"]}},"tuhfa":{},"full":1,"rep":[9638],"tks":"صحيح: رواه البخاري (106)، ومسلم (1)، واللفظ للبخاري، ولفظ مسلم مثله إلا في قوله: «فليلج النار»، فعند مسلم: «يلج النار»."},{"num":1256,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: تَسَمَّوْا بِاسْمِي وَلَا تَكْتَنُوا بِكُنْيَتِي، وَمَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي، فَإِنَّ الشَّيْطَانَ لَا يَتَمَثَّلُ فِي صُورَتِي، وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في العلم (110)، ومسلم في المقدمة (3) كلاهما من طريق أبي عوانة، عن أبي حصين، عن أبي صالح، عن أبي هريرة، فذكر الحديث. واللّفظ للبخاريّ أمّا مسلم فاكتفى بالجملة الأخيرة فقط.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (110) and Muslim in his Introduction (3). The wording is that of al-Bukhārī.","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “Name yourselves with my name, but do not take my kunyah. Whoever sees me in a dream has truly seen me, for Satan cannot assume my form. And whoever deliberately lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (110)، ومسلم (3)، واللفظ للبخاري."},{"num":1257,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: إِنَّهُ لَيَمْنَعُنِي أَنْ أُحَدِّثَكُمْ حَدِيثًا كَثِيرًا، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَعَمَّدَ عَلَيَّ كَذِبًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في العلم (108) ثنا أبو معمر، قال: حدّثنا عبد الوارث، عن عبد العزيز، قال أنس.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-ʿIlm (108).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: “What prevents me from narrating many ḥadīths to you is that the Prophet ﷺ said: ‘Whoever deliberately attributes a lie to me, let him take his seat in the Fire.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (108)."},{"num":1258,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ، فَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاري في الجنائز (1291)، ومسلم في المقدمة (4) من طريق علي بن ربيعة الأسدي، عن المغيرة بن شعبة، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (1291) and Muslim in his Introduction (4).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Al-Mughīrah, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Indeed, lying about me is not like lying about anyone else. Whoever lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1291)، ومسلم (4)."},{"num":1259,"demo":false,"sanad":"","matn":["عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَذَبَ عَلَيَّ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في العلم (107) عن أبي الوليد، قال: حدّثنا شعبة، عن جامع بن شدّاد، عن عامر بن عبدالله بن الزبير، عن أبيه، قلت للزبير: إنّي لا أسمعك تحدِّث عن رسول الله صلى الله عليه وسلم، كما يحدِّث فلان وفلان، قال: أما إنّي لم أفارقه، ولكن سمعته يقول (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (107).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Al-Zubayr ibn al-ʿAwwām, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Whoever lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (107)."},{"num":1260,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ يَقُلْ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في العلم (109) عن مكي بن إبراهيم، قال حدّثنا يزيد بن أبي عبيد، عن سلمة، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (109).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ, may Allah be pleased with him, said: I heard the Prophet ﷺ say: “Whoever attributes to me what I did not say, let him take a seat in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (109)."},{"num":1261,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَلِّغُوا عَنِّي وَلَوْ آيَةً وَحَدِّثُوا عَنْ بَنِي إِسْرَائِيلَ وَلَا حَرَجَ وَمَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه البخاريّ في أحاديث الأنبياء (3461) وابن حبان (6256)، والترمذي (2669)، والدارمي (559)، والإمام أحمد (6486)كلهم من طريق الأوزاعيّ, عن حسان بن عطية، عن أبي كبشة، عن عبدالله بن عمرو، قال: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3461).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported that the Prophet ﷺ said: “Convey from me, even if only one verse. Narrate from the Children of Israel, and there is no harm in doing so. And whoever deliberately lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"rep":[1181,8176,8275],"tks":"صحيح: رواه البخاري (3461)."},{"num":1262,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ بَيْتًا فِي النَّارِ."],"takhrij":"صحيح: رواه الإمام أحمد (4742)، والبزّار-كشف الأستار (210)، والطّبرانيّ في الأوسط (8033)، مجمع البحرين (296)، وفي الكبير (13153، 13154) من طرق عن عبيد الله بن عمر، عن أبي بكر بن سالم، عن أبيه (سالم بن عبدالله ابن عمر)، عن جدّه، فذكر نحوه.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (4742), al-Bazzār in Kashf al-Astār (210), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (296), and in al-Muʿjam al-Kabīr (13153, 13154). The wording is that of al-Ṭabarānī.","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported that the Prophet ﷺ said: “Whoever deliberately lies about me, let him take a house in the Fire.”"]},"buhuth":{"en":["Aḥmad’s wording is:","“Indeed, the one who lies about me will have a house built for him in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (4742)، والبزار في كشف الأستار (210)، والطبراني في الأوسط كما في مجمع البحرين (296)، وفي الكبير (13153، 13154)، واللفظ للطبراني."},{"num":1263,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى هَذَا الْمِنْبَرِ: يَا أَيُّهَا النَّاسُ إِيَّاكُمْ وَكَثْرَةَ الْحَدِيثِ عَنِّي، مَنْ قَالَ عَلَيَّ فَلَا يَقُولَنَّ إِلَّا حَقًّا أَوْ صِدْقًا، فَمَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"حسن: رواه ابن ماجه (35) عن أبي بكر بن أبي شيبة، ثنا يحيى بن يعلى التّميميّ، عن محمد بن إسحاق، عن معبد بن كعب، عن أبي قتادة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (35).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Qatādah, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say from this pulpit: “O people, beware of excessive narration from me. Whoever narrates from me should say nothing except what is true and truthful. Whoever attributes to me what I did not say, let him take his seat in the Fire.”"]},"buhuth":{"en":["Al-Aʿẓamī said: Its chain is ḥasan on account of Maʿbad ibn Kaʿb, who was declared trustworthy by authorities whose accreditation is relied upon. Muḥammad ibn Isḥāq is also in its chain; he explicitly stated hearing in Aḥmad’s narration (22538), removing the concern of tadlīs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (35)."},{"num":1264,"demo":false,"sanad":"","matn":["عَنْ هِشَامِ بْنِ أَبِي رُقَيَّةَ قَالَ: سَمِعْتُ مَسْلَمَةَ بْنَ مُخَلَّدٍ، وَهُوَ قَاعِدٌ عَلَى الْمِنْبَرِ يَخْطُبُ النَّاسَ وَهُوَ يَقُولُ: يَا أَيُّهَا النَّاسُ أَمَّا لَكُمْ فِي الْعَصْبِ وَالْكَتَّانِ مَا يَكْفِيكُمْ عَنِ الْحَرِيرِ، وَهَذَا رَجُلٌ فِيكُمْ يُخْبِرُكُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُمْ يَا عُقْبَةُ، فَقَامَ عُقْبَةُ بْنُ عَامِرٍ وَأَنَا أَسْمَعُ، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ. وَأَشْهَدُ أَنِّي سَمِعَتْهُ يَقُولُ: مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا حَرَّمَهُ أَنْ يَلْبَسَهُ فِي الْآخِرَةِ."],"takhrij":"صحيح: رواه أحمد (17431)، وأبو يعلى (1751) كلاهما عن هارون بن معروف، ثنا ابن وهب، أخبرني عمر (هو ابن الحارث المصريّ)، أنّ هشام بن أبي رقية قال: فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (17431) and Abū Yaʿlā (1751).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Hishām ibn Abī Ruqayyah reported: I heard Maslamah ibn Mukhallad, while he was seated on the pulpit addressing the people, say: “O people, is there not enough for you in striped cloth and linen to suffice you instead of silk? Here is a man among you who will inform you from the Messenger of Allah ﷺ. Stand, O ʿUqbah.” So ʿUqbah ibn ʿĀmir, may Allah be pleased with him, stood while I was listening and said: I heard the Messenger of Allah ﷺ say: “Whoever deliberately lies about me, let him take his seat in the Fire.” And I testify that I heard him say: “Whoever wears silk in this world will be deprived of wearing it in the Hereafter.”"]},"buhuth":{"en":["Its chain is ṣaḥīḥ; its narrators are trustworthy narrators of the two Ṣaḥīḥ collections except Hishām ibn Abī Ruqayyah, who is trustworthy. Ibn Ḥibbān also authenticated it and narrated it as no. 5436 through the route of Ibn Wahb."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17431)، وأبو يعلى (1751)."},{"num":1265,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: بَعَثَ إِلَيَّ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ، فَأَتَيْتُهُ فَقَالَ: مَا أَحَادِيثُ تُحَدِّثُهَا وَتَرْوِيهَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا نَجِدُهَا فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ؟ تُحَدِّثُ أَنَّ لَهُ حَوْضًا فِي الْجَنَّةِ ! قَالَ: قَدْ حَدَّثَنَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَوَعَدَنَاهُ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ شَيْخٌ قَدْ خَرِفْتَ، قَالَ: إِنِّي قَدْ سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ جَهَنَّمَ، وَمَا كَذَبْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه الإمام أحمد (19266)، والطبرانيّ في الكبير (5021)، والبزار - كشف الأستار (217)، كلّهم من طريق أبي حيان التّيميّ، حدّثني يزيد بن حيان التّيميّ، قال: حدّثنا زيد بن أرقم في مجلسه، قال: بعث إلى عبيد الله بن زياد، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (19266), al-Ṭabarānī in al-Muʿjam al-Kabīr (5/203–204), and al-Bazzār in Kashf al-Astār (217).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, said: ʿUbaydullāh ibn Ziyād sent for me, so I came to him. He said: “What are these reports that you narrate from the Messenger of Allah ﷺ which we do not find in the Book of Allah, Mighty and Majestic? You narrate that he has a Pool in Paradise!” I said: “The Messenger of Allah ﷺ informed us of it and promised it to us.” He said: “You have lied. Rather, you are an old man who has become senile.” Zayd said: “My two ears certainly heard it, and my heart retained it, from the Messenger of Allah ﷺ, who said: ‘Whoever deliberately lies about me, let him take his seat in Hell.’ And I have not lied about the Messenger of Allah ﷺ.”"]},"buhuth":{"en":["The expression “you have become senile” means that a man’s intellect has deteriorated because of old age."]}},"tuhfa":{},"full":1,"dr":1,"rep":[856],"tks":"صحيح: رواه أحمد (19266)، والطبراني في الكبير (5/203–204)، والبزار في كشف الأستار (217)."},{"num":1266,"demo":false,"sanad":"","matn":["عَنْ رِيَاحِ بنِ الْحَارِثِ قَالَ: كُنَّا عِنْدَ الْمُغِيرَةِ بْنِ شُعْبَةَ وَهُوَ فِي الْمَسْجِدِ وَعِنْدَهُ أَهْلُ الْكُوفَةِ، فَجَاءَ سَعِيدُ بْنُ زَيْدٍ فَأَوْسَعَ لَهُ الْمُغِيرَةُ، فَقَالَ: هَاهُنَا فَاجْلِسْ، فَأَجْلَسَهُ مَعَهُ عَلَى السَّرِيرِ، فَقَالَ سَعِيدُ بْنُ زَيْدٍ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ كَذِبًا عَلَيَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ، مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه أبو يعلى في المسند (966)، و المطالب (3113)، عن إبراهيم بن الحجاج، ثنا عبد الواحد بن زياد، ثنا صدقة بن المثنى، حدثني رياح بن الحارث، فذكره.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Yaʿlā in his Musnad, as cited in al-Maṭālib al-ʿĀliyah (3113).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Riyāḥ ibn al-Ḥārith reported: We were with al-Mughīrah ibn Shuʿbah may Allah be pleased with him in the mosque, and some of the people of Kūfah were with him. Saʿīd ibn Zayd, may Allah be pleased with him, came, so al-Mughīrah made room for him and said: “Sit here.” He seated him beside himself on the couch. Saʿīd ibn Zayd may Allah be pleased with him then said: I heard the Messenger of Allah ﷺ say: “Indeed, lying about me is not like lying about anyone else. Whoever deliberately lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى في المسند، كما في المطالب العالية (3113)."},{"num":1267,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ قَالَ: مَا يَمْنَعُنِي أَنْ أُحَدِّثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أَكُونَ أَوْعَى أَصْحَابِهِ عَنْهُ، وَلَكِنِّي أَشْهَدُ لَسَمِعْتُهُ يَقُولُ: مَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"حسن: رواه أحمد (469) من طريقين، عن عبدالرحمن بن أبي الزّناد، عن أبيه، عن عامر بن سعد، قال: سمعت عثمان بن عفّان، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (469).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿUthmān ibn ʿAffān, may Allah be pleased with him, said: “What prevents me from narrating from the Messenger of Allah ﷺ is not that I was less able than his Companions to retain what he said. Rather, I testify that I heard him say: ‘Whoever attributes to me what I did not say, let him take his seat in the Fire.’”"]},"buhuth":{"en":["It was also narrated by Aḥmad (507) and al-Bazzār (384) through another route.","Al-Haythamī stated that the narrators of one route are narrators of the Ṣaḥīḥ collections. Al-Aʿẓamī noted that one route has a discontinuity concerning whether Maḥmūd ibn Labīd heard from ʿUthmān, but the routes strengthen one another."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (469)."},{"num":1268,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مِنْ أَفْرَى الْفِرَى مَنِ ادَّعَى إِلَى غَيْرِ وَالِدِهِ، وَمِنْ أَفْرَى الْفِرَى مَنْ أَرَى عَيْنَيْهِ مَا لَمْ تَرَ، وَمِنْ أَفْرَى الْفِرَى مَنْ قَالَ عَلَيَّ مَا لَمْ أَقُلْ."],"takhrij":"صحيح: رواه البزّار-كشف الأستار (211): حدّثنا محمد بن مسكين، ثنا سعيد بن أبي مريم، ثنا نافع بن يزيد، عن الوليد بن أبي الوليد، عن يزيد بن الهاد، عن عبدالله بن دينار، عن ابن عمر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bazzār (211).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Among the greatest fabrications is for a person to claim lineage to someone other than his father; among the greatest fabrications is for a person to make his eyes claim to have seen what they did not see; and among the greatest fabrications is for a person to attribute to me what I did not say.”"]},"buhuth":{"en":["Al-Bukhārī (7043) narrated it in abbreviated form:","“Among the greatest fabrications is for a person to make his eyes claim to have seen what they did not see.”","The word al-firā is the plural of firyah, meaning a lie or fabrication.","The statement, “one who makes his eyes claim to have seen what they did not see,” means that a person says, “I saw such-and-such in a dream,” although he actually saw nothing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار (211)."},{"num":1269,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا لِيُضِلَّ بِهِ النَّاسَ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"حسن: رواه أبو بكر البزّار-كشف الأستار (209) عن عبدالله بن سعيد، عن يونس بن بكير، ثنا الأعمش، عن طلحة بن مصرِّف، عن عمرو بن شرحبيل، عن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Bakr al-Bazzār in Kashf al-Astār (209).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported that the Prophet ﷺ said: “Whoever deliberately lies about me in order to mislead people, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو بكر البزار في كشف الأستار (209)."},{"num":1270,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ."],"takhrij":"صحيح: رواه أحمد (11404)، وأبو يعلى (1229)، والطبرانيّ في جزء من كذب عليَّ متعمّداً (ص89) كلّهم من حديث أبي مسلمة، أنّه سمع أبا نضرة يحدّث عن أبي سعيد الخدريّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الترهيب من الكذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (11404), Abū Yaʿlā (1229), and al-Ṭabarānī in his treatise Man Kadhaba ʿAlayya Mutaʿammidan (p. 89).","chapter_en":"Warning Against Lying About the Prophet ﷺ","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported that the Prophet ﷺ said: “Whoever deliberately lies about me, let him take his seat in the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (11404)، وأبو يعلى (1229)، والطبراني في جزء «من كذب علي متعمدا» (ص 89)."},{"num":1271,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: إِنَّ النَّاسَ يَقُولُونَ أَكْثَرَ أَبُو هُرَيْرَةَ، وَلَوْلَا آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا، ثُمَّ يَتْلُو: ﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ﴾ إِلَى قَوْلِهِ: ﴿الرَّحِيمُ﴾ [البقرة: 159، 160]، إِنَّ إِخْوَانَنَا مِنَ الْمُهَاجِرِينَ كَانَ يَشْغَلُهُمْ والصَّفْقُ بِالْأَسْوَاقِ، وَإِنَّ إِخْوَانَنَا مِنَ الْأَنْصَارِ كَانَ يَشْغَلُهُمُ الْعَمَلُ فِي أَمْوَالِهِمْ، وَإِنَّ أَبَا هُرَيْرَةَ كَانَ يَلْزَمُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِبَعِ بَطْنِهِ، وَيَحْضُرُ مَا لَا يَحْضُرُونَ، وَيَحْفَظُ مَا لَا يَحْفَظُونَ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (118)، ومسلم في فضائل الصحابة (2492) كلاهما من طرق عن الزّهريّ، عن الأعرج، عن أبي هريرة، فذكره. واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب كراهية منع العلم، وهو علم الكتاب والسنة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (118) and Muslim (2492). The wording is that of al-Bukhārī.","chapter_en":"Disapproval of Withholding Knowledge—Namely, Knowledge of the Book and the Sunnah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: People say, “Abū Hurayrah narrates too much.” Were it not for two verses in the Book of Allah, I would not have narrated any ḥadīth. He then recited: “Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Book—those are cursed by Allah and cursed by those who curse…” through His saying, “the Most Merciful.” [Sūrat al-Baqarah 2:159–160] He then said: Our brothers among the Muhājirūn were occupied with trading in the markets, and our brothers among the Anṣār were occupied with working upon their property, while Abū Hurayrah remained close to the Messenger of Allah ﷺ for enough food to fill his stomach. He attended what they did not attend and memorized what they did not memorize."]},"intro":{"ar":["قال الله تعالى:","﴿إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنْزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى مِنْ بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ أُولَئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ﴾","[البقرة: ١٥٩]","وقال تعالى:","﴿وَإِذْ أَخَذَ اللَّهُ مِيثَاقَ الَّذِينَ أُوتُوا الْكِتَابَ لَتُبَيِّنُنَّهُ لِلنَّاسِ وَلَا تَكْتُمُونَهُ فَنَبَذُوهُ وَرَاءَ ظُهُورِهِمْ وَاشْتَرَوْا بِهِ ثَمَنًا قَلِيلًا فَبِئْسَ مَا يَشْتَرُونَ﴾","[آل عمران: ١٨٧]"],"en":["Allah Most High said:","“Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Book—those are cursed by Allah and cursed by those who curse.”","[Sūrat al-Baqarah 2:159]","And Allah Most High said:","“And when Allah took the covenant of those who were given the Book: ‘You must make it clear to the people and not conceal it.’ But they cast it behind their backs and exchanged it for a small price. Miserable indeed is what they purchased.”","[Sūrat Āl ʿImrān 3:187]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (118)، ومسلم (2492)، واللفظ للبخاري."},{"num":1272,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سُئِلَ عَنْ عِلْمٍ عَلِمَهُ ثُمَّ كَتَمَهُ أُلْجِمَ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنْ نَارٍ."],"takhrij":"صحيح: رواه أبو داود (3658)، والترمذيّ (2649)، وابن ماجه (261) كلّهم من طرق عن علي بن الحكم، عن عطاء (وهو ابن أبي رباح)، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية منع العلم، وهو علم الكتاب والسنة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3658), al-Tirmidhī (2649), and Ibn Mājah (261).","chapter_en":"Disapproval of Withholding Knowledge—Namely, Knowledge of the Book and the Sunnah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever is asked about knowledge and then conceals it will be bridled on the Day of Resurrection with a bridle of fire.”"]},"buhuth":{"en":["Al-Tirmidhī said: “A ḥasan ḥadīth.”","It was also narrated by Aḥmad (2/263), authenticated by Ibn Ḥibbān (95), and narrated by al-Ḥākim (1/101). Al-Ḥākim discussed whether ʿAṭāʾ heard from Abū Hurayrah, and al-Aʿẓamī discussed the routes of the report and the evidence that strengthens them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3658)، والترمذي (2649)، وابن ماجه (261)."},{"num":1273,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنّ رَسُولَ اللَّهِ صَلَّى الِلَّهِ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَتَمَ عِلْمًا أَلْجَمَهُ الِلَّهِ يَوْمَ الْقِيَامَةِ بِلِجَامٍ مِنْ نَارٍ."],"takhrij":"حسن: رواه ابن حبان (96)، والحاكم (346)، والبيهقيّ في المدخل (575) كلّهم من طريق ابن وهب، عن عبدالله بن عياش بن عباس، عن أبيه، عن أبي عبدالرحمن الحبليّ، عن عبدالله بن عمرو، فذكر الحديث.","grade":"حسن","chapter_ar":"باب كراهية منع العلم، وهو علم الكتاب والسنة","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān (96), al-Ḥākim (346), and al-Bayhaqī in al-Madkhal (575).","chapter_en":"Disapproval of Withholding Knowledge—Namely, Knowledge of the Book and the Sunnah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Whoever conceals knowledge, Allah will bridle him on the Day of Resurrection with a bridle of fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (96)، والحاكم (346)، والبيهقي في المدخل (575)."},{"num":1274,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى الِلَّهِ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الَّذِي يَتَعَلَّمُ الْعِلْمَ، ثُمَّ لَا يُحَدِّثُ بِهِ، كَمَثَلِ الَّذِي يَكْنِزُ الْكَنْزَ، فَلَا يُنْفِقُ مِنْهُ."],"takhrij":"حسن: رواه الطّبرانيّ في الأوسط (689)، وابن عبد البر في جامع بيان العلم (774) كلاهما من حديث ابن وهب، قال: حدّثني ابن لهيعة، عن درّاج أبي السّمح، عن أبي الهيثم وعبدالرحمن بن حُجيرة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب كراهية من تعلَّم العلم ثم لا يحدِّث به","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (689) and Ibn ʿAbd al-Barr in Jāmiʿ Bayān al-ʿIlm (774).","chapter_en":"Disapproval of One Who Learns Knowledge and Then Does Not Convey It","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The likeness of one who learns knowledge and then does not convey it is like one who hoards a treasure and does not spend from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (689)، وابن عبد البر في جامع بيان العلم (774)."},{"num":1275,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم:  كَفَى بِالْمَرْءِ كَذِبًا، أَنْ يُحَدِّثَ بِكُلِّ مَا سَمِعَ."],"takhrij":"صحيح: رواه مسلم في المقدمة (5) عن أبي بكر بن أبي شيبة، حدثنا علي بن حفص، حدثنا شعبة، عن خبيب بن عبدالرحمن، عن حفص بن عاصم، عن أبي هريرة فذكره..","grade":"صحيح","chapter_ar":"باب النهي عن الحديث بكل ما سمع","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in his Introduction (5).","chapter_en":"The Prohibition of Narrating Everything One Hears","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “It is sufficient as a lie for a person to narrate everything he hears.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14941],"tks":"صحيح: رواه مسلم (5)."},{"num":1276,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: قَالَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَدَّثَ عَنِّى، بِحَدِيثٍ يُرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ."],"takhrij":"صحيح: رواه مسلم في المقدمة (1) عن أبي بكر بن أبي شيبة، حدثنا وكيع، عن شعبة وسفيان، عن حبيب، عن ميمون بن أبي شبيب، عن المغيرة بن شعبة، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الرواية عن الكذابين والاحتياط في التحمل والأداء","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in his Introduction (1).","chapter_en":"The Prohibition of Narrating From Liars and Exercising Caution in Receiving and Conveying Reports","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever narrates from me a report that he believes to be false is one of the liars.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1)."},{"num":1277,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَدَّثَ عَنِّى، بِحَدِيثٍ يُرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ.."],"takhrij":"صحيح: رواه مسلم في المقدمة (1) عن أبي بكر بن أبي شيبة، حدّثنا وكيع، عن شعبة، عن الحكم، عن عبدالرحمن بن أبي ليلى، عن سمرة بن جندب، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الرواية عن الكذابين والاحتياط في التحمل والأداء","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in his Introduction (1).","chapter_en":"The Prohibition of Narrating From Liars and Exercising Caution in Receiving and Conveying Reports","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Samurah ibn Jundub, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever narrates from me a report that he believes to be false is one of the liars.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1)."},{"num":1278,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: يَكُونُ فِي آخِرِ الزَّمَانِ، دَجَّالُونَ كَذَّابُونَ، يَأْتُونَكُمْ مِنَ الأَحَادِيثِ، بِمَا لَمْ تَسْمَعُوا أَنْتُمْ، وَلَا آبَاؤُكُمْ، فَإِيَّاكُمْ وَإِيَّاهُمْ، لَا يُضِلُّونَكُمْ، وَلَا يَفْتِنُونَكُمْ."],"takhrij":"صحيح: رواه مسلم في المقدمة (6، 7) من طرق عن مسلم بن يسار، أنّه سمع أبا هريرة يقول (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب النهي عن الرواية عن الكذابين والاحتياط في التحمل والأداء","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in his Introduction (6, 7).","chapter_en":"The Prohibition of Narrating From Liars and Exercising Caution in Receiving and Conveying Reports","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “At the end of time there will be lying impostors who will bring you reports that neither you nor your fathers have ever heard. Beware of them and keep away from them, lest they mislead you or put you to trial.”"]}},"tuhfa":{},"full":1,"rep":[15720],"tks":"صحيح: رواه مسلم (6، 7)."},{"num":1279,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبَيْنِ."],"takhrij":"صحيح: رواه ابن ماجه (40) عن عثمان بن أبي شيبة، ثنا محمد بن فضيل، عن الأعمش، عن الحكم، عن عبدالرحمن بن أبي ليلى، عن عليّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن الرواية عن الكذابين والاحتياط في التحمل والأداء","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (40).","chapter_en":"The Prohibition of Narrating From Liars and Exercising Caution in Receiving and Conveying Reports","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib, may Allah be pleased with him, reported that the Prophet ﷺ said: “Whoever narrates from me a report while believing it to be false is one of the liars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (40)."},{"num":1280,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: الدُّنْيَا مَلْعُونَةٌ مَلْعُونٌ، مَا فِيهَا إِلَّا ذِكْرَ اللَّهِ، وَمَا وَالَاهُ أَوْ عَالِمًا أَوْ مُتَعَلِّمًا."],"takhrij":"حسن: رواه الترمذيّ (2322)، وابن ماجه (4112) كلاهما من طريق عبدالرحمن بن ثابت بن ثوبان، قال: سمعت عطاء بن قرّة، قال: سمعت عبدالله بن ضمرة السّلوليّ، قال: حدّثنا أبو هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذم الدنيا إلا عالمًا أو متعلمًا","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2322) and Ibn Mājah (4112).","chapter_en":"What Has Been Reported Concerning the Condemnation of the World Except for a Scholar or a Learner","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “The world is cursed, and cursed is what is in it, except the remembrance of Allah and whatever is connected to it, or a scholar, or a learner.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2322)، وابن ماجه (4112)."},{"num":1281,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ تَعَلَّمَ عِلْمًا مِمَّا يُبْتَغَى بِهِ وَجْهُ اللَّهِ عَزَّ وَجَلَّ لَا يَتَعَلَّمُهُ إِلَّا لِيُصِيبَ بِهِ عَرَضًا مِنَ الدُّنْيَا لَمْ يَجِدْ عَرْفَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ، يَعْنِي رِيحَهَا."],"takhrij":"حسن: رواه أبو داود (3664)، وابن ماجه (252) كلاهما من طريق سريج ابن النّعمان، قال: حدّثنا فليح بن سليمان، عن عبدالله بن عبدالرحمن بن معمر أبي طوالة، عن سعيد بن يسار، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب الترهيب من طلب العلم لغير وجه الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (3664) and Ibn Mājah (252).","chapter_en":"Warning Against Seeking Knowledge for Other Than the Sake of Allah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever learns knowledge by which the Face of Allah, Mighty and Majestic, is sought, but learns it only to obtain some worldly gain, will not find the fragrance of Paradise on the Day of Resurrection.”"]},"buhuth":{"en":["It was also authenticated by Ibn Ḥibbān (78)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3664)، وابن ماجه (252)."},{"num":1282,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَعَلَّمُوا الْعِلْمَ لِتُبَاهُوا بِهِ الْعُلَمَاءَ، وَلَا لِتُمَارُوا بِهِ السُّفَهَاءَ، وَلَا تَخَيَّرُوا بِهِ الْمَجَالِسَ، فَمَنْ فَعَلَ ذَلِكَ فَالنَّارُ النَّارُ."],"takhrij":"حسن: رواه ابن ماجه (254) عن محمد بن يحيى، حدّثنا ابن أبي مريم، قال: أنبأنا يحيى ابن أيوب، عن ابن جريج، عن أبي الزّبير، عن جابر بن عبدالله، (فذكره).","grade":"حسن","chapter_ar":"باب الترهيب من طلب العلم لغير وجه الله","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (254).","chapter_en":"Warning Against Seeking Knowledge for Other Than the Sake of Allah","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Do not learn knowledge in order to boast before the scholars, nor to argue with the foolish, nor to seek the choice places in gatherings because of it. Whoever does that—the Fire, the Fire.”"]},"buhuth":{"en":["It was also authenticated by Ibn Ḥibbān (77) and al-Ḥākim in al-Mustadrak (1/161)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (254)."},{"num":1283,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: خَطَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُطْبَةً مَا سَمِعْتُ مِثْلَهَا قَطُّ، قَالَ: لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا، قَالَ: فَغَطَّى أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وُجُوهَهُمْ لَهُمْ خَنِينٌ، فَقَالَ رَجُلٌ: مَنْ أَبِي؟ قَالَ: فُلَانٌ، فَنَزَلَتْ هَذِهِ الْآيَةُ: ﴿لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾ [سورة المائدة: 101]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4621)، ومسلم في الفضائل (2359) كلاهما من حديث شعبة، حدّثنا موسى بن أنس، عن أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4621) and Muslim (2359).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: The Messenger of Allah ﷺ delivered a sermon the like of which I had never heard before. He said: “If you knew what I know, you would laugh little and weep much.” The Companions of the Messenger of Allah ﷺ covered their faces, and the sound of their weeping could be heard. Then a man asked: “Who is my father?” He replied: “Your father is so-and-so.” Then this verse was revealed: “Do not ask about things which, if disclosed to you, would distress you.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾","[المائدة: ١٠١]"],"en":["Allah Most High said:","“O you who believe, do not ask about things which, if made clear to you, would distress you.”","[Sūrat al-Māʾidah 5:101]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4621)، ومسلم (2359)."},{"num":1284,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ قَوْمٌ يَسْأَلُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اسْتِهْزَاءً، فَيَقُولُ الرَّجُل: مَنْ أَبِي؟ وَيَقُولُ الرَّجُلُ: تَضِلُّ نَاقَتُهُ، أَيْنَ نَاقَتِي؟ فَأَنْزَلَ اللَّهُ فِيهِمْ هَذِهِ الْآيَةَ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ﴾ [سورة المائدة: 101] حَتَّى فَرَغَ مِنَ الْآيَةِ كُلِّهَا."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4622) عن الفضل بن سهل، قال: حدّثنا أبو النّضر، حدّثنا أبو خيثمة، حدّثنا أبو الجويرية، عن ابن عباس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4622).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: Some people used to ask the Messenger of Allah ﷺ questions mockingly. One man would ask: “Who is my father?” And another man whose she-camel had gone astray would ask: “Where is my she-camel?” So Allah revealed concerning them this verse: “O you who believe, do not ask about things which, if disclosed to you, would distress you…” until the end of the entire verse."]}},"tuhfa":{},"full":1,"rep":[12292],"tks":"صحيح: رواه البخاري (4622)."},{"num":1285,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ أَشْيَاءَ كَرِهَهَا، فَلَمَّا أَكْثَرُوا عَلَيْهِ الْمَسْأَلَةَ غَضِبَ وَقَالَ: سَلُونِي، فَقَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ مَنْ أَبِي؟ قَالَ: أَبُوكَ حُذَافَةُ، ثُمَّ قَامَ آخَرُ فَقَالَ: يَا رَسُولَ اللَّهِ، مَنْ أَبِي؟ فَقَالَ: أَبُوكَ سَالِمٌ مَوْلَى شَيْبَةَ، فَلَمَّا رَأَى عُمَرُ مَا بِوَجْهِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْغَضَبِ، قَالَ: إِنَّا نَتُوبُ إِلَى اللَّهِ عَزَّ وَجَلَّ."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام (7291)، ومسلم في الفضائل (2360) كلاهما من حديث أبي أسامة، عن بريد بن أبي بردة، عن أبي بردة، عن أبي موسى، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7291) and Muslim (2360).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported: The Messenger of Allah ﷺ was asked about matters that he disliked. When the people persisted in questioning him, he became angry and said: “Ask me.” A man stood and asked: “O Messenger of Allah ﷺ, who is my father?” He replied: “Your father is Ḥudhāfah.” Then another man stood and asked: “O Messenger of Allah ﷺ, who is my father?” He replied: “Your father is Sālim, the freedman of Shaybah.” When ʿUmar, may Allah be pleased with him, saw the anger upon the face of the Messenger of Allah ﷺ, he said: “We repent to Allah, Mighty and Majestic.”"]}},"tuhfa":{},"full":1,"rep":[15025],"tks":"متفق عليه: رواه البخاري (7291)، ومسلم (2360)."},{"num":1286,"demo":false,"sanad":"","matn":["عَنْ أَبِي فِرَاسٍ، رَجُلٍ مِنْ أَسْلَمَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ: سَلُونِي عَمَّا شِئْتُمْ فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ مَنْ أَبِي؟ قَالَ: أَبُوكَ فُلَانٌ الَّذِي تُدْعَى إِلَيْهِ، وَسَأَلَهُ رَجُلٌ أَفِي الْجَنَّةِ أَنَا؟ فَقَالَ: فِي الْجَنَّةِ، وَقَالَ آخَرُ: أَفِي الْجَنَّةِ أَنَا؟ قَالَ: فِي النَّارِ، فَقَامَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ: رَضِينَا بِاللهِ رِبًا."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (4580) عن محمد بن عبدالله الحضرميّ، ثنا عمر بن محمد بن الحسن الأسدي، ثنا أبي، ثنا عبد العزيز بن عبد الصّمد العمي، عن أبي عمران الجوني، عن أبي فراس، رجل من أسلم، ، فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (4580).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abū Firās, a man from Aslam, reported: The Messenger of Allah ﷺ said one day: “Ask me whatever you wish.” A man asked: “O Messenger of Allah ﷺ, who is my father?” He replied: “Your father is so-and-so, the man to whom you are attributed.” Another man asked him: “Am I in Paradise?” He replied: “In Paradise.” Another asked: “Am I in the Fire?” He replied: “In the Fire.” Then ʿUmar, may Allah be pleased with him, stood and said: “We are pleased with Allah as our Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (4580)."},{"num":1287,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: دَعُونِي مَا تَرَكْتُكُمْ إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ، فَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَاجْتَنِبُوهُ، وَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام بالكتاب والسنة (7288) عن إسماعيل، حدّثني مالك، عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Iʿtiṣām bi-l-Kitāb wa-l-Sunnah (7288) and Muslim (1337).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “Leave me concerning what I have left you without command. Those before you were destroyed because of their excessive questioning and their disagreement with their prophets. When I prohibit you from something, avoid it; and when I command you with something, do of it as much as you are able.”"]},"buhuth":{"en":["At the beginning of Muslim’s narration:","The Messenger of Allah ﷺ addressed us and said:","“O people, Allah has made Ḥajj obligatory upon you, so perform Ḥajj.”","A man asked:","“Every year, O Messenger of Allah ﷺ?”","He remained silent until the man asked it three times.","The Messenger of Allah ﷺ then said:","“Had I said, ‘Yes,’ it would have become obligatory, and you would not have been able to do it.”","Then he mentioned the remainder of the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13518,15653],"tks":"متفق عليه: رواه البخاري (7288)، ومسلم (1337)."},{"num":1288,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَيْكُمْ عُقُوقَ الْأُمَّهَاتِ، وَوَأْدَ الْبَنَاتِ، وَمَنْعًا وَهَاتِ، وَكَرِهَ لَكُمْ ثَلَاثًا قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ."],"takhrij":"متفق عليه: رواه البخاريّ في الأدب (5975)، ومسلم في الأقضية (593) كلاهما من حديث ورّاد مولى المغيرة بن شعبة، عن المغيرة بن شعبة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5975) and Muslim (593).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, Allah, Mighty and Majestic, has forbidden you from being undutiful to mothers, burying daughters alive, withholding what is due while demanding what is not due, and He dislikes for you three things: idle talk of ‘it was said’ and ‘he said,’ excessive questioning, and wasting wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5975)، ومسلم (593)."},{"num":1289,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْظَمُ الْمُسْلِمِينَ فِي الْمُسْلِمِينَ جُرْمًا، مَنْ سَأَلَ عَنْ أَمْرٍ لَمْ يُحَرَّمْ، فَحُرِّمَ عَلَى النَّاسِ، مِنْ أَجْلِ مَسْأَلَتِهِ."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام (7289)، ومسلم في الفضائل (2358) كلاهما من حديث ابن شهاب، عن عامر بن سعد، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7289) and Muslim (2358).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The Muslim who commits the greatest offense against the Muslims is the one who asks about something that had not been forbidden, and it then becomes forbidden to the people because of his questioning.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7289)، ومسلم (2358)."},{"num":1290,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ عُوَيْمِرًا أَتَى عَاصِمَ بْنَ عَدِيٍّ وَكَانَ سَيِّدَ بَنِي عَجْلَانَ، فَقَالَ: كَيْفَ تَقُولُونَ فِي رَجُلٍ وَجَدَ مَعَ امْرَأَتِهِ رَجُلًا أَيَقْتُلُهُ فَتَقْتُلُونَهُ، أَمْ كَيْفَ يَصْنَعُ؟ سَلْ لِي رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَتَى عَاصِمٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، فَكَرِهَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسَائِلَ، فَسَأَلَهُ عُوَيْمِرٌ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَرِهَ الْمَسَائِلَ وَعَابَهَا، قَالَ عُوَيْمِرٌ: وَاللَّهِ لَا أَنْتَهِي حَتَّى أَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4745)، ومسلم في اللّعان (1492) كلاهما من حديث ابن شهاب، عن سهل بن سعد السّاعديّ، فذكر الحديث بطوله.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4745) and Muslim (1492).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Sahl ibn Saʿd, may Allah be pleased with him, reported: ʿUwaymir came to ʿĀṣim ibn ʿAdī, who was the leader of Banū ʿAjlān, and said: “What do you say concerning a man who finds another man with his wife? Should he kill him, or what should he do? Ask the Messenger of Allah ﷺ about that for me.” So ʿĀṣim went to the Prophet ﷺ and said: “O Messenger of Allah ﷺ…” But the Messenger of Allah ﷺ disliked such questions. ʿUwaymir then asked about it, and he was told: “The Messenger of Allah ﷺ disliked such questions and criticized them.” ʿUwaymir said: “By Allah, I will not stop until I ask the Messenger of Allah ﷺ about it.” Then the remainder of the ḥadīth was mentioned."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4745)، ومسلم (1492)."},{"num":1291,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَنْ يَبْرَحَ النَّاسُ يَتَسَاءَلُونَ حَتَّى يَقُولُوا هَذَا اللَّهُ خَالِقُ كُلِّ شَيْءٍ فَمَنْ خَلَقَ اللَّهَ ؟."],"takhrij":"متفق عليه: رواه البخاريّ في الاعتصام (7296) عن الحسن بن صباح، حدّثنا شبابة، حدّثنا ورقاء، عن عبدالله بن عبدالرحمن، سمعت أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Iʿtiṣām (7296) and Muslim (136).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “People will continue questioning one another until they say: ‘Allah is the Creator of everything, so who created Allah?’”"]},"buhuth":{"en":["Muslim also narrated it in al-Īmān (136) through another route from Mukhtār ibn Fulful, from Anas, from the Messenger of Allah ﷺ, who said: “Allah, Mighty and Majestic, said: Your Ummah will continue saying, ‘What about this? What about that?’ until they say, ‘Allah created creation, so who created Allah?’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7296)، ومسلم (136)."},{"num":1292,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بْنِ يَسَارٍ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللهَ جَلَّ وَعَزَّ كَرِهَ لَكُمْ قِيلَ وَقَالَ، وَكَثْرَةَ السُّؤَالِ، وَإِضَاعَةَ الْمَالِ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (20/ح 522) من طرق عن سلم بن قتيبة، عن عمران القطّان، عن قتادة، عن أبي عبدالله الحسري، عن معقل بن يسار، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī (20/224).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Maʿqil ibn Yasār, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, Allah, Glorious and Mighty, dislikes for you idle talk of ‘it was said’ and ‘he said,’ excessive questioning, and wasting wealth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (20/ح 522)."},{"num":1293,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كُنَّا عِنْدَ عُمَرَ فَقَالَ: نُهِينَا عَنِ التَّكَلُّفِ."],"takhrij":"صحيح: رواه البخاريّ في الاعتصام (7293) عن سليمان بن حرب، حدّثنا حمّاد بن زيد، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن كثرة المسألة عما لم يكن ولم ينزل به وحي","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7293).","chapter_en":"The Prohibition of Excessive Questioning About Matters That Have Not Occurred and Concerning Which No Revelation Has Been Sent Down","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: We were with ʿUmar may Allah be pleased with him when he said: “We were forbidden from affectation and unnecessarily burdening ourselves.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14453,15027],"tks":"صحيح: رواه البخاري (7293)."},{"num":1294,"demo":false,"sanad":"","matn":["عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، قَالَ: تَفَرَّقَ النَّاسُ عَنْ أَبِي هُرَيْرَةَ، فَقَالَ لَهُ نَاتِلُ: أَهْلِ الشَّامِ أَيُّهَا الشَّيْخُ، حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: نَعَمْ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَوَّلَ النَّاسِ يُقْضَى يَوْمَ الْقِيَامَةِ عَلَيْهِ رَجُلٌ اسْتُشْهِدَ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟، قَالَ: قَاتَلْتُ فِيكَ حَتَّى اسْتُشْهِدْتُ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ قَاتَلْتَ لِأَنْ يُقَالَ جَرِيءٌ، فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ، وَرَجُلٌ تَعَلَّمَ الْعِلْمَ وَعَلَّمَهُ وَقَرَأَ الْقُرْآنَ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟، قَالَ: تَعَلَّمْتُ الْعِلْمَ وَعَلَّمْتُهُ وَقَرَأْتُ فِيكَ الْقُرْآنَ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِمٌ وَقَرَأْتَ الْقُرْآنَ لِيُقَالَ هُوَ قَارِئٌ، فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ حَتَّى أُلْقِيَ فِي النَّارِ، وَرَجُلٌ وَسَّعَ اللَّهُ عَلَيْهِ وَأَعْطَاهُ مِنْ أَصْنَافِ الْمَالِ كُلِّهِ، فَأُتِيَ بِهِ فَعَرَّفَهُ نِعَمَهُ فَعَرَفَهَا، قَالَ: فَمَا عَمِلْتَ فِيهَا؟، قَالَ: مَا تَرَكْتُ مِنْ سَبِيلٍ تُحِبُّ أَنْ يُنْفَقَ فِيهَا إِلَّا أَنْفَقْتُ فِيهَا لَكَ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ فَعَلْتَ لِيُقَالَ هُوَ جَوَادٌ، فَقَدْ قِيلَ ثُمَّ أُمِرَ بِهِ فَسُحِبَ عَلَى وَجْهِهِ ثُمَّ أُلْقِيَ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1905) عن يحيى بن حبيب الحارثيّ، ثنا خالد بن الحارث، ثنا ابن جريج، حدثني يونس بن يوسف، عن سليمان بن يسار، فذكره.","grade":"صحيح","chapter_ar":"باب ما ورد من الوعيد للقراء المرائين","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Imārah (1905).","chapter_en":"What Has Been Reported Concerning the Warning Against Reciters Who Show Off","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Sulaymān ibn Yasār reported: After the people dispersed from Abū Hurayrah may Allah be pleased with him, Nātil, a man from al-Shām, said to him: “O elder, narrate to us a ḥadīth that you heard from the Messenger of Allah ﷺ.” He replied: “Yes. I heard the Messenger of Allah ﷺ say: “The first person whose case will be judged on the Day of Resurrection will be a man who was martyred. He will be brought, and Allah will make him recognize His blessings, and he will recognize them. He will say: ‘What did you do with them?’ The man will say: ‘I fought for Your sake until I was martyred.’ He will say: ‘You have lied. Rather, you fought so that it would be said, “He is courageous,” and it was said.’ Then an order will be given concerning him, and he will be dragged upon his face until he is thrown into the Fire. Then there will be a man who learned knowledge and taught it and recited the Qurʾān. He will be brought, and Allah will make him recognize His blessings, and he will recognize them. He will say: ‘What did you do with them?’ The man will say: ‘I learned knowledge and taught it, and I recited the Qurʾān for Your sake.’ He will say: ‘You have lied. Rather, you learned knowledge so that it would be said, “He is a scholar,” and you recited the Qurʾān so that it would be said, “He is a reciter,” and it was said.’ Then an order will be given concerning him, and he will be dragged upon his face until he is thrown into the Fire. Then there will be a man upon whom Allah bestowed abundance and gave every kind of wealth. He will be brought, and Allah will make him recognize His blessings, and he will recognize them. He will say: ‘What did you do with them?’ The man will say: ‘I did not leave any path in which You love wealth to be spent except that I spent in it for Your sake.’ He will say: ‘You have lied. Rather, you did that so that it would be said, “He is generous,” and it was said.’ Then an order will be given concerning him, and he will be dragged upon his face and then thrown into the Fire.”"]},"buhuth":{"en":["The expression “Nātil of the people of al-Shām” refers to Nātil ibn Qays al-Ḥizāmī al-Shāmī. His father was a Companion, and Nātil was the chief and leader of his people."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4085,7801,12030,16197],"tks":"صحيح: رواه مسلم (1905)."},{"num":1295,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَكْثَرَ مُنَافِقِي أُمَّتِي قُرَّاؤُهَا."],"takhrij":"حسن: رواه الإمام أحمد (6633) عن زيد بن الحباب، من كتابه، ، حدّثنا عبدالرحمن بن شريح، سمعت شرحبيل بن يزيد المعافريّ، أنّه سمع محمد بن هديّة الصدفي، قال: سمعت عبدالله بن عمرو بن العاص يقول... فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما ورد من الوعيد للقراء المرائين","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (6633).","chapter_en":"What Has Been Reported Concerning the Warning Against Reciters Who Show Off","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “Indeed, most of the hypocrites of my Ummah are its reciters.”"]},"buhuth":{"en":["ʿAbd al-Raḥmān ibn Jubayr also corroborated it; Aḥmad narrated this route (6634), and Ibn Baṭṭah narrated it in al-Īmān (942) through ʿAbdullāh ibn Wahb from Ibn Lahīʿah. Ibn Wahb was among those who narrated from Ibn Lahīʿah before his memory changed.","In Fayḍ al-Qadīr (2/80), al-Munāwī transmitted from al-Zamakhsharī concerning the statement, “Most of the hypocrites of my Ummah are its reciters”:","“He intended by hypocrisy here showing off, because both involve displaying outwardly something contrary to what is inward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6633)."},{"num":1296,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَكْثَرُ مُنَافِقِي هَذِهِ الْأُمَّةِ قُرَّاؤُهَا."],"takhrij":"حسن: رواه الإمام أحمد (17367) عن أبي عبدالرحمن، حدّثنا ابن لهيعة، حدّثنا أبو المصعب، قال: سمعت عقبة بن عامر، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما ورد من الوعيد للقراء المرائين","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (17367).","chapter_en":"What Has Been Reported Concerning the Warning Against Reciters Who Show Off","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Most of the hypocrites of this Ummah are its reciters.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17367)."},{"num":1297,"demo":false,"sanad":"","matn":["عَنْ خَبَّابٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ بَنِي إِسْرَائِيلَ لَمَّا هَلَكُوا قَصُّوا."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (3705) من طريقين، عن أبي أحمد الزّبيريّ، ثنا سفيان، عن الأجلح، عن عبدالله بن أبي الهذيل، عن خباب، فذكر الحديث.","grade":"حسن","chapter_ar":"باب في التحذير من كثرة القصص","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī (3705).","chapter_en":"Warning Against Excessive Storytelling and Public Preaching Through Stories","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Khabbāb, may Allah be pleased with him, reported that the Prophet ﷺ said: “When the Children of Israel were ruined, they resorted to storytelling.”"]},"buhuth":{"en":["Abū Nuʿaym also narrated it in al-Ḥilyah (4/362) through this route and said: “It is gharīb from the narration of al-Ajlaḥ and al-Thawrī; Abū Aḥmad alone narrated it.”","Regarding the statement, “When they were ruined, they resorted to storytelling,” Ibn al-Athīr said:","“That is, they relied upon speech and abandoned action, and this became a cause of their destruction. Or the meaning may be the reverse: when they were ruined through abandoning action, they then devoted themselves to storytelling.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني (3705)."},{"num":1298,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ مُعَاوِيَةَ الْكِنْدِيِّ: أَنَّهُ رَكِبَ إِلَى عُمَرَ بْنِ الْخَطَّابِ يَسْأَلُهُ عَنْ ثَلَاثِ خِلَالٍ، قَالَ: فَقَدِمَ الْمَدِينَةَ، فَسَأَلَهُ عُمَرُ: مَا أَقْدَمَكَ؟ قَالَ: لِأَسْأَلَكَ عَنْ ثَلَاثِ خِلَالٍ، قَالَ: وَمَا هُنَّ؟ قَالَ: رُبَّمَا كُنْتُ أَنَا وَالْمَرْأَةُ فِي بِنَاءٍ ضَيِّقٍ، فَتَحْضُرُ الصَّلَاةُ، فَإِنْ صَلَّيْتُ أَنَا وَهِيَ، كَانَتْ بِحِذَائِي، وَإِنْ صَلَّتْ خَلْفِي، خَرَجَتْ مِنَ الْبِنَاءِ، فَقَالَ عُمَرُ: تَسْتُرُ بَيْنَكَ وَبَيْنَهَا بِثَوْبٍ، ثُمَّ تُصَلِّي بِحِذَائِكَ إِنْ شِئْتَ. وَعَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ، فَقَالَ: نَهَانِي عَنْهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: وَعَنِ الْقَصَصِ، فَإِنَّهُمْ أَرَادُونِي عَلَى الْقَصَصِ، فَقَالَ: مَا شِئْتَ، كَأَنَّهُ كَرِهَ أَنْ يَمْنَعَهُ، قَالَ: إِنَّمَا أَرَدْتُ أَنْ أَنْتَهِيَ إِلَى قَوْلِكَ، قَالَ: أَخْشَى عَلَيْكَ أَنْ تَقُصَّ فَتَرْتَفِعَ عَلَيْهِمْ فِي نَفْسِكَ، ثُمَّ تَقُصَّ فَتَرْتَفِعَ، حَتَّى يُخَيَّلَ إِلَيْكَ أَنَّكَ فَوْقَهُمْ بِمَنْزِلَةِ الثُّرَيَّا، فَيَضَعَكَ اللَّهُ تَحْتَ أَقْدَامِهِمْ يَوْمَ الْقِيَامَةِ بِقَدْرِ ذَلِكَ."],"takhrij":"حسن: رواه أحمد (111) عن أبي المغيرة، ثنا صفوان، ثنا عبدالرحمن بن جبير بن نفير، عن الحارث بن معاوية الكندي، فذكره.","grade":"حسن","chapter_ar":"باب في التحذير من كثرة القصص","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (111).","chapter_en":"Warning Against Excessive Storytelling and Public Preaching Through Stories","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Al-Ḥārith ibn Muʿāwiyah al-Kindī reported that he traveled to ʿUmar ibn al-Khaṭṭāb may Allah be pleased with him to ask him about three matters. When he arrived in Madinah, ʿUmar asked him: “What brought you?” He replied: “To ask you about three matters.” ʿUmar asked: “What are they?” He said: “Sometimes a woman and I are in a narrow structure when the prayer time comes. If I pray while she also prays, she is beside me; but if she prays behind me, she must go outside the structure.” ʿUmar said: “Place a cloth as a screen between you and her, then pray beside her if you wish.” He then asked about the two rakʿahs after ʿAṣr. ʿUmar said: “The Messenger of Allah ﷺ prohibited me from them.” He then said: “And about storytelling: the people have wanted me to give them public exhortations through stories.” ʿUmar said: “As you wish,” as though he disliked forbidding him. Al-Ḥārith said: “I only wanted to reach your own opinion.” ʿUmar said: “I fear that if you begin preaching through stories, you will begin to consider yourself elevated above the people. Then you will continue doing so and rise further in your own estimation, until you imagine yourself above them like the Pleiades. Allah will then place you beneath their feet on the Day of Resurrection in proportion to that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (111)."},{"num":1299,"demo":false,"sanad":"","matn":["عَنِ الْأَسْوَدِ بْنِ هِلَالٍ، عَنْ عَبْدِ اللهِ قَالَ: ذَكَرُوا لَهُ رَجُلًا يَقُصُّ، فَجَاءَ فِي الْقَوْمِ فَسَمِعْتُهُ يَقُولُ: سُبْحَانَ اللهِ كَذَا وَكَذَا، فَلَمَّا سَمِعَ ذَلِكَ قَامَ، فَقَالَ: أَلَا تَسْمَعُوا؟ فَلَمَّا نَظَرُوا إِلَيْهِ قَالَ: إِنَّكُمْ لَأَهْدَى مِنْ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ، إِنَّكُمْ لَمُتَمَسِّكُونَ بِطَرَفِ ضَلَالَةٍ."],"takhrij":"صحيح: رواه الطبرانيّ في الكبير (8639) عن علي بن عبد العزيز، ثنا أبو غسان مالك بن إسماعيل، ثنا إسرائيل، عن الأشعث بن أبي الشّعثاء، عن الأسود بن هلال، فذكره.","grade":"صحيح","chapter_ar":"باب في التحذير من كثرة القصص","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ṭabarānī (8639).","chapter_en":"Warning Against Excessive Storytelling and Public Preaching Through Stories","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Al-Aswad ibn Hilāl reported from ʿAbdullāh may Allah be pleased with him: They mentioned to him a man who used to give public exhortations through stories, so he came and sat among the people. I heard the man saying: “Subḥān Allah, such-and-such…” When ʿAbdullāh heard that, he stood and said: “Will you not listen?” When they looked toward him, he said: “Are you truly better guided than Muḥammad ﷺ and his Companions? You are certainly clinging to an edge of misguidance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني (8639)."},{"num":1300,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: نَسَخَ عُمَرُ كِتَابًا مِنَ التَّوْرَاةِ بِالْعَرَبِيَّةِ، فَجَاءَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يَقْرَأُ وَوَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَغَيَّرُ، فَقَالَ رَجُلٌ مِنَ الأَنْصَارِ: وَيْحَكَ يَابْنَ الْخَطَّابِ! أَلا تَرَى وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لا تَسْأَلُوا أَهْلَ الْكِتَابِ عَنْ شَيْءٍ، فَإِنَّهُمْ لَنْ يَهْدُوكُمْ وَقَدْ ضَلُّوا، وَإِنَّكُمْ إِمَّا أَنْ تُكَذِّبُوا بِحَقٍّ أَوْ تُصَدِّقُوا بِبَاطِلٍ، وَاللَّهِ لَوْ كَانَ مُوسَى بَيْنَ أَظْهُرِكُمْ مَا حَلَّ لَهُ إِلا أَنْ يَتَّبِعَنِي."],"takhrij":"حسن: رواه البزّار -كشف الأستار (124)، عن عبد الواحد بن غياث، أنا حماد بن زيد، ثنا خالد، حدثني عامر، ثنا جابر، فذكره.","grade":"حسن","chapter_ar":"باب الزجر عن النظر في كتب أهل الكتاب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (124).","chapter_en":"Rebuking the Practice of Looking Into the Books of the People of the Book","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: ʿUmar, may Allah be pleased with him, copied a writing from the Torah into Arabic and brought it to the Prophet ﷺ. He began reading it while the face of the Messenger of Allah ﷺ visibly changed. A man from the Anṣār said: “Woe to you, O son of al-Khaṭṭāb! Do you not see the face of the Messenger of Allah ﷺ?” The Prophet ﷺ said: “Do not ask the People of the Book about anything. They will not guide you when they themselves have gone astray. You may either deny something true or affirm something false. By Allah, if Mūsā were among you, it would not be lawful for him to do anything except follow me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (124)."},{"num":1301,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكِتَابٍ أَصَابَهُ مِنْ بَعْضِ أَهْلِ الْكُتُبِ، فَقَرَأَهُ عَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَغَضِبَ وَقَالَ: أَمُتَهَوِّكُونَ فِيهَا يَا ابْنَ الْخَطَّابِ، وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ جِئْتُكُمْ بِهَا بَيْضَاءَ نَقِيَّةً، لَا تَسْأَلُوهُمْ عَنْ شَيْءٍ فَيُخْبِرُوكُمْ بِحَقٍّ فَتُكَذِّبُوا بِهِ، أَوْ بِبَاطِلٍ فَتُصَدِّقُوا بِهِ، وَالَّذِي نَفْسِي بِيَدِهِ لَوْ أَنَّ مُوسَى كَانَ حَيًّا، مَا وَسِعَهُ إِلَّا أَنْ يَتَّبِعَنِي."],"takhrij":"حسن: رواه الإمام أحمد (15156)، وابن أبي شيبة (26949)، والبزار- كشف الأستار (124)، كلهم من طرق عن هشيم بن بشير، أخبرنا مجالد، عن الشعبي، عن جابر بن عبد الله فذكره. والسياق لأحمد.","grade":"حسن","chapter_ar":"باب الزجر عن النظر في كتب أهل الكتاب","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (15156), Ibn Abī Shaybah (26949), and al-Bazzār in Kashf al-Astār (124).","chapter_en":"Rebuking the Practice of Looking Into the Books of the People of the Book","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, came to the Prophet ﷺ with a book that he had obtained from some of the People of the Book and read it to the Prophet ﷺ. The Prophet ﷺ became angry and said: “Are you confused concerning it, O son of al-Khaṭṭāb? By the One in Whose hand is my soul, I have brought it to you pure and clear. Do not ask them about anything, lest they inform you of something true and you deny it, or of something false and you affirm it. By the One in Whose hand is my soul, if Mūsā were alive, he would have no choice but to follow me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15156)، وابن أبي شيبة (26949)، والبزار في كشف الأستار (124)."},{"num":1302,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اقْتَبَسَ عِلْمًا مِنَ النُّجُومِ، اقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ زَادَ مَا زَادَ."],"takhrij":"صحيح: رواه أبو داود (3905)، وابن ماجه (3726) من طريق يحيى بن سعيد، عن عبيدالله بن الأخنس، عن الوليد بن عبدالله، عن يونس بن ماهك، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الزجر عن علم النجوم","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3905) and Ibn Mājah (3726).","chapter_en":"What Has Been Reported Concerning the Warning Against Astrology","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “Whoever acquires a portion of knowledge from the stars has acquired a branch of magic; the more he increases in it, the more he increases in magic.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3905)، وابن ماجه (3726)."},{"num":1303,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلَكَ الْمُتَنَطِّعُونَ، قَالَهَا ثَلَاثًا."],"takhrij":"صحيح: رواه مسلم في العلم (2670) عن أبي بكر بن أبي شيبة، حدثنا حفص بن غياث، ويحيى بن سعيد، عن ابن جريج، عن سليمان بن عتيق، عن طلق بن حبيب، عن الأحنف بن قيس، عن عبدالله (وهو ابن مسعود)، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن التنطع في الدين","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-ʿIlm (2670).","chapter_en":"The Prohibition of Excessiveness and Unnecessary Extremism in Religion","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Those who go to excess are ruined.” He said it three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2670)."},{"num":1304,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ قَالَ: قِيلَ لَهُ: أَلَا تَدْخُلُ عَلَى عُثْمَانَ فَتُكَلِّمَهُ؟ فَقَالَ: أَتَرَوْنَ أَنِّي لَا أُكَلِّمُهُ إِلَّا أُسْمِعُكُمْ؟ وَاللَّهِ لَقَدْ كَلَّمْتُهُ فِيمَا بَيْنِي وَبَيْنَهُ، مَا دُونَ أَنْ أَفْتَتِحَ أَمْرًا لَا أُحِبُّ أَنْ أَكُونَ أَوَّلَ مَنْ فَتَحَهُ، وَلَا أَقُولُ لِأَحَدٍ يَكُونُ عَلَيَّ أَمِيرًا، إِنَّهُ خَيْرُ النَّاسِ بَعْدَ مَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: يُؤْتَى بِالرَّجُلِ يَوْمَ الْقِيَامَةِ، فَيُلْقَى فِي النَّارِ، فَتَنْدَلِقُ أَقْتَابُ بَطْنِهِ، فَيَدُورُ بِهَا كَمَا يَدُورُ الْحِمَارُ بِالرَّحَى، فَيَجْتَمِعُ إِلَيْهِ أَهْلُ النَّارِ، فَيَقُولُونَ يَا فُلَانُ: مَا لَكَ أَلَمْ تَكُنْ تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ؟ فَيَقُولُ: بَلَى، قَدْ كُنْتُ آمُرُ بِالْمَعْرُوفِ وَلَا آتِيهِ وَأَنْهَى عَنِ الْمُنْكَرِ وَآتِيهِ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3267)، ومسلم في الزّهد والرّقائق (2989) كلاهما من طريق الأعمش، عن شقيق، عن أسامة بن زيد، فذكره.","grade":"متفق عليه","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3267) and Muslim (2989).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Usāmah ibn Zayd, may Allah be pleased with them, reported: It was said to him: “Will you not go in to ʿUthmān and speak to him?” He replied: “Do you think that I do not speak to him unless I make you hear it? By Allah, I have spoken to him privately, without opening a matter that I would dislike to be the first to open. And I do not say concerning anyone who is placed in authority over me that he is the best of people, after I heard the Messenger of Allah ﷺ say: ‘A man will be brought on the Day of Resurrection and thrown into the Fire. His intestines will spill out, and he will go around them as a donkey goes around a millstone. The people of the Fire will gather around him and say: “O so-and-so, what is wrong with you? Did you not used to command what is right and forbid what is wrong?” He will say: “Yes. I used to command what is right but did not do it, and I used to forbid what is wrong but would do it myself.”’”"]},"intro":{"ar":["قال الله تعالى:","﴿أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ وَأَنْتُمْ تَتْلُونَ الْكِتَابَ أَفَلَا تَعْقِلُونَ﴾","[البقرة: ٤٤]","وقال تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ ۝ كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لَا تَفْعَلُونَ﴾","[الصف: ٢–٣]","وقال تعالى فيمن حُمِّل التوراة ثم لم يعمل بها:","﴿مَثَلُ الَّذِينَ حُمِّلُوا التَّوْرَاةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ الْحِمَارِ يَحْمِلُ أَسْفَارًا ۚ بِئْسَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِ اللَّهِ ۚ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ﴾","[الجمعة: ٥]"],"en":["Allah Most High said:","“Do you command people to righteousness while forgetting yourselves, even though you recite the Scripture? Will you not then reason?”","[Sūrat al-Baqarah 2:44]","And Allah Most High said:","“O you who believe, why do you say what you do not do? It is greatly hateful in the sight of Allah that you say what you do not do.”","[Sūrat al-Ṣaff 61:2–3]","And Allah Most High said concerning those who were entrusted with the Torah but did not uphold it:","“The example of those who were entrusted with the Torah and then did not uphold it is like that of a donkey carrying books. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people.”","[Sūrat al-Jumuʿah 62:5]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3267)، ومسلم (2989)."},{"num":1305,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)، أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا."],"takhrij":"صحيح: رواه مسلم في الذّكر والدّعاء (2722) من حديث أبي معاوية، عن عاصم، عن عبدالله بن الحارث، وعن أبي عثمان النّهديّ، عن زيد بن أرقم، فذكره في حديث أطول، وسيأتي في موضعه.","grade":"صحيح","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Dhikr wa-l-Duʿāʾ (2722).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, reported that the Prophet ﷺ used to say: “O Allah, I seek refuge in You from knowledge that does not benefit, from a heart that does not humble itself, from a soul that is never satisfied, and from a supplication that is not answered.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2722)."},{"num":1306,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الْأَسْلَمِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمُرِهِ فِيمَا أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَ فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَ أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَ أَبْلَاهُ."],"takhrij":"حسن: رواه الترمذيّ (2417) عن عبدالله بن عبدالرحمن، أخبرنا الأسود بن عامر، حدثنا أبو بكر بن عياش، عن الأعمش، عن سعيد بن عبدالله بن جريج، عن أبي برزة الأسلميّ، فذكره.","grade":"حسن","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2417).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Abū Barzah al-Aslamī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “The feet of a servant will not move on the Day of Resurrection until he is questioned about his life and how he spent it; about his knowledge and what he did with it; about his wealth—where he acquired it and how he spent it; and about his body and how he wore it out.”"]},"buhuth":{"en":["Al-Tirmidhī said: “This is a ḥasan ṣaḥīḥ ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1214],"tks":"حسن: رواه الترمذي (2417)."},{"num":1307,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُؤْتَى بِالرَّجُلِ الَّذِي كَانَ يُطَاعُ فِي مَعَاصِي اللَّهِ تَعَالَى، فَيُقْذَفُ فِي النَّارِ، فَتَنْدَلِقُ بِهِ أَقْتَابُهُ، فَيَسْتَدِيرُ فِيهَا كَمَا يَسْتَدِيرُ الْحِمَارُ فِي الرَّحَا، فَيَأْتِي عَلَيْهِ أَهْلُ طَاعَتِهِ مِنَ النَّاسِ فَيَقُولُونَ: أَيْ فُلَ، أَيْنَ مَا كُنْتَ تَأْمُرُنَا بِهِ؟ فَيَقُولُ: إِنِّي كُنْتُ آمُرُكُمْ بِأَمْرٍ وَأُخَالِفُكُمْ إِلَى غَيْرِهِ."],"takhrij":"حسن: رواه أحمد (21794) عن عبد الصمد، ثنا حماد، عن عاصم، عن أبي وائل، قال: قيل لأسامة بن زيد، فذكره.","grade":"حسن","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (21794).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Usāmah ibn Zayd, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “A man who used to be obeyed in disobedience to Allah will be brought and thrown into the Fire. His intestines will spill out, and he will go around with them as a donkey goes around a millstone. The people who used to obey him will come to him and say: ‘O so-and-so, where is that which you used to command us to do?’ He will say: ‘I used to command you to do one thing while I myself would go against you and do something else.’”"]},"buhuth":{"en":["It was also narrated by al-Ḥākim in al-Mustadrak (7010)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21794)."},{"num":1308,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى قَوْمٍ تُقْرَضُ شِفَاهُهُمْ بِمَقَارِيضَ مِنْ نَارٍ، قَالَ: قُلْتُ: مَنْ هَؤُلَاءِ؟ قَالُوا: خُطَبَاءُ مِنْ أَهْلِ الدُّنْيَا كَانُوا يَأْمُرُونَ النَّاسَ بِالْبِرِّ، وَيَنْسَوْنَ أَنْفُسَهُمْ وَهُمْ يَتْلُونَ الْكِتَابَ، أَفَلَا يَعْقِلُونَ."],"takhrij":"صحيح: رواه أحمد (12211) عن وكيع، حدّثنا حمّاد بن سلمة، عن علي ابن زيد، عن أنس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (12211).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “On the night I was taken on the Night Journey, I passed by people whose lips were being cut with scissors of fire. I asked: ‘Who are these?’ They said: ‘They are preachers from among the people of this world who used to command people to righteousness while forgetting themselves, even though they recited the Scripture. Will they not then reason?’”"]},"buhuth":{"en":["It was also narrated through other routes from Anas may Allah be pleased with him by Abū Yaʿlā (4069) and Abū Nuʿaym in al-Ḥilyah (8/172), and authenticated by Ibn Ḥibbān (53)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12211)."},{"num":1309,"demo":false,"sanad":"","matn":["عَنْ جُنْدُبِ بْنِ عَبْدِ اللهِ الْأَزْدِيِّ صَاحِبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: انْطَلَقْتُ أَنَا وَهُوَ إِلَى الْبَصْرَةِ حَتَّى أَتَيْنَا مَكَانًا يُقَالُ لَهُ بَيْتُ الْمِسْكِينِ، وَهُوَ مِنَ الْبَصْرَةِ مِثْلُ الثَّوِيَّةِ مِنَ الْكُوفَةِ، فَقَالَ: هَلْ كُنْتَ تُدَارِسُ أَحَدًا الْقُرْآنَ؟ فَقُلْتُ: نَعَمْ، قَالَ: فَإِذَا أَتَيْنَا الْبَصْرَةَ فآتِنِي بِهِمْ فَأَتَيْتُهُ بِصَالِحِ بْنِ مُسَرِّحٍ وَبِأَبِي بِلَالٍ وَنَجْدَةَ وَنَافِعِ بْنِ الْأَزْرَقِ وَهُمْ فِي نَفْسِي يَوْمَئِذٍ مِنْ أَفَاضِلِ أَهْلِ الْبَصْرَةِ فَأَنْشَأَ يُحَدِّثُنِي عَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ جُنْدُبٌ، قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَثَلُ الْعَالِمِ الَّذِي يُعَلِّمُ النَّاسَ الْخَيْرَ ويَنْسَى نَفْسَهُ كَمَثَلِ السِّرَاجِ يُضِيءُ لِلنَّاسِ ويَحْرِقُ نَفْسَهُ. وَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَحُولَنَّ بَيْنَ أَحَدِكُمْ وَبَيْنَ الْجَنَّةِ وَهُوَ يَنْظُرُ إِلَى أَبْوَابِهَا مِلْءُ كَفٍّ مِنْ دَمِ مُسْلِمٍ أَهْرَاقَهُ ظُلْمًا. قَالَ: فَتَكَلَّمَ الْقَوْمُ فَذَكَرُوا الْأَمْرَ بِالْمَعْرُوفِ وَالنَّهْيَ عَنِ الْمُنْكَرِ وَهُوَ سَاكِتٌ يَسْتَمِعُ مِنْهُمْ ثُمَّ قَالَ: لَمْ أَرَ كَالْيَوْمِ قَطُّ قَوْمًا أَحَقَّ بِالنَّجَاةِ إِنْ كَانُوا صَادِقِينَ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (1681) من طريق هشام بن عمار، عن علي بن سليمان الكلبي، حدثني الأعمش، عن أبي تميمة، عن جندب بن عبدالله الأزديّ، فذكر الحديث.","grade":"حسن","chapter_ar":"باب في الوعيد للعالم الذي لا يعمل بعلمه، وإن كان علمه ينتفع به غيره","chapter_ur":"","part_ar":"كتاب العلم","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (1681).","chapter_en":"The Warning Against a Scholar Who Does Not Act Upon His Knowledge, Even Though Others Benefit From His Knowledge","part_en":"The Book of Knowledge","group_ar":"جموع أبواب ما ورد من الترهيب في أبواب العلم","group_en":"Collection of Chapters Concerning Warnings Related to Matters of Knowledge","part_no":3,"group_no":2,"chapter_no":20,"content":{"translation":{"en":["Jundub ibn ʿAbdullāh al-Azdī may Allah be pleased with him, a Companion of the Prophet ﷺ, reported: I set out with him toward Basrah until we came to a place called Bayt al-Miskīn, which lay from Basrah at a distance comparable to al-Thawiyyah from Kūfah. He asked, “Were you studying the Qurʾān with anyone?” I replied, “Yes.” He said, “When we reach Basrah, bring them to me.” So I brought to him Ṣāliḥ ibn Musarriḥ, Abū Bilāl, Najdah, and Nāfiʿ ibn al-Azraq. At that time, I regarded them as among the distinguished people of Basrah. He then began narrating to me from the Messenger of Allah ﷺ. Jundub said: The Messenger of Allah ﷺ said: “The example of a scholar who teaches people goodness but forgets himself is like a lamp that gives light to the people while burning itself.” And the Messenger of Allah ﷺ said: “Let not a handful of the blood of a Muslim, which one of you shed unjustly, come between him and Paradise while he is looking at its gates.” The people then spoke and discussed enjoining what is right and forbidding what is wrong, while he remained silent listening to them. Then he said: “I have never seen, before today, a people more deserving of salvation, if they are truthful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في المعجم الكبير (1681)."},{"num":1310,"demo":false,"sanad":"","matn":["عَنْ الْمُغِيرَةِ بْنِ أَبِي بُرْدَةَ، أَنَّهُ سَمِعَ أَبَا هُرَيْرَةَ يَقُولُ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنَ الْمَاءِ، فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ بِهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُوَ الطَّهُورُ مَاؤُهُ، الْحِلُّ مَيْتَتُهُ."],"takhrij":"صحيح: رواه مالك في الطهارة (12) عن صفوان بن سُليم، عن سعيد بن سلمة، من آل بني الأزرق، عن المغيرة بن أبي بُرْدة، وَهُوَ مِنْ بَنِي عَبْدِ الدَّارِ، فذكر الحديث. ومن طريق مالك رواه أبو داود (83) والترمذي (69) والنسائي (59) وابن ماجه (386).","grade":"صحيح","chapter_ar":"باب ما جاء في ماء البحر","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (12), Abū Dāwūd (83), al-Tirmidhī (69), al-Nasāʾī (59), and Ibn Mājah (386).","chapter_en":"What Has Been Reported Concerning Seawater","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Al-Mughīrah ibn Abī Burdah reported that he heard Abū Hurayrah, may Allah be pleased with him, say: A man came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, we travel by sea and carry only a small amount of water with us. If we use it for wuḍūʾ, we will become thirsty. May we perform wuḍūʾ with seawater?” The Messenger of Allah ﷺ said: “Its water is purifying, and its dead animals are lawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (12)، وأبو داود (83)، والترمذي (69)، والنسائي (59)، وابن ماجه (386)."},{"num":1311,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سُئِلَ عَنْ مَاءِ الْبَحْرِ؟ فَقَالَ: هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ."],"takhrij":"حسن: رواه ابن ماجه (388)، قال: حدثنا محمد بن يحيى، ثنا أحمد بن حنبل، ثنا أبو القاسم بن أبي الزناد، قال: حدثني إسحاق بن حازم، عن عبيدالله، وهو ابن مِقْسم، عن جابر، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في ماء البحر","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (388).","chapter_en":"What Has Been Reported Concerning Seawater","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported that the Prophet ﷺ was asked about seawater, and he said: “Its water is purifying, and its dead animals are lawful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (388)."},{"num":1312,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ، فَلْيَغْسِلْ يَدَهُ قَبْلَ أَنْ يُدْخِلَهَا فِي وَضُوئِهِ، فَإِنَّ أَحَدَكُمْ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (9) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهة غمس المتوضئ وغيره يده في الإناء قبل غسلهما","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik in al-Ṭahārah (9).","chapter_en":"The Dislike of Dipping One’s Hand Into a Vessel Before Washing It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “When one of you awakens from sleep, let him wash his hand before putting it into his water for wuḍūʾ, for none of you knows where his hand spent the night.”"]},"buhuth":{"en":["It was also narrated by al-Bukhārī (162) and Muslim (278). In Muslim’s wording: “When one of you awakens from sleep, let him not immerse his hand in the vessel until he has washed it three times, for he does not know where his hand spent the night.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9)."},{"num":1313,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا اسْتَيْقَظَ أَحَدُكُمْ مِنْ نَوْمِهِ فَلَا يُدْخِلْ يَدَهُ فِي الْإِنَاءِ حَتَّى يَغْسِلَهَا."],"takhrij":"حسن: رواه ابن ماجه (394)، وابن خزيمة (146) كلاهما من حديث عبدالله بن وهب، قال: أخبرني ابن لهيعة وجابر بن إسماعيل، عن عُقيل بن خالد، عن ابن شهاب، عن سالم بن عبد الله، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهة غمس المتوضئ وغيره يده في الإناء قبل غسلهما","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (394) and Ibn Khuzaymah (146).","chapter_en":"The Dislike of Dipping One’s Hand Into a Vessel Before Washing It","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “When one of you awakens from sleep, he should not put his hand into the vessel until he has washed it.”"]},"buhuth":{"en":["This ḥadīth indicates that it is disliked to dip the hands into a vessel before washing them. According to the majority of scholars, if someone puts his hands into it before washing them, this does not make the water impure or remove its status as purifying water. Nevertheless, observing this etiquette is preferable because it promotes cleanliness and prevents doubts and obsessive misgivings."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (394)، وابن خزيمة (146)."},{"num":1314,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنُ عُمَرَ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمَاءِ وَمَا يَنُوبُهُ مِنَ الدَّوَابِّ وَالسِّبَاعِ، فَقَالَ: إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ، لَمْ يَحْمِلِ الْخَبَثَ."],"takhrij":"صحيح: رواه أبو داود (63، 64) والترمذي (67)، والنسائي (52) وابن ماجه (517) كلهم عن محمد بن جعفر بن الزبير، عن عبدالله بن عبدالله بن عمر، عن أبيه عبدالله بن عمر، إلا الترمذي فإنه قال: عن عبيدالله بن عبدالله بن عمر.","grade":"صحيح","chapter_ar":"باب أن الماء إذا كان قلتين لا ينجسه شيء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (63, 64), al-Tirmidhī (67), al-Nasāʾī (52), and Ibn Mājah (517).","chapter_en":"If Water Reaches Two Qullahs, Nothing Makes It Impure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: The Messenger of Allah ﷺ was asked about water and the animals and beasts that repeatedly come to it. The Messenger of Allah ﷺ said: “If the water amounts to two qullahs, it does not carry impurity.”"]},"buhuth":{"en":["The expression “come repeatedly to it” means that they return to it time after time.","A qullah is a large vessel used by the Arabs, similar to a large jar. Jurists estimated its capacity at approximately 250 to 300 raṭls."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (63، 64)، والترمذي (67)، والنسائي (52)، وابن ماجه (517)."},{"num":1315,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمَاءُ لا يُنَجِّسُهُ شَيْءٌ."],"takhrij":"حسن: رواه البزّار – كشف الأستار (249)، والطبراني في الأوسط (2093)، وأبو يعلى (4765) كلهم من طريق شريك، عن المقدام بن شريح، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب أن الماء إذا كان قلتين لا ينجسه شيء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (249), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (2093), and Abū Yaʿlā (4765).","chapter_en":"If Water Reaches Two Qullahs, Nothing Makes It Impure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported that the Prophet ﷺ said: “Nothing makes water impure.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (249)، والطبراني في الأوسط (2093)، وأبو يعلى (4765)."},{"num":1316,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَتَوَضَّأُ مِنْ بِئْرِ بُضَاعَةَ، وَهِيَ بِئْرٌ يُلْقَى فِيهَا الْحِيَضُ وَلَحْمُ الْكِلَابِ وَالنَّتْنُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْمَاءُ طَهُورٌ لَا يُنَجِّسُهُ شَيْءٌ."],"takhrij":"حسن: رواه أبو داود (66) والترمذي (66) والنسائي (326) كلهم من طريق الوليد بن كثير، عن محمد بن كعب القُرَظي، عن عبيدالله بن عبد الرحمن بن رافع، عن أبي سعيد الخدري قال: فذكره..","grade":"حسن","chapter_ar":"باب أن الماء إذا كان قلتين لا ينجسه شيء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (66), al-Tirmidhī (66), and al-Nasāʾī (326).","chapter_en":"If Water Reaches Two Qullahs, Nothing Makes It Impure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: It was said: “O Messenger of Allah, may we perform wuḍūʾ from the well of Buḍāʿah, when menstrual rags, the flesh of dogs, and foul matter are cast into it?” The Messenger of Allah ﷺ said: “Water is purifying; nothing makes it impure.”"]},"buhuth":{"en":["Al-Shāfiʿī said that the well of Buḍāʿah was large and spacious, and impurities would enter it without changing its color, taste, or smell.","The statement that menstrual rags, dog flesh, and foul matter were cast into it does not mean that people deliberately threw these things into the well. Rather, the well was situated in a low area, so floodwater would carry refuse from roads and courtyards into it. Because of the abundance of its water, it was not affected."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (66)، والترمذي (66)، والنسائي (326)."},{"num":1317,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: اغْتَسَلَ بَعْضُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جَفْنَةٍ، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِيَتَوَضَّأَ مِنْهَا أَوْ يَغْتَسِلَ، فَقَالَتْ لَهُ: يَا رَسُولَ اللَّهِ، إِنِّي كُنْتُ جُنُبًا . فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْمَاءَ لَا يُجْنِبُ."],"takhrij":"حسن: رواه أبو داود (68) والترمذي (65) والنسائي (325) وابن ماجه (370، 371) كلهم من طريق سماك بن حرب، عن عكرمة، عن ابن عباس.","grade":"حسن","chapter_ar":"باب أن الماء إذا كان قلتين لا ينجسه شيء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (68), al-Tirmidhī (65), al-Nasāʾī (325), and Ibn Mājah (370, 371).","chapter_en":"If Water Reaches Two Qullahs, Nothing Makes It Impure","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: One of the wives of the Prophet ﷺ performed ghusl using water from a large bowl. The Prophet ﷺ then came to perform wuḍūʾ from it or to bathe with it. She said: “O Messenger of Allah, I was in a state of janābah.” The Messenger of Allah ﷺ said: “Water does not become junub.”"]},"buhuth":{"en":["A jafnah is a large bowl."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (68)، والترمذي (65)، والنسائي (325)، وابن ماجه (370، 371)."},{"num":1318,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لَقِيَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا جُنُبٌ، فَأَخَذَ بِيَدِي فَمَشَيْتُ مَعَهُ حَتَّى قَعَدَ، فَانْسَلَلْتُ فَأَتَيْتُ الرَّحْلَ فَاغْتَسَلْتُ، ثُمَّ جِئْتُ وَهُوَ قَاعِدٌ، فَقَالَ: أَيْنَ كُنْتَ يَا أَبَا هِرٍّ؟ فَقُلْتُ لَهُ: فَقَالَ: سُبْحَانَ اللَّهِ يَا أَبَا هِرٍّ، إِنَّ الْمُؤْمِنَ لَا يَنْجُسُ."],"takhrij":"متفق عليه: رواه البخاري (285)، واللفظ له، ومسلم في الحيض (371)، كلاهما عن أبي رافع، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب مصافحة الجنب","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (285) and Muslim (371).","chapter_en":"Shaking Hands With a Person in a State of Janābah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ met me while I was in a state of janābah. He took me by the hand, and I walked with him until he sat down. Then I slipped away, went to my dwelling, performed ghusl, and returned while he was sitting. He said: “Where were you, O Abū Hurayrah?” I told him, and he said: “Glory be to Allah, O Abū Hurayrah! Indeed, the believer does not become impure.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (285)، ومسلم (371)."},{"num":1319,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَقِيَهُ وَهُوَ جُنُبٌ، فَحَادَ عَنْهُ، فَاغْتَسَلَ، ثُمَّ جَاءَ فَقَالَ: كُنْتُ جُنُبًا، قَالَ: إِنَّ الْمُسْلِمَ لَا يَنْجُسُ."],"takhrij":"صحيح: رواه مسلم في الحيض (372). عن أبي بكر بن أبي شيبة وأبي كريب قالا: حدثنا وكيع، عن مِسْعَرٍ، عن وَاصِل، عن أبي وائل، عن حذيفة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب مصافحة الجنب","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (372).","chapter_en":"Shaking Hands With a Person in a State of Janābah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":4,"content":{"translation":{"en":["Ḥudhayfah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ met him while he was in a state of janābah. Ḥudhayfah moved away from him, performed ghusl, and then returned and said: “I was in a state of janābah.” The Prophet ﷺ said: “Indeed, the Muslim does not become impure.”"]}},"tuhfa":{},"full":1,"rep":[12447],"tks":"صحيح: رواه مسلم (372)."},{"num":1320,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ قَالَ: أَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْرَجْنَا لَهُ مَاءً فِي تَوْرٍ مِنْ صُفْرٍ، فَتَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ، وَمَسَحَ بِرَأْسِهِ فَأَقْبَلَ بِهِ وَأَدْبَرَ، وَغَسَلَ رِجْلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (197) ومسلم في الطهارة (235: 18) كلاهما من حديث عبد الله بن زيد بن عاصم، واللفظ للبخاري، وهذا مختصر من حديث طويل في صفة وضوء النبي صلى الله عليه وسلم. انظر: كتاب الوضوء.","grade":"متفق عليه","chapter_ar":"باب استعمال أواني النحاس للوضوء وغيره","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (197) and Muslim in al-Ṭahārah (235:18). The wording is that of al-Bukhārī.","chapter_en":"Using Copper Vessels for Wuḍūʾ and Other Purposes","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd, may Allah be pleased with him, reported: The Messenger of Allah ﷺ came, so we brought out water for him in a tawr made of copper. He performed wuḍūʾ, washing his face three times, his hands twice each, wiping his head by moving his hands forward and backward, and washing his feet."]},"buhuth":{"en":["Ṣufr means copper, and a tawr is a vessel resembling a washbasin; it has also been said that it is itself a washbasin."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (197)، ومسلم (235: 18)، واللفظ للبخاري."},{"num":1321,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا شَرِبَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ، فَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (35) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر الحديث. ومن طريقه البخاري في الوضوء (172) ومسلم في الطهارة (279).","grade":"متفق عليه","chapter_ar":"باب حكم ولوغ الكلب في الإناء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (35), al-Bukhārī (172), and Muslim (279).","chapter_en":"The Ruling on a Dog Licking From a Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “If a dog drinks from the vessel of one of you, let him wash it seven times.”"]},"buhuth":{"en":["In a narration of Muslim:","“The first of them should be with soil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (35)، والبخاري (172)، ومسلم (279)."},{"num":1322,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ قَالَ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَتْلِ الْكِلَابِ، ثُمَّ قَالَ: مَا بَالُهُمْ، وَبَالُ الْكِلَابِ، ثُمَّ رَخَّصَ فِي كَلْبِ الصَّيْدِ وَكَلْبِ الْغَنَمِ، وَقَالَ: إِذَا وَلَغَ الْكَلْبُ فِي الإِنَاءِ، فَاغْسِلُوهُ سَبْعَ مَرَّاتٍ، وَعَفِّرُوهُ الثَّامِنَةَ فِي التُّرَابِ.","وَفِي رِوَايَةِ: وَرَخَّصَ فِي كَلْبِ الْغَنَمِ، وَالصَّيْدِ، وَالزَّرْعِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (280). من طريق شعبة، عن أبي التيَّاح. سمع مُطَرِّفَ بن عبدالله يحدث عن ابن المُغَفَّل فذكر الحديث.","grade":"صحيح","chapter_ar":"باب حكم ولوغ الكلب في الإناء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (280).","chapter_en":"The Ruling on a Dog Licking From a Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Mughaffal, may Allah be pleased with him, reported: The Messenger of Allah ﷺ ordered that dogs be killed, then he said: “What is the matter with them and with the dogs?” He then granted a concession regarding a hunting dog and a sheepdog, and said: “If a dog licks from a vessel, wash it seven times and rub it with soil the eighth time.” In another narration, he permitted keeping a dog for sheep, hunting, and crops."]},"buhuth":{"en":["The expression “rub it” comes from al-ʿafar, meaning soil; that is, scrub it with soil."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (280)."},{"num":1323,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): فَشَرِبْنَا وَنَحْنُ أَرْبَعُونَ رَجُلًا عِطَاشٌ، مِنْ مَزَادَةِ امْرَأَةٍ مُشْرِكَةٍ، وَغَسَّلْنَا صَاحِبَنَا (الْجُنُبُ)."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3571)، ومسلمٌ في المساجدِ (682)، كلاهما من حديث سلْم بن زريرٍ، قال: سمعت أبا رجاء العُطاردي، قال: حدَّثنا عمران بن حصين .. فذكر الحديث، في حديثٍ طويلٍ، سيأتي بتمامه في دلائل النبوَّةِ.","grade":"متفق عليه","chapter_ar":"باب استعمال أواني المشركين للوضوء وغيره","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Manāqib (3571) and Muslim in al-Masājid (682).","chapter_en":"Using the Vessels of Polytheists for Wuḍūʾ and Other Purposes","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":7,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn, may Allah be pleased with him, reported: We drank, while we were forty thirsty men, from the waterskin of a polytheist woman, and we washed our companion who was in a state of janābah."]},"buhuth":{"en":["A mizādah is a large waterskin."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3571)، ومسلم (682)."},{"num":1324,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدَةَ بِنْتِ أَبِي عُبَيْدَةَ عُبَيْدِ بْنِ فَرْوَةَ، عَنْ خَالَتِهَا كَبْشَةَ بِنْتِ كَعْبِ بْنِ مَالِكٍ، وَكَانَتْ تَحْتَ ابْنِ أَبِي قَتَادَةَ الْأَنْصَارِيِّ، أَنَّهَا أَخْبَرَتْهَا، أَنَّ أَبَا قَتَادَةَ دَخَلَ عَلَيْهَا فَسَكَبَتْ لَهُ وَضُوءًا، فَجَاءَتْ هِرَّةٌ لِتَشْرَبَ مِنْهُ، فَأَصْغَى لَهَا الْإِنَاءَ حَتَّى شَرِبَتْ، قَالَتْ كَبْشَةُ: فَرَآنِي أَنْظُرُ إِلَيْهِ، فَقَالَ: أَتَعْجَبِينَ يَا ابْنَةَ أَخِي؟ قَالَتْ: فَقُلْتُ: نَعَمْ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّهَا لَيْسَتْ بِنَجَسٍ، إِنَّمَا هِيَ مِنَ الطَّوَّافِينَ عَلَيْكُمْ أَوِ الطَّوَّافَاتِ."],"takhrij":"حسن: رواه مالك في الطهارة (13) عن إسحاق بن عبدالله بن أبي طلحة، عن حُميدة بنت أبي عبيدة، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب طهارة سؤر الهرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan Ṣaḥīḥ: Narrated by Mālik (13), Abū Dāwūd (75), al-Tirmidhī (92), and al-Nasāʾī (68).","chapter_en":"The Purity of Water Left Over by a Cat","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":8,"content":{"translation":{"en":["Ḥumaydah bint ʿUbayd ibn Rifāʿah reported from Kabshah bint Kaʿb ibn Mālik, who was married to the son of Abū Qatādah: Abū Qatādah, may Allah be pleased with him, entered upon her, and she poured water for him to perform wuḍūʾ. A cat came to drink from it, so Abū Qatādah tilted the vessel toward it until it drank. Kabshah said: He saw me looking at him and said: “Are you surprised, O daughter of my brother?” I said: “Yes.” He said: The Messenger of Allah ﷺ said: “It is not impure. It is only among those male and female creatures that frequently move about among you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (13)، وأبو داود (75)، والترمذي (92)، والنسائي (68)."},{"num":1325,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْفِطْرَةُ خَمْسٌ، أَوْ خَمْسٌ مِنَ الْفِطْرَةِ، الْخِتَانُ، وَالِاسْتِحْدَادُ، وَتَقْلِيمُ الأَظْفَارِ، وَنَتْفُ الإِبِطِ، وَقَصُّ الشَّارِبِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5889، 5891، 6297) ومسلم في الطهارة (257). كلاهما من حديث ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5889, 5891, 6297) and Muslim (257).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Prophet ﷺ said: “The fiṭrah consists of five—or five things are from the fiṭrah: circumcision, shaving the pubic hair, clipping the nails, plucking the armpit hair, and trimming the moustache.”"]},"buhuth":{"en":["Al-Istiḥdād means shaving the pubic hair, so named because a blade is used."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5889، 5891، 6297)، ومسلم (257)."},{"num":1326,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَالِفُوا الْمُشْرِكِينَ، وَفِّرُوا اللِّحَى وَأَحْفُوا الشَّوَارِبَ، وَكَانَ ابْنُ عُمَرَ إِذَا حَجَّ أَوِ اعْتَمَرَ قَبَضَ عَلَى لِحْيَتِهِ فَمَا فَضَلَ أَخَذَهُ.","وَفِي رِوَايَةِ: انْهَكُوا الشَّوَارِبَ وَأَعْفُوا اللِّحَى."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5892، 5893) واللفظ له، ومسلم في الطهارة (259) وفيه: أحفوا الشوارب، وأعفوا اللحى وفي لفظ: أحفوا الشوارب، وأوفوا اللحى، وفي لفظ عن النبي صلى الله عليه وسلم أنه أمر بإحفاء الشوارب وإعفاء اللحية.","grade":"متفق عليه","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5892, 5893) and Muslim (259).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported that the Prophet ﷺ said: “Differ from the polytheists: let the beards grow and trim the moustaches closely.” In another narration: “Trim the moustaches thoroughly and leave the beards to grow.” Whenever Ibn ʿUmar, may Allah be pleased with them, performed Ḥajj or ʿUmrah, he would grasp his beard and cut whatever extended beyond his handful."]},"buhuth":{"en":["Trimming the moustache closely means cutting it until it becomes short and thin; it may also mean being thorough in trimming it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5892، 5893)، ومسلم (259)."},{"num":1327,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَشْرٌ مِنَ الْفِطْرَةِ: قَصُّ الشَّارِبِ، وَإِعْفَاءُ اللِّحْيَةِ، وَالسِّوَاكُ، وَاسْتِنْشَاقُ الْمَاءِ، وَقَصُّ الأَظْفَارِ، وَغَسْلُ الْبَرَاجِمِ، وَنَتْفُ الإِبِطِ، وَحَلْقُ الْعَانَةِ، وَانْتِقَاصُ الْمَاءِ.","قَالَ زَكَرِيَّاءُ: قَالَ مُصْعَبٌ: وَنَسِيتُ الْعَاشِرَةَ، إِلَّا أَنْ تَكُونَ: الْمَضْمَضَةَ.","زَادَ قُتَيْبَةُ: قَالَ وَكِيعٌ: انْتِقَاصُ الْمَاءِ يَعْنِي الِاسْتِنْجَاءَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (261). من حديث وكيع، عن زكريا بن أبي زائدة، عن مصعب بن شيبة، عن طلق بن حبيب، عن عبدالله بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (261).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported that the Messenger of Allah ﷺ said: “Ten things are from the fiṭrah: trimming the moustache, letting the beard grow, using the siwāk, drawing water into the nose, clipping the nails, washing the finger joints, plucking the armpit hair, shaving the pubic hair, and cleansing oneself with water.”","Zakariyyā said that Muṣʿab said: “I forgot the tenth, unless it was rinsing the mouth.”","Ibn Qutaybah added that Wakīʿ said: “Cleansing oneself with water means istinjāʾ.”"]},"buhuth":{"en":["Al-Barājim is the plural of burjumah, referring to the knuckles and joints of the fingers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (261)."},{"num":1328,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: جُزُّوا الشَّوَارِبَ وَأَرْخُوا اللِّحَى، خَالِفُوا الْمَجُوسَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (260). من حديث العلاء بن عبد الرحمن بن يعقوب مولى الحُرَقَةِ، عن أبيه، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (260).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Trim the moustaches and let the beards grow; differ from the Magians.”"]},"buhuth":{"en":["The expressions “let them grow,” “leave them,” and “let them become full” all mean allowing the beard to remain abundant."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15414],"tks":"صحيح: رواه مسلم (260)."},{"num":1329,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ، وَتَقْلِيمِ الْأَظْفَارِ، وَنَتْفِ الإِبِطِ، وَحَلْقِ الْعَانَةِ، أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً."],"takhrij":"صحيح: رواه مسلم في الطهارة (258)، من حديث أبي عمران الجونِّي، عن أنس فذكر الحديث. وحكمه مرفوع، وقد جاء التصريح بذلك في رواية أبي داود (4200) بقوله: وقَّتَ لنا رسول الله صلى الله عليه وسلم....","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (258).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: “A time limit was set for us regarding trimming the moustache, clipping the nails, plucking the armpit hair, and shaving the pubic hair: we were not to leave them for more than forty days.”"]},"buhuth":{"ar":["وجاء التصريح برفعه في رواية أبي داود (٤٢٠٠) بقوله:","«وَقَّتَ لَنَا رَسُولُ اللهِ ﷺ…»"],"en":["Its attribution to the Messenger of Allah ﷺ is made explicit in Abū Dāwūd (4200):","“The Messenger of Allah ﷺ set a time limit for us…”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (258)."},{"num":1330,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: ضِفْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَأَمَرَ بِجَنْبٍ فَشُوِيَ، وَأَخَذَ الشَّفْرَةَ فَجَعَلَ يَحُزُّ لِي بِهَا مِنْهُ، قَالَ: فَجَاءَ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ، قَالَ: فَأَلْقَى الشَّفْرَةَ، وَقَالَ: مَا لَهُ تَرِبَتْ يَدَاهُ؟ وَقَامَ يُصَلِّ، زَادَ الْأَنْبَارِيُّ: وَكَانَ شَارِبِي وَفَى فَقَصَّهُ لِي عَلَى سِوَاكٍ أَوْ قَالَ: أَقُصُّهُ لَكَ عَلَى سِوَاكٍ."],"takhrij":"حسن: رواه أبو داود (188) والترمذي في الشمائل (159) كلاهما من طريق مسعر، عن أبي صخر جامع بن شداد، عن المغيرة بن عبدالله (اليشكري) عن المغيرة بن شعبة فذكر الحديث. واللفظ لأبي داود. ولفظ الترمذي مختصر، ومن هذا الطريق رواه أيضاً الإمام أحمد (18212). وإسناده حسنٌ، لأجل المغيرة بن عبدالله اليشكري، فهو حسن الحديث. وانظر المزيد من التفصيل في كتاب الوضوء، باب ترك الوضوء مما مسَّته النار.","grade":"حسن","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (188), al-Tirmidhī in al-Shamāʾil (159), and Aḥmad (18212).","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported: I was a guest of the Prophet ﷺ one night. He ordered that a side of meat be roasted, then took a blade and began slicing pieces from it for me. Bilāl then came to inform him that it was time for prayer, so he put down the blade and said, “What is the matter with him? May his hands be dusted!” Al-Mughīrah said: My moustache had grown long, so the Messenger of Allah ﷺ trimmed it for me over a siwāk, or he said: “I will trim it for you over a siwāk.”"]}},"tuhfa":{},"full":1,"rep":[1647],"tks":"حسن: رواه أبو داود (188)، والترمذي في الشمائل (159)، وأحمد (18212)."},{"num":1331,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ لَمْ يَأْخُذْ شَارِبَهُ فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه الترمذي (2761) والنسائي (13) كلاهما من طريق يوسف ابن صهيب، عن حبيب بن يسار، عن زيد بن أرقم فذكر مثله.","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2761) and al-Nasāʾī (13), both through Yūsuf ibn Ṣuhayb, from Ḥabīb ibn Yasār, from Zayd ibn Arqam, with a similar report.","chapter_en":"The Traits of the Fiṭrah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":9,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Whoever does not trim his moustache is not from us.”"]},"buhuth":{"en":["Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.”","Al-Aʿẓamī said: It is as he said, for its narrators are trustworthy and its chain is ṣaḥīḥ. Some narrations mention Abū Ramlah—ʿAbd Allāh ibn Abī Umāmah al-Ḥārithī al-Madanī—between Ḥabīb ibn Yasār and Zayd ibn Arqam; this is an instance of an additional narrator in an otherwise connected chain.","As for what is reported from Ibn ʿAbbās—that the Prophet ﷺ used to trim or take from his moustache and that Ibrāhīm, the Friend of the Most Merciful, used to do so—it is weak. Al-Tirmidhī (2760) narrated it through Simāk, from ʿIkrimah, from Ibn ʿAbbās. Simāk is Ibn Ḥarb ibn Aws al-Kūfī; he is ṣadūq, but his narration from ʿIkrimah is inconsistent, and he changed in his later years and would sometimes accept prompting. I did not find anyone who corroborated him in this report. See the remaining narrations in the Book of Manners and Clothing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2761)، والنسائي (13)."},{"num":1332,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اخْتَتَنَ إِبْرَاهِيمُ عَلَيْهِ السَّلَام وَهُوَ ابْنُ ثَمَانِينَ سَنَةً بِالْقَدُّومِ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3356) ومسلم في كتاب الفضائل (2370) كلاهما عن قتيبة بن سعيد، حدَّثنا مغيرة بن عبد الرحمن القرشي، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الختان","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3356) and Muslim (2370).","chapter_en":"What Has Been Reported Concerning Circumcision","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Ibrāhīm, peace be upon him, circumcised himself when he was eighty years old, using the qadūm.”"]},"buhuth":{"en":["The expression “with the qadūm” may refer to the name of a place, or it may refer to a tool resembling an adze or axe. The latter is generally intended here."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8375],"tks":"متفق عليه: رواه البخاري (3356)، ومسلم (2370)."},{"num":1333,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَذْكُرُ اللَّهَ عَلَى كُلِّ أَحْيَانِهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (373). من حديث ابن أبي زائدة، عن أبيه، عن خالد ابن سلمة، عن البَهِيِّ، عن عروة، عن عائشة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب ذكر الله تعالى في كل حال","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (373).","chapter_en":"Remembering Allah Most High in Every Circumstance","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":11,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: The Prophet ﷺ used to remember Allah in all of his circumstances."]}},"tuhfa":{},"full":1,"rep":[10793],"tks":"صحيح: رواه مسلم (373)."},{"num":1334,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ حَزْمٍ قَالَ: كَانَ فِي كِتَابِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَلَا يَمَسَّ الْقُرْآنَ إِلَّا طَاهِرٌ."],"takhrij":"صحيح وجادة: رواه مالك في كتاب القرآن (1) عن عبدالله بن أبي بكر بن عمرو بن حزم، أنّ في الكتاب الذي كتبه رسول الله صلى الله عليه وسلم لعمرو بن حزم كان فيه (فذكر الحديث).","grade":"صحيح وجادة","chapter_ar":"باب ما جاء: لا يمس القرآن إلا طاهر","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ by written transmission: Narrated by Mālik in Kitāb al-Qurʾān (1), from ʿAbdullāh ibn Abī Bakr ibn ʿAmr ibn Ḥazm, that in the document which the Messenger of Allah ﷺ wrote for ʿAmr ibn Ḥazm was this report.","chapter_en":"What Has Been Reported Concerning the Statement: “No One Should Touch the Qurʾān Except One Who Is Pure”","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":12,"content":{"translation":{"en":["ʿAmr ibn Ḥazm, may Allah be pleased with him, reported: It was written in the document of the Messenger of Allah ﷺ: “No one should touch the Qurʾān except one who is pure.”"]},"buhuth":{"en":["It was also narrated by ʿAbd al-Razzāq (1328), al-Dāraquṭnī (435), and al-Bayhaqī (1/87), all through Maʿmar, from ʿAbd Allāh ibn Abī Bakr, from his father, who said that this was in the document of the Prophet ﷺ to ʿAmr ibn Ḥazm.","This route is mursal, because ʿAbd Allāh ibn Abī Bakr ibn Muḥammad ibn ʿAmr ibn Ḥazm narrates it from his father Abū Bakr and from his grandfather Muḥammad ibn ʿAmr ibn Ḥazm. Muḥammad ibn ʿAmr ibn Ḥazm al-Anṣārī, Abū ʿAbd al-Malik al-Madanī, saw the Prophet ﷺ but has no direct hearing except from the Companions. For that reason al-Dāraquṭnī said: “It is mursal, and its narrators are trustworthy.” It has also been narrated with a connected chain, which will be discussed in detail in the Book of Zakāh.","Ibn ʿAbd al-Barr said: “There is no disagreement that Mālik narrates this hadith as mursal. It has also been narrated with a connected chain by a sound route, and it is a famous document among the scholars of sīrah, well known among the people of knowledge to such a degree that its fame renders detailed isnād support unnecessary.”","Al-Aʿẓamī said that the narrations which follow support it, even though none of those supporting reports is entirely free from weakness.","Among them is the report from Ḥakīm ibn Ḥizām that the Prophet ﷺ said: “Do not touch the Qurʾān unless you are pure.” Al-Ṭabarānī narrated it in al-Kabīr (3/229); al-Dāraquṭnī (440) also narrated it, and al-Ḥākim authenticated it (3/485). Its chain includes Suwayd Abū Ḥātim and Maṭar al-Warrāq, both of whom were discussed by the critics. Al-Ḥāzimī considered its chain ḥasan, and a statement was transmitted from al-Dāraquṭnī that all of its narrators are trustworthy. Al-Aʿẓamī said he did not find that statement in al-Dāraquṭnī’s Sunan; thus al-Ḥāzimī’s grading has some basis, although the soul is not fully at ease with declaring it ḥasan.","Also in this chapter is the marfūʿ report from Ibn ʿUmar: “No one should touch the Qurʾān except one who is pure.” It was narrated by al-Ṭabarānī in al-Kabīr (13217) and al-Ṣaghīr (1162), al-Dāraquṭnī (437), al-Bayhaqī, and others. Its chain includes Sulaymān ibn Mūsā al-Ashdaq, concerning whom the critics differed. Ibn Ḥajar said in al-Talkhīṣ that its chain is acceptable; al-Haythamī said its narrators were declared trustworthy; and al-Jawzajānī said: “This is a well-known ḥasan hadith.”","There is likewise a marfūʿ report from ʿUthmān ibn Abī al-ʿĀṣ with the wording, “Do not touch the Qurʾān unless you are pure,” but its routes contain weakness and disconnection.","Al-Aʿẓamī concluded: The summary in this chapter is that the hadith is authentic as a written transmission, and the reports in the chapter strengthen this written transmission. The heart is reassured regarding the soundness of a hadith such as this, and a number of Companions, Followers, and rightly guided imams after them held to its meaning.","Muṣʿab ibn Saʿd ibn Abī Waqqāṣ said: “I was holding the muṣḥaf for Saʿd ibn Abī Waqqāṣ and scratched myself. Saʿd said: Perhaps you touched your private part? I said: Yes. He said: Get up and perform wuḍūʾ. So I performed wuḍūʾ and returned.” Mālik narrated it in al-Ṭahārah (59), and its chain is ṣaḥīḥ.","Sālim, ʿAṭāʾ, Ṭāwūs, al-Qāsim, and ʿĀmir al-Shaʿbī disliked reading from the muṣḥaf without wuḍūʾ.","Ibn ʿAbd al-Barr said in al-Istidhkār (8/10–11): “The jurists of the major regions upon whom fatwā revolves, together with their followers, agreed that the muṣḥaf should not be touched except by one who is pure.” He mentioned Mālik, al-Shāfiʿī, Abū Ḥanīfah, al-Thawrī, al-Awzāʿī, Aḥmad, Isḥāq, Abū Thawr, and Abū ʿUbayd, and this was also transmitted from a group of Companions and Followers.","Isḥāq ibn Rāhawayh said: “No one should read directly from the muṣḥaf unless he has wuḍūʾ. This is not because of Allah’s statement, ‘None touch it except the purified’ [al-Wāqiʿah 56:79], but because of the statement of the Messenger of Allah ﷺ: ‘No one should touch the Qurʾān except one who is pure.’”","Other scholars permitted touching the muṣḥaf without wuḍūʾ, citing the Prophet’s ﷺ statement, “The believer does not become impure.” They understood the prohibition as referring to the junub and menstruating woman, and understood the Qurʾānic verse as referring to the heavenly Book touched only by purified angels.","Al-Baghawī said in Sharḥ al-Sunnah (2/48): “Al-Ḥakam, Ḥammād, and Abū Ḥanīfah permitted carrying and touching it. Abū Ḥanīfah said: He should not touch the written portion.” ʿAbd al-Razzāq (1347) narrated from Saʿīd ibn Jubayr that he urinated, washed his face, then took the muṣḥaf and read from it. Al-Aʿẓamī remarked that Marwān ibn Muʿāwiyah was a Kūfan who settled in Makkah; perhaps ʿAbd al-Razzāq did not recognize him at first, then later realized who he was, making the chain connected."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح وجادة: رواه مالك (1)، عن عبد الله بن أبي بكر بن عمرو بن حزم، أن في الكتاب الذي كتبه رسول الله ﷺ لعمرو بن حزم كان فيه، فذكر الحديث."},{"num":1335,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ يَقُولُ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْهَاجِرَةِ، فَأُتِيَ بِوَضُوءٍ فَتَوَضَّأَ، فَجَعَلَ النَّاسُ يَأْخُذُونَ مِنْ فَضْلِ وَضُوئِهِ فَيَتَمَسَّحُونَ بِهِ، فَصَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ وَبَيْنَ يَدَيْهِ عَنَزَةٌ... ( فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (187)، وبوّب بقوله: استعمال فضل وَضوء الناس. من حديث شعبة قال: ثنا الحكم، قال: سمعتُ أبا جحيفة فذكره.","grade":"متفق عليه","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (187), who titled the chapter, “Using the leftover wuḍūʾ water of people,” through Shuʿbah, from al-Ḥakam, who said: I heard Abū Juḥayfah, and he mentioned the report.","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Juḥayfah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ came out to us at midday. Water was brought to him for wuḍūʾ, and he performed wuḍūʾ. The people began taking from the water left over from his wuḍūʾ and wiping themselves with it. The Prophet ﷺ then prayed two rakʿahs for Ẓuhr and two rakʿahs for ʿAṣr, with a short spear placed in front of him."]},"buhuth":{"en":["In another narration in al-Bukhārī, in the Book of Prayer (376), and Muslim, in the Book of Prayer (503), through ʿUmar ibn Abī Zāʾidah, from ʿAwn ibn Abī Juḥayfah, his father said: “I saw the Messenger of Allah ﷺ in a red leather tent, and I saw Bilāl take the water from the Messenger of Allah’s ﷺ wuḍūʾ. I saw the people rushing toward that water; whoever obtained some of it wiped himself with it, and whoever did not get any took moisture from his companion’s hand. Then I saw Bilāl take a short spear and plant it in the ground. The Prophet ﷺ came out wearing a red garment, with it raised, and prayed two rakʿahs with the people facing the spear. I saw people and animals passing beyond the spear.”","The expression “mushammiran” means raising his garment to the middle of his shins, as stated in a narration in Muslim: “It is as though I can see the whiteness of his shins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (187)، وبوب بقوله: «استعمال فضل وضوء الناس»."},{"num":1336,"demo":false,"sanad":"","matn":["عَنِ ابْنِ شِهَابٍ قَالَ: أَخْبَرَنِي مَحْمُودُ بْنُ الرَّبِيعِ قَالَ: وَهُوَ الَّذِي مَجّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي وَجْهِهِ، وَهُوَ غُلَامٌ مِنْ بِئْرِهِمْ، وَقَالَ عُرْوَةُ: عَنْ الْمِسْوَرِ وَغَيْرِهِ يُصَدِّقُ كُلُّ وَاحِدٍ مِنْهُمَا صَاحِبَهُ، وَإِذَا تَوَضَّأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَادُوا يَقْتَتِلُونَ عَلَى وَضُوئِهِ."],"takhrij":"صحيح: رواه البخاري في الوضوء (189). من طريق صالح بن كيسان، عن ابن شهاب فذكره.","grade":"صحيح","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (189).","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Ibn Shihāb reported: Maḥmūd ibn al-Rabīʿ informed me—and he was the boy into whose face the Messenger of Allah ﷺ playfully sprayed water from their well. ʿUrwah also narrated from al-Miswar and others, each confirming the other: “When the Prophet ﷺ performed wuḍūʾ, they would almost fight over the water from his wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (189)."},{"num":1337,"demo":false,"sanad":"","matn":["عَنِ السَّائِبِ بْنِ يَزِيدَ قَالَ: ذَهَبَتْ بِي خَالَتِي إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي وَجِعٌ فَمَسَحَ رَأْسِي وَدَعَا لِي بِالْبَرَكَةِ، ثُمَّ تَوَضَّأَ فَشَرِبْتُ مِنْ وَضُوئِهِ، ثُمَّ قُمْتُ خَلْفَ ظَهْرِهِ، فَنَظَرْتُ إِلَى خَاتَمِ النُّبُوَّةِ بَيْنَ كَتِفَيْهِ مِثْلَ زِرِّ الْحَجَلَةِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (190) ومسلم في الفضائل (2345)، كلاهما من طريق حاتم بن إسماعيل، عن الجعد، قال: سمعت السائب بن يزيد.. فذكره الحديث. وسيعاد الحديث في صفة النبي صلى الله عليه وسلم.","grade":"متفق عليه","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (190) and Muslim in al-Faḍāʾil (2345).","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Al-Sāʾib ibn Yazīd, may Allah be pleased with him, reported: My maternal aunt took me to the Prophet ﷺ and said: “O Messenger of Allah, my nephew has pain in his feet.” He wiped my head and supplicated for blessing for me. Then he performed wuḍūʾ, and I drank from the water left over from his wuḍūʾ. I then stood behind him and looked at the Seal of Prophethood between his shoulders; it was like the button of a bridal canopy."]},"buhuth":{"en":["The expression waqiʿ is read with a kasrah on the qāf; Muslim’s narration has wajiʿ. It refers to pain in the feet.","The expression “the button of a ḥajalah” has been explained as the button of one of the decorated canopies or chambers furnished with cloth, couches, and curtains, having loops and buttons.","It has also been said that ḥajalah refers to a bird, in which case its “button” means its egg. This is supported by another narration describing the Seal as being “like a pigeon’s egg.”","See Fatḥ al-Bārī (1/296)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9395],"tks":"متفق عليه: رواه البخاري (190)، ومسلم (2345)."},{"num":1338,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ نَازِلٌ بِالْجِعْرَانَةِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ وَمَعَهُ بِلَالٌ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْرَابِيٌّ فَقَالَ: أَلَا تُنْجِزُ لِي مَا وَعَدْتَنِي، فَقَالَ لَهُ: أَبْشِرْ، فَقَالَ: قَدْ أَكْثَرْتَ عَلَيَّ مِنْ أَبْشِرْ، فَأَقْبَلَ عَلَى أَبِي مُوسَى وَبِلَالٍ كَهَيْئَةِ الْغَضْبَانِ، فَقَالَ: رَدَّ الْبُشْرَى، فَاقْبَلَا أَنْتُمَا، قَالَا: قَبِلْنَا، ثُمَّ دَعَا بِقَدَحٍ فِيهِ مَاءٌ، فَغَسَلَ يَدَيْهِ وَوَجْهَهُ فِيهِ، وَمَجَّ فِيهِ، ثُمَّ قَالَ: اشْرَبَا مِنْهُ، وَأَفْرِغَا عَلَى وُجُوهِكُمَا وَنُحُورِكُمَا، وَأَبْشِرَا، فَأَخَذَا الْقَدَحَ فَفَعَلَا، فَنَادَتْ أُمُّ سَلَمَةَ مِنْ وَرَاءِ السِّتْرِ: أَنْ أَفْضِلَا لِأُمِّكُمَا، فَأَفْضَلَا لَهَا مِنْهُ طَائِفَةً."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4328) وأخرجه في الوضوء (196) مختصرا، ومسلم في الفضائل (2497)، كلاهما من طريق أبي أسامة، عن يزيد بن عبدالله بن أبي بُردة، عن جدِّه أبي بردة، عن أبي موسى.. فذكره.","grade":"متفق عليه","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (196, 4328) and Muslim (2497). The wording is that of al-Bukhārī, while Muslim’s wording is similar.","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported: I was with the Prophet ﷺ while he was staying at al-Jiʿrānah between Makkah and Madīnah, and Bilāl was with him. A Bedouin came to the Prophet ﷺ and said: “Will you not fulfill what you promised me?” He said: “Receive glad tidings.” The Bedouin replied: “You have told me ‘Receive glad tidings’ too many times.” The Prophet ﷺ then turned toward Abū Mūsā and Bilāl, appearing displeased, and said: “He has rejected the glad tidings, so you two accept them.” They said: “We accept them.” He then called for a vessel containing water, washed his hands and face in it, and spat into it. Then he said: “Drink from it, pour it over your faces and upper chests, and receive glad tidings.” They took the vessel and did so. Umm Salamah, may Allah be pleased with her, called from behind the curtain: “Leave some for your mother.” So they left a portion of it for her."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9250,10039,14647],"tks":"متفق عليه: رواه البخاري (196، 4328)، ومسلم (2497). واللفظ للبخاري، ولفظ مسلم نحوه."},{"num":1339,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: مَرِضْتُ مَرَضًا، فَأَتَانِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، وَأَبُو بَكْرٍ، وَهُمَا مَاشِيَانِ فَوَجَدَانِي أُغْمِيَ عَلَيَّ، فَتَوَضَّأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَبَّ وَضُوءَهُ عَلَيَّ... ( فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: أخرجه البخاري في المرضى (5651) ومسلم في الفرائض (1616)، كلاهما من طريق سفيان، عن ابن المنكدر، سمع جابر بن عبدالله فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5651) and Muslim (1616).","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: I became seriously ill. The Prophet ﷺ came walking to visit me, accompanied by Abū Bakr, may Allah be pleased with him,. They found me unconscious. The Prophet ﷺ performed wuḍūʾ and then poured the water from his wuḍūʾ over me."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5651)، ومسلم (1616)."},{"num":1340,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَيَّةَ قال: رَأَيْتُ عَلِيًّا تَوَضَّأَ ثَلَاثًا ثَلَاثًا، ثُمَّ قَامَ فَشَرِبَ فَضْلَ وَضُوئِهِ وَقَالَ: صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا صَنَعْتُ."],"takhrij":"حسن: رواه النسائي (136) من طريق شعبة، عن أبي إسحاق، عن أبي حية فذكر مثله. ورواه الترمذي (48) من طريق أبي الأحوص عن أبي إسحاق به.","grade":"حسن","chapter_ar":"باب استعمال فضل الوضوء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī (136) and al-Tirmidhī (48).","chapter_en":"Using Water Left Over From Wuḍūʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":13,"content":{"translation":{"en":["Abū Ḥayyah reported: I saw ʿAlī, may Allah be pleased with him, perform wuḍūʾ, washing three times. He then stood and drank the water remaining from his wuḍūʾ and said: “The Messenger of Allah ﷺ did just as I have done.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (136)، والترمذي (48)."},{"num":1341,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدٍ الْحِمْيَرِيِّ قَالَ: لَقِيتُ رَجُلًا صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعَ سِنِينَ كَمَا صَحِبَهُ أَبُو هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَغْتَسِلَ الْمَرْأَةُ بِفَضْلِ الرَّجُلِ، أَوْ يَغْتَسِلَ الرَّجُلُ بِفَضْلِ الْمَرْأَةِ، زَادَ مُسَدَّدٌ: وَلْيَغْتَرِفَا جَمِيعًا."],"takhrij":"صحيح:  رواه أبو داود (81) والنسائي (238) كلاهما من طريق أبي عوانة، عن داود الأوْدي، عن حُميد بن عبد الرحمن قال، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن الوضوء بفضل وضوء المرأة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (81) and al-Nasāʾī (238).","chapter_en":"The Prohibition of Performing Wuḍūʾ With Water Left Over From a Woman’s Purification","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Ḥumayd al-Ḥimyarī reported: I met a man who had accompanied the Prophet ﷺ for four years, just as Abū Hurayrah, may Allah be pleased with him, had accompanied him. He said: The Messenger of Allah ﷺ prohibited a woman from bathing with water left over by a man, or a man from bathing with water left over by a woman; rather, they should both scoop from the vessel together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (81)، والنسائي (238)."},{"num":1342,"demo":false,"sanad":"","matn":["عَنِ الْحَكَمِ بْنِ عَمْرٍو وَهُوَ الْأَقْرَعُ، أن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ بِفَضْلِ طَهُورِ الْمَرْأَةِ."],"takhrij":"حسن: رواه أبو داود (82) والترمذي (64) والنسائي (343) وابن ماجه (373) كلهم من طريق أبي داود الطيالسي، عن شعبة، عن عاصم قال: سمعت أبا حاجب يحدث عن الحكم بن عمرو، فذكر مثله.","grade":"حسن","chapter_ar":"باب النهي عن الوضوء بفضل وضوء المرأة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (82), al-Tirmidhī (64), al-Nasāʾī (343), and Ibn Mājah (373).","chapter_en":"The Prohibition of Performing Wuḍūʾ With Water Left Over From a Woman’s Purification","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":14,"content":{"translation":{"en":["Al-Ḥakam ibn ʿAmr, known as al-Aqraʿ may Allah be pleased with him, reported that the Prophet ﷺ prohibited a man from performing wuḍūʾ with water left over from a woman’s purification."]},"buhuth":{"en":["Al-Tirmidhī added:","“Or he said: from her leftover water.”","Al-Tirmidhī said: “This is a Ḥasan ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (82)، والترمذي (64)، والنسائي (343)، وابن ماجه (373)."},{"num":1343,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ امْرَأَةً مِنْ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اغْتَسَلَتْ مِنْ جَنَابَةٍ، فَتَوَضَّأَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوِ اغْتَسَلَ مِنْ فَضْلِهَا.","وَفِي رِوَايَةِ: فَذَكَرَتْ ذَلِكَ لَهُ فَقَالَ: إِنَّ الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ."],"takhrij":"حسن: رواه النسائي (325)، وابن ماجه (91)، وأحمد (2101)، والحاكم (568) كلهم من حديث سفيان الثوري، عن سماك، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب إباحة الوضوء بفضل غسل المرأة من الجنابة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī (325), Ibn Mājah (370), Aḥmad (2101), and al-Ḥākim (1/159).","chapter_en":"The Permissibility of Performing Wuḍūʾ With Water Left Over From a Woman’s Ghusl From Janābah","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: One of the wives of the Prophet ﷺ performed ghusl from janābah, and the Prophet ﷺ then performed wuḍūʾ—or ghusl—with the water remaining from her bath. In another narration, she mentioned this to him, and he said:","“Nothing makes water impure.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (325)، وابن ماجه (91)، وأحمد (2101)، والحاكم (568)."},{"num":1344,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ مِنْ إِنَاءٍ، هُوَ الْفَرَقُ مِنَ الْجَنَابَةِ.","وَفِي رِوَايَةِ: قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ مِنْ قَدَحٍ، يُقَالُ لَهُ الْفَرَقُ."],"takhrij":"متفق عليه: الرواية الأولى رواها مالك في الطهارة (68) وعنه مسلم في الحيض (319)، وسبق ذكرها في باب المستحب من الماء للغُسْل والوُضوء.","grade":"متفق عليه","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: The first wording was narrated by Mālik (68) and Muslim (319), and the second wording by al-Bukhārī (250) and Muslim (319).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: The Messenger of Allah ﷺ used to perform ghusl from janābah using a vessel called a faraq.","In another narration, she said: “The Prophet ﷺ and I used to perform ghusl from the same vessel, a container called a faraq.”"]},"buhuth":{"en":["A faraq, with either a fatḥah or sukūn on the rāʾ, is a vessel said to hold sixteen raṭls. Sufyān said that a faraq equals three ṣāʿs.","Muslim narrated from Abū Salamah ibn ʿAbd al-Raḥmān:","“The wives of the Prophet ﷺ used to cut some of the hair of their heads until it became like a wafrah.”","Al-Bukhārī also mentioned this briefly (351).","The statement means that they would shorten and lighten their hair until it became like a wafrah, which is hair reaching approximately to the ears without extending beyond them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: الرواية الأولى رواها مالك (68)، ومسلم (319)، والرواية الثانية رواها البخاري (250)، ومسلم (319)."},{"num":1345,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالْمَرْأَةُ مِنْ نِسَائِهِ يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ.","زَادَ مُسْلِمٌ (أَي ابْنُ إبْرَاهِيمَ) وَوَهْبُ بْنُ جَرِيرٍ، عَنْ شُعْبَةَ: مِنَ الْجَنَابَةِ."],"takhrij":"صحيح: رواه البخاري في الغسل (264)، عن أبي الوليد (هو ابن جرير بن حازم)، قال: حدَّثنا شعبة، عن عبدالله بن عبدالله بن جبرٍ، قال: سمعت أنس بن مالكٍ يقول فذكره.","grade":"صحيح","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (264).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: The Prophet ﷺ and one of his wives used to perform ghusl from the same vessel.","Muslim ibn Ibrāhīm and Wahb added, from Shuʿbah: “From janābah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (264)."},{"num":1346,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ حَدَّثَتْهُ، أَنَّ أُمَّ سَلَمَةَ حَدَّثَتْهَا قَالْ: كَانَتْ هِيَ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَغْتَسِلَانِ فِي الإِنَاءِ الْوَاحِدِ مِنَ الْجَنَابَةِ."],"takhrij":"متفق عليه: أخرجه البخاري في الحيض (322)، ومسلم في الحيض (324)، كلاهما من طريق أبي سلمة بن عبد الرحمن، عن زينب ابنة أبي سلمة، عن أمها فذكرت الحديث. وفيه قصَّة، انظر كتاب الحيض، باب الاضطجاع مع الحائض في لحافٍ واحدٍ.","grade":"متفق عليه","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (322) and Muslim (324).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Zaynab bint Umm Salamah reported that her mother, Umm Salamah may Allah be pleased with her, told her: She and the Messenger of Allah ﷺ used to perform ghusl from janābah using the same vessel."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (322)، ومسلم (324)."},{"num":1347,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أَخْبَرَتْنِي مَيْمُونَةُ، أَنَّهَا كَانَتْ تَغْتَسِلُ هِيَ وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي إِنَاءٍ وَاحِدٍ."],"takhrij":"متفق عليه: رواه مسلم في الحيض (322) عن عمرو بن دينار، عن أبي الشعثاء، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (322) and al-Bukhārī (253).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās, may Allah be pleased with them, reported: Maymūnah, may Allah be pleased with her, informed me that she and the Prophet ﷺ used to perform ghusl from the same vessel."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (322)، والبخاري (253)."},{"num":1348,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّهُ قَالَ: كَانَ الرِّجَالُ وَالنِّسَاءُ يَتَوَضَّئُونَ فِي زَمَانِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمِيعًا."],"takhrij":"صحيح: رواه مالك في الطهارة (15) عن نافع، عن عبدالله بن عمر فذكر مثله، وعنه البخاري في الوضوء  (193)","grade":"صحيح","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (15) and al-Bukhārī (193).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, used to say: “Men and women used to perform wuḍūʾ together during the time of the Prophet ﷺ.”"]},"buhuth":{"en":["Abū Dāwūd (79, 80) added:","“From one vessel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (15)، والبخاري (193)."},{"num":1349,"demo":false,"sanad":"","matn":["عَنْ أُمَّ صُبَيَّةَ الْجُهَنِيَّةِ قَالَتْ: اخْتَلَفَتْ يَدِي وَيَدُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فِي الْوُضُوءِ مِنْ إِنَاءٍ وَاحِدٍ."],"takhrij":"حسن: رواه الإمام أحمد (27067) عن عبد الرحمن بن مهدي، قال: حدَّثني خارجة بن الحارث، قال: حدَّثني سالم بن سَرْج، قال: سمعت أم صُبَيَّة الجُهنية.. فذكرت مثله. وإسناده حسن لأجل خارجة بن الحارث، وهو: بن رافع بن مَكِيث الجُهَني، فإنَّه صدوق.","grade":"حسن","chapter_ar":"باب غسل الرجل والمرأة ووضوئهما في إناء واحد","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (27067).","chapter_en":"A Man and Woman Performing Ghusl and Wuḍūʾ From the Same Vessel","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":16,"content":{"translation":{"en":["Umm Ṣubayyah al-Juhaniyyah, may Allah be pleased with her, reported: “My hand and the hand of the Messenger of Allah ﷺ alternated in the same vessel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (27067)."},{"num":1350,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ قَالَ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (142) عن آدم قال: حدثنا شعبة، عن عبد العزيز بن صهيب قال: سمعت أنسا يقول.. فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقول عند إرادة دخول الخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (142), from Ādam, from Shuʿbah, from ʿAbd al-ʿAzīz ibn Ṣuhayb, who said: I heard Anas say, and he mentioned the report.","chapter_en":"What One Should Say When Intending to Enter the Toilet","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: When the Prophet ﷺ entered the toilet, he would say: “O Allah, I seek refuge in You from the male and female devils.”"]},"buhuth":{"en":["Al-Bukhārī said: Ibn ʿUrwah followed him from Shuʿbah. Ghundar reported from Shuʿbah: “when he came to the place of relieving himself.” Mūsā reported from Ḥammād: “when he entered the place of relieving himself.” Saʿīd ibn Zayd reported from ʿAbd al-ʿAzīz: “when he intended to enter.”","Muslim also narrated it in al-Ḥayḍ (375) from Ḥammād, from ʿAbd al-ʿAzīz ibn Ṣuhayb, with similar wording; he also narrated it through Hushaym from ʿAbd al-ʿAzīz, with the wording: “when he entered the privy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10976],"tks":"متفق عليه: رواه البخاري (142)."},{"num":1351,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ هَذِهِ الْحُشُوشَ مُحْتَضَرَةٌ، فَإِذَا أَتَى أَحَدُكُمُ الْخَلَاءَ، فَلْيَقُلْ: أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ."],"takhrij":"صحيح: رواه أبو داود (6) وابن ماجه (296) كلاهما من طريق شعبة، عن قتادة، عن النضر بن أنس، عن زيد بن أرقم، فذكره. وصحَّحه ابن خزيمة (69) وابن حبان (1408)، والحاكم (229) كلُّهم من هذا الوجه.","grade":"صحيح","chapter_ar":"باب ما يقول عند إرادة دخول الخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (6) and Ibn Mājah (296), and authenticated by Ibn Khuzaymah (69), Ibn Ḥibbān (1408), and al-Ḥākim (668), all through Shuʿbah, from Qatādah, from al-Naḍr ibn Anas, from Zayd ibn Arqam, with a similar report. Its chain is ṣaḥīḥ.","chapter_en":"What One Should Say When Intending to Enter the Toilet","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":17,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Indeed, these places of relieving oneself are attended by devils. So when one of you goes to the toilet, let him say: ‘I seek refuge in Allah from the male and female devils.’”"]},"buhuth":{"en":["Ibn Mājah also narrated it by another route, from Saʿīd ibn Abī ʿArūbah, from Qatādah, from al-Qāsim ibn ʿAwf al-Shaybānī, from Zayd ibn Arqam. Its chain is ṣaḥīḥ, and Qatādah narrated it by two routes, both of which are sound.","Al-Bukhārī alluded to this when he said: “It is possible that Qatādah narrated it from both of them,” as al-Tirmidhī transmitted from him in his Jāmiʿ (1/11).","As for al-Tirmidhī’s statement that “the hadith of Zayd ibn Arqam has inconsistency in its chain,” al-Aʿẓamī said this is not correct in light of al-Bukhārī’s possibility, because true inconsistency is when the differing narrations cannot be reconciled; when reconciliation is possible, the inconsistency is removed.","As for the narration of Maʿmar ibn Rāshid, it is an error, as al-Bayhaqī related in his Sunan (1/96) from Aḥmad, so it does not stand against the sound narrations.","Al-ḥushūsh means privies. The original meaning of al-ḥashsh is a dense cluster of palm trees, where people used to relieve themselves before privies were built in houses. The word has two vocalizations: ḥashsh and ḥushsh. “Muḥtaḍarah” means that devils are present there, as al-Khaṭṭābī explained.","These two reports are the soundest narrations in this chapter. As for the report from ʿAlī ibn Abī Ṭālib that the screen between the eyes of the jinn and the private parts of the children of Ādam is to say “Bismillāh” when entering the privy, it is weak. There are also reports from Ibn Masʿūd and Abū Saʿīd in this chapter, but they are all weak."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8228,10977],"tks":"صحيح: رواه أبو داود (6)، وابن ماجه (296)، وصححه ابن خزيمة (69)، وابن حبان (1408)، والحاكم (229). وإسناده صحيح."},{"num":1352,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ مِنَ الْغَائِطِ قَالَ: غُفْرَانَكَ."],"takhrij":"حسن: رواه أبو داود (30) والترمذي (7) وابن ماجه (300) كلهم من طريق إسرائيل بن يونس، عن يوسف بن أبي بردة، عن أبيه، عن عائشة.","grade":"حسن","chapter_ar":"باب ما يقول الرجل إذا خرج من الخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (30), al-Tirmidhī (7), and Ibn Mājah (300), and authenticated by Ibn Khuzaymah (90), Ibn Ḥibbān (1444), and al-Ḥākim (562).","chapter_en":"What One Should Say Upon Leaving the Toilet","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":18,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: When the Prophet ﷺ came out after relieving himself, he would say: “I seek Your forgiveness.”"]},"buhuth":{"en":["Al-Tirmidhī said: “Ḥasan gharīb; we do not know it except through the narration of Isrāʾīl from Yūsuf ibn Abī Burdah.” He also said: “We do not know anything in this chapter except the hadith of ʿĀʾishah from the Prophet ﷺ.”","Its chain is ḥasan because of Yūsuf ibn Abī Burdah. He is not especially famous, but no criticism of him is known; al-ʿIjlī and Ibn Ḥibbān declared him trustworthy. Al-Nawawī authenticated his hadith in al-Adhkār, as did Ibn Ḥajar in Natāʾij al-Afkār (1/214), and al-Dhahabī also declared him trustworthy in al-Kāshif.","Al-Tirmidhī’s description of it as gharīb is because Isrāʾīl alone narrated it; Isrāʾīl is trustworthy.","“Ghufrānaka” means: I ask You for Your forgiveness.","Al-Khaṭṭābī said that two explanations have been given for saying this supplication after leaving the privy: one is that he sought forgiveness for having left the remembrance of Allah during the time he remained there; the other is that it means repentance from falling short in thanking Allah for the blessing of food, digestion, and the easy removal of harm.","Nothing in this chapter is established except the hadith of ʿĀʾishah. Abū Ḥātim al-Rāzī said: The soundest report in this chapter is the hadith of ʿĀʾishah.","Al-Aʿẓamī said: It is as he said. As for the report from Anas with the wording, “Praise be to Allah who removed harm from me and granted me well-being,” it is weak. Likewise, the reports in this chapter from Abū Dharr and ʿAbd Allāh ibn ʿUmar have weak chains."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10978],"tks":"حسن: رواه أبو داود (30)، والترمذي (7)، وابن ماجه (300)، وصححه ابن خزيمة (90)، وابن حبان (1444)، والحاكم (562)."},{"num":1353,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنْ غَائِطٍ قَطُّ إِلَّا مَسَّ مَاءً."],"takhrij":"صحيح: رواه ابن ماجه (354)، وابن حبان (1441) كلاهما من حديث أبي الأحوص، عن منصور، عن إبراهيم، عن الأسود، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب غسل اليدين بعد الخروج من الخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (354) and Ibn Ḥibbān (1441).","chapter_en":"Washing the Hands After Leaving the Toilet","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":19,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: “I never saw the Messenger of Allah ﷺ come out after relieving himself except that he used water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (354)، وابن حبان (1441)."},{"num":1354,"demo":false,"sanad":"","matn":["عَنْ عَبْدَ اللَّهِ بْنَ الْأَرْقَمِ أَنَّهُ كَانَ يَؤُمُّ أَصْحَابَهُ فَحَضَرَتِ الصَّلَاةُ يَوْمًا فَذَهَبَ لِحَاجَتِهِ، ثُمَّ رَجَعَ فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا أَرَادَ أَحَدُكُمُ الْغَائِطَ فَلْيَبْدَأْ بِهِ قَبْلَ الصَّلَاةِ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة في السفر (49) عن هشام بن عروة، عن أبيه، عن عبدالله بن الأرقم، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الرجل الحاقن يبدأ بالخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (49), Abū Dāwūd (88), al-Tirmidhī (142), al-Nasāʾī (2/110), and Ibn Mājah (616).","chapter_en":"One Who Needs to Relieve Himself Should Do So Before Praying","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn Arqam, may Allah be pleased with him, used to lead his companions in prayer. One day, when the time for prayer came, he went to relieve himself and then returned. He said: I heard the Messenger of Allah ﷺ say: “When one of you needs to defecate, let him begin with that before the prayer.”"]},"buhuth":{"en":["In another wording:","“When one of you needs to defecate and the prayer has been established, let him begin by relieving himself.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (49)، وأبو داود (88)، والترمذي (142)، والنسائي (853)، وابن ماجه (616)."},{"num":1355,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا صَلَاةَ بِحَضْرَةِ الطَّعَامِ، وَلَا هُوَ يُدَافِعُهُ الأَخْبَثَانِ."],"takhrij":"صحيح: رواه مسلم في كتاب المساجد (560) عن يعقوب بن مجاهد، عن ابن أبي عتيق، قال: تحدثتُ أنا والقاسم عند عائشة حديثاً. وكان القاسم رجلاً لحَّانةً. وكان لأم ولد. فقالت له عائشة: مالك لا تَحَدَّثُ كما يتحدثُ ابن أخي هذا؟ أَمَا إنِّي قد علمتُ من أين أُتِيتَ. هذا أدَّبته أُمُّه وأنت أدَّبتك أُمُّك. قال: فغضب القاسم وأضَبَّ عليها. فلما رأى مائدة عائشة قد أتى بها قام. قالت: أين؟ قال: أصلِّي. قالت: اجْلِسْ. قال: إنِّي أًصلِّي. قالت: اجْلِسْ غُدَرُ. إني سمعتُ رسول الله صلى الله عليه وسلم يقول. فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب الرجل الحاقن يبدأ بالخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (560).","chapter_en":"One Who Needs to Relieve Himself Should Do So Before Praying","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: I heard the Messenger of Allah ﷺ say: “There is no prayer in the presence of food, nor while one is resisting the urge of the two foul things.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2387],"tks":"صحيح: رواه مسلم (560)."},{"num":1356,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَقُومُ أَحَدُكُمْ إِلَى الصَّلَاةِ وَبِهِ أَذًى."],"takhrij":"صحيح: رواه ابن ماجه (618) عن أبي بكر بن أبي شيبة، وهو في مصنفه (7935) ثنا أبو أسامة، عن إدريس الأوْدي، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الرجل الحاقن يبدأ بالخلاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (618) and Abū Bakr ibn Abī Shaybah in his Muṣannaf (2/422), and authenticated by Ibn Ḥibbān.","chapter_en":"One Who Needs to Relieve Himself Should Do So Before Praying","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “None of you should rise for prayer while he is suffering from the need to relieve himself.”"]},"buhuth":{"en":["Ibn Ḥibbān’s wording is:","“None of you should pray while resisting the urge of the two foul things.”","The word “discomfort” here means the need to urinate or defecate, as explained in the Musnad of Imām Aḥmad (9697, 10094)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (618)، وأبو بكر بن أبي شيبة في مصنفه (7935)، وصححه ابن حبان."},{"num":1357,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ مِنَ اللَّيْلِ، فَقَضَى حَاجَتَهُ، ثُمَّ غَسَلَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ نَامَ."],"takhrij":"متفق عليه: أخرجه البخاري (6316)، ومسلم (304)، كلاهما من طريق سفيان، عن سلمة بن كهيل، عن كريب، عن ابن عباس..فذكر مثله. واللفظ لمسلم، أمَّا البخاري، فذكره في سياقٍ أطول انظر كتاب الوضوء: باب أنَّ النوم ليس حدثاً بل مَظِنَّة للحدث.","grade":"متفق عليه","chapter_ar":"باب غسل الوجه واليدين إذا استيقظ من النوم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6316) and Muslim (304).","chapter_en":"Washing the Face and Hands Upon Awakening From Sleep","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās, may Allah be pleased with them, reported: The Prophet ﷺ rose during the night, relieved himself, then washed his face and hands and went back to sleep."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6316)، ومسلم (304)."},{"num":1358,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ."],"takhrij":"صحيح: أخرجه النسائي (5) قال: أخبرنا حُميد بن مَسعدة البصري ومحمد بن عبدالأعلى، عن يزيد، وهو ابن زريع، قال: حدثني عبدالرحمن بن أبي عتيق، قال: حدثني أبي، قال: سمعتُ عائشة تحدث، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī (5), who reported from Ḥumayd ibn Masʿadah al-Baṣrī and Muḥammad ibn ʿAbd al-Aʿlā, from Yazīd—meaning Ibn Zurayʿ—from ʿAbd al-Raḥmān ibn Abī ʿAtīq, from his father, who said: I heard ʿĀʾishah narrate, and he mentioned the report.","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported that the Prophet ﷺ said: “The siwāk is a means of purification for the mouth and a means of pleasing the Lord.”"]},"buhuth":{"en":["Its narrators are trustworthy and its chain is ṣaḥīḥ. Al-Bukhārī cited it in his Ṣaḥīḥ (4/158 with Fatḥ al-Bārī) in a decisive form. Ibn Khuzaymah (135) and Ibn Ḥibbān (1067) also authenticated it. See al-Minnah al-Kubrā (1/121).","Ibn Abī ʿAtīq is ʿAbd Allāh ibn Muḥammad ibn ʿAbd al-Raḥmān ibn Abī Bakr al-Ṣiddīq; Muḥammad had the kunyah Abū ʿAtīq. It was narrated by other routes, and in some it was made part of the Musnad of Abū Bakr, but the correct attribution is to the Musnad of ʿĀʾishah.","Similar reports are narrated from Ibn ʿAbbās and Anas, but their chains contain weak narrators; and from Abū Umāmah in Ibn Mājah (289), in whose chain is ʿAlī ibn Yazīd al-Alhānī, whom Ibn Maʿīn and others weakened.","Regarding the phrase “the siwāk is a purifier for the mouth and a means of pleasing the Lord,” muṭahharah may be pronounced with fatḥ or kasr on the mīm, two usages mentioned by Ibn al-Sikkīt and others; the kasr is more common. It refers to a vessel used for purification, and the siwāk is likened to it because it cleans the mouth; purification here means cleanliness. Al-Nawawī mentioned this in Sharḥ al-Muhadhdhab (1/268).","As for the report from ʿĀʾishah, “I kept to the siwāk until I feared it would make my teeth fall out,” its chain is inconsistent. It is narrated from ʿAmr ibn Abī ʿAmr, the client of al-Muṭṭalib, in three different ways, showing inconsistency in this chain even though he is among the narrators of the two Ṣaḥīḥs. The word yudrid means the falling out of the teeth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه النسائي (5)."},{"num":1359,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عَلَيْكُمْ بِالسِّوَاكِ، فَإِنَّهُ مَطْيَبَةٌ لِلْفَمِ، وَمَرْضَاةٌ لِلرَّبِّ."],"takhrij":"حسن: رواه الإمام أحمد (5865) عن قتيبة بن سعيد، حدثنا ابنُ لهيعة، عن عبيدالله بن أبي جعفر، عن نافع، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (5865), from Qutaybah ibn Saʿīd, from Ibn Lahīʿah, from ʿUbayd Allāh ibn Abī Jaʿfar, from Nāfiʿ, from Ibn ʿUmar, who mentioned the report.","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported that the Prophet ﷺ said: “Keep to the siwāk, for it makes the mouth pleasant and is a means of pleasing the Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (5865)."},{"num":1360,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (114)، عن أبي الزناد، عن الأعرج، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (114), from Abū al-Zinād, from al-Aʿraj, from Abū Hurayrah, who mentioned the report.","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Were it not that I would cause hardship for my Ummah, I would have commanded them to use the siwāk.”"]},"buhuth":{"en":["Al-Bukhārī also narrated it in al-Jumuʿah (887) and Muslim in al-Ṭahārah (252), through several routes from Sufyān, from Abū al-Zinād. The wording here is Mālik’s in al-Muwaṭṭaʾ. Al-Bukhārī and Muslim include the addition “at every prayer” or “with every prayer”; al-Nasāʾī and Ibn Mājah have “with wuḍūʾ at every prayer”; and Aḥmad has “with every wuḍūʾ.”","The hadith of Abū Hurayrah with the additional mention of delaying the ʿIshāʾ prayer until half the night will come in the Book of Prayer, in the chapter on the time of ʿIshāʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (114)، عن أبي الزناد، عن الأعرج، عن أبي هريرة قال، فذكره."},{"num":1361,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ. قَالَ: فَكَانَ زَيْدُ بْنُ خَالِدٍ يَضَعُ السِّوَاكَ مِنْهُ مَوْضِعَ الْقَلَمِ مِنْ أُذُنِ الْكَاتِبِ، كُلَّمَا قَامَ إِلَى الصَّلَاةِ اسْتَاكَ."],"takhrij":"صحيح:  رواه الإمام أحمد (17048) فقال: حدثنا عبدالصمد (هو ابن عبدالوارث)، قال: حدَّثنا حرب – يعني ابن شدَّاد، عن يحيى (هو ابن أبي كثير)، حدَّثنا أبو سلمة،","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (17048), who reported from ʿAbd al-Ṣamad—meaning Ibn ʿAbd al-Wārith—from Ḥarb—meaning Ibn Shaddād—from Yaḥyā—meaning Ibn Abī Kathīr—from Abū Salamah, and he mentioned the report.","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Zayd ibn Khālid al-Juhanī, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Were it not that I would cause hardship for my Ummah, I would have commanded them to use the siwāk at every prayer.” He said: Zayd ibn Khālid used to place the siwāk behind his ear like the pen of a scribe. Whenever he stood for prayer, he would use the siwāk."]},"buhuth":{"en":["Abū Dāwūd (47), whose wording this is, al-Tirmidhī (23), and al-Nasāʾī in al-Kubrā (3029) all narrated it through Muḥammad ibn Isḥāq, from Muḥammad ibn Ibrāhīm al-Taymī, from Abū Salamah ibn ʿAbd al-Raḥmān, from Zayd ibn Khālid al-Juhanī. Al-Tirmidhī added in the marfūʿ wording: “and I would have delayed the ʿIshāʾ prayer until one-third of the night.”","Al-Tirmidhī said: “Ḥasan ṣaḥīḥ.”","Al-Aʿẓamī said: Rather, this chain is weak because of Muḥammad ibn Isḥāq, who was a mudallis and narrated it with ʿanʿanah. However, Imām Aḥmad (17048) narrated it by two routes: one from Muḥammad ibn Fuḍayl, from Muḥammad ibn Isḥāq, with similar wording; and the second from ʿAbd al-Ṣamad, who said: Ḥarb—meaning Ibn Shaddād—narrated to us, from Yaḥyā, from Abū Salamah, from Zayd ibn Khālid, with similar wording. This chain is ṣaḥīḥ. Yaḥyā is Ibn Abī Kathīr. See this hadith also in the Book of Prayer, chapter on the time of ʿIshāʾ.","As for the report from Jābir ibn ʿAbd Allāh that the Prophet’s ﷺ siwāk was behind his ear like a scribe’s pen, it is weak. Al-Bayhaqī narrated it (1/37) and, after transmitting al-Ṭabarānī’s remark, said that Yaḥyā ibn Yamān was not considered strong and that it appears he confused this with the earlier hadith of Muḥammad ibn Isḥāq."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (17048)."},{"num":1362,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَاب النَّبيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْلَا أَشُقُّ عَلَى أُمَّتِي، لَأَمَرْتُهُمْ بالسِّوَاكِ مَعَ كُلِّ صَلَاةٍ."],"takhrij":"صحيح: رواه أحمد (23486) قال: حدثنا يحيى بن سعيد (القطان) قال: سمعناه من الأعمش، حدثني عبدالله بن يسار، عن عبد الرحمن بن أبي ليلى، عن رجل من أصحاب النبي صلى الله عليه وسلم، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (23486).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ reported that the Prophet ﷺ said: “Were it not that I would cause hardship for my Ummah, I would have commanded them to use the siwāk with every prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23486)."},{"num":1363,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ وُضُوءٍ."],"takhrij":"حسن: أخرجه الطبراني في الأوسط ( 1238) واللفظ له، وأحمد (968) في سياق أطول، كلاهما من طريق محمد بن إسحاق، قال: حدثني عمي عبد الرحمن بن يسار، عن عبيدالله بن أبي رافع، عن أبيه، عن علي بن أبي طالب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (2/138, no. 1260), whose wording is cited here, and Aḥmad (968).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Were it not that I would cause hardship for my Ummah, I would have commanded them to use the siwāk with every wuḍūʾ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (1260)، واللفظ له، وأحمد (968)."},{"num":1364,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ حَنْظَلَةَ بْنِ أَبِي عَامِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُمِرَ بِالْوُضُوءِ لِكُلِّ صَلَاةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ، فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ، أُمِرَ بِالسِّوَاكِ لِكُلِّ صَلَاةٍ.","فَكَانَ ابْنُ عُمَرَ يَرَى أَنَّ بِهِ قُوَّةً، فَكَانَ لَا يَدَعُ الْوُضُوءَ لِكُلِّ صَلَاةٍ."],"takhrij":"حسن: رواه أبو داود (48) قال: حدثنا محمد بن عوف الطائي، حدثنا أحمد بن خالد، حدثنا محمد بن إسحاق، عن محمد بن يحيى بن حبان، عن عبدالله بن عبدالله بن عمر قال: قلت: أرأيت توضُّؤَ ابن عمر لكل صلاة طاهرًا وغير طاهر، عَمَّ ذاك؟ فقال: حدَّثَتْنيه أسماء بنت زيد بن الخطاب أن عبدالله بن حنظلة حدثَها، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (48).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn Ḥanẓalah ibn Abī ʿĀmir, may Allah be pleased with him, reported: The Messenger of Allah ﷺ was commanded to perform wuḍūʾ for every prayer, whether he was already in a state of purity or not. When that became difficult for him, he was commanded to use the siwāk for every prayer. Ibn ʿUmar, may Allah be pleased with them, considered himself capable of continuing to renew his wuḍūʾ, so he would not leave performing wuḍūʾ for every prayer."]},"buhuth":{"en":["Abū Dāwūd pointed to the narration of Ibrāhīm—meaning Ibn Saʿd—from Muḥammad ibn Isḥāq in which the name appears as ʿUbayd Allāh, in the diminutive form. The author said: This difference does not cause harm, for both ʿAbd Allāh and ʿUbayd Allāh are trustworthy narrators from the narrators of the two Ṣaḥīḥs; Abū Zurʿah and al-Nasāʾī declared both trustworthy. Its chain is ḥasan. Muḥammad ibn Isḥāq was a mudallis, but his explicit statement of hearing occurs in Aḥmad (21960), through Yaʿqūb ibn Ibrāhīm, from his father, from Muḥammad ibn Isḥāq, who said: Muḥammad ibn Yaḥyā ibn Ḥabbān al-Anṣārī al-Māzinī narrated to me, from ʿUbayd Allāh ibn ʿAbd Allāh ibn ʿUmar, and he mentioned the report."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (48)."},{"num":1365,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (245) ومسلم في الطهارة (255). كلاهما من حديث جرير، عن منصور، عن أبي وائل، عن حذيفة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (245) and Muslim in al-Ṭahārah (255).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān, may Allah be pleased with him, reported: When the Prophet ﷺ rose during the night, he would vigorously rub his mouth with the siwāk."]},"buhuth":{"en":["In the narration of Ḥuṣayn ibn ʿAbd al-Raḥmān, from Abū Wāʾil, in Muslim, the wording is: “When he rose to pray tahajjud, he would rub his mouth with the siwāk.” Al-shawṣ means rubbing the teeth crosswise with the siwāk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (245)، ومسلم (255)."},{"num":1366,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللَّهُ مَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ وَيُصَلِّي تِسْعَ رَكَعَاتٍ لَا يَجْلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ... (فَذَكَرَهَا فِي حَدِيثِ طَوِيل)."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين وقصرها (746) عن محمد بن المثنى العنزيّ، حدّثنا محمد بن أبي عدي، عن سعيد، عن قتادة، عن زرارة بن أوفى، عن سعد بن هشام، عنها، وهو طرف من حديث طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in Ṣalāt al-Musāfirīn wa-Qaṣrihā (746).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: We used to prepare his siwāk and his water for purification. Allah would awaken him during whatever portion of the night He willed, and he would use the siwāk, perform wuḍūʾ, and pray nine rakʿahs, not sitting until the eighth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746)."},{"num":1367,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَانَ إِذَا دَخَلَ بَيْتَهُ، بَدَأَ بِالسِّوَاكِ.","وفي رواية:قَالَ شُرَيْحٍ: سَأَلْتُ عَائِشَةَ قُلْتُ: بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا دَخَلَ بَيْتَهُ؟ قَالَتْ: بِالسِّوَاكِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (253). من حديث مِسْعَر، عن المقدام بن شريح، عن أبيه، قال: سألت عائشة.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (253).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: When the Prophet ﷺ entered his house, he would begin with the siwāk.","In another narration, Shurayḥ said: I asked ʿĀʾishah: “With what did the Prophet ﷺ begin when he entered his house?” She replied: “With the siwāk.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (253)."},{"num":1368,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدْتُهُ يَسْتَنُّ بِسِوَاكٍ بِيَدِهِ، يَقُولُ: أُعْ أُعْ، وَالسِّوَاكُ فِي فِيهِ كَأَنَّه يَتَهَوَّعُ."],"takhrij":"متفق عليه: أخرجه البخاري في الوضوء (244)، واللفظ له، ومسلم في الطهارة (254)، كلاهما من حديث حماد بن زيد، عن غيلان بن جرير، عن أبي بردَة، عن أبيه. ولفظ مسلم قال: دخلت على النبي صلى الله عليه وسلم وطرفُ السواك على لسانه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (244), whose wording is cited here, and Muslim (254).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī, may Allah be pleased with him, reported: I came to the Messenger of Allah ﷺ while he was cleaning his teeth with a siwāk in his hand and making the sound: “Uʿ, uʿ,” while the siwāk was in his mouth, as though he were retching."]},"buhuth":{"en":["Muslim’s wording states:","“I entered upon the Prophet ﷺ while the end of the siwāk was upon his tongue.”","The expression yatahawwaʿ comes from al-tahawwuʿ, meaning retching or vomiting. Here it refers to drawing phlegm up from the deepest part of the throat in order to expel it, resembling the movement of someone about to vomit."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (244)، واللفظ له، ومسلم (254)."},{"num":1369,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكْثَرْتُ عَلَيْكُمْ فِي السِّوَاكِ."],"takhrij":"صحيح: أخرجه البخاري في الجمعة (888)، وابن حبان (1066)، والدارمي (709)، وأحمد (12459) والبيهقيّ (143) واللفظ له، والنسائى (6)، وأبو يعلى (4171) مسند البزار (7442)،كلهم عن عبد الوارث، قال: حدَّثنا شعيب بن الحبحاب، حدَّثنا أنس.. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (888).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “I have repeatedly emphasized the siwāk to you.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (888)."},{"num":1370,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَرَانِي فِي الْمَنَامِ أَتَسَوَّكُ بِسِوَاكٍ، فَجَذَبَنِي رَجُلَانِ أَحَدُهُمَا أَكْبَرُ مِنَ الْآخَرِ، فَنَاوَلْتُ السِّوَاكَ الْأَصْغَرَ مِنْهُمَا، فَقِيلَ لِي: كَبِّرْ، فَدَفَعْتُهُ إِلَى الْأَكْبَرِ."],"takhrij":"صحيح: رواه مسلم في الرؤيا (2271)، عن نصر بن علي الجهضمي، أخبرني أبي، حدَّثنا صخر بن جويرية، عن نافع، أنَّ عبدالله بن عمر حدَّثه به.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2271).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported that the Prophet ﷺ said: “I was shown in a dream that I was using a siwāk. Two men came to me, one of them older than the other. I handed it to the younger of them, but I was told: ‘Give precedence to the elder.’ So I handed it to the older of them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2271)."},{"num":1371,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ لَا يَنَامُ إِلَّا وَالسِّوَاكُ عِنْدَهُ، فَإِذَا اسْتَيْقَظَ بَدَأَ بِالسِّوَاكِ."],"takhrij":"حسن: رواه أحمد (5979)، وأبو يعلى (5749) كلاهما من طريق أبي داود الطيالسي، حدثنا محمد بن مسلم بن مهران مولًى لقريش، سمعتُ جدّي يحدّث عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (5979) and Abū Yaʿlā (5749).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, reported: The Messenger of Allah ﷺ would not sleep except with the siwāk beside him, and when he awoke, he would begin with the siwāk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (5979)، وأبو يعلى (5749)."},{"num":1372,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَنُّ وَعِنْدَهُ رَجُلَانِ، أَحَدُهُمَا أَكْبَرُ مِنَ الْآخَرِ، فَأَوْحَى اللَّهُ إِلَيْهِ فِي فَضْلِ السِّوَاكِ أَنْ كَبِّرْ أَعْطِ السِّوَاكَ أَكْبَرَهُمَا."],"takhrij":"حسن: رواه أبو داود (50) قال: حدثنا محمد بن عيسى، حدثنا عَنْبَسة بن عبد الواحد، عن هشام بن عروة، عن أبيه، عن عائشة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (50).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: The Messenger of Allah ﷺ was using the siwāk while two men were with him, one older than the other. Allah revealed to him concerning the siwāk: “Give precedence to the elder; give the siwāk to the older of the two.”"]},"buhuth":{"en":["Its chain is ḥasan because of Muḥammad ibn ʿĪsā ibn al-Qāsim ibn Sumayʿ, concerning whom there is disagreement, though his hadith is ḥasan. Al-Ḥāfiẓ also graded it ḥasan in Fatḥ al-Bārī (1/357). Abū Dāwūd said that Aḥmad ibn Ḥazm reported from Abū Saʿīd—meaning al-Aʿrābī—that this was among the reports uniquely transmitted by the people of Madinah. The word “yastannu” means to use the siwāk. It is derived from sinn (tooth), referring to passing something rough over another thing; from the same root is the sharpening stone used for iron and the like. Here it means that he rubbed his teeth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (50)."},{"num":1373,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنَّهُ بَاتَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَقَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ آخِرِ اللَّيْلِ، فَخَرَجَ فَنَظَرَ فِي السَّمَاء، ثُمَّ تَلَا هَذِهِ الآيَةَ فِي آلِ عِمْرَانَ: ﴿إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ﴾ حَتَّى بَلَغَ: ﴿فَقِنَا عَذَابَ النَّارِ﴾ [آل عمران: 190، 191] ثُمَّ رَجَعَ إِلَى الْبَيْتِ فَتَسَوَّكَ وَتَوَضَّأَ، ثُمَّ قَامَ فَصَلَّى، ثُمَّ اضْطَجَعَ، ثُمَّ قَامَ فَخَرَجَ فَنَظَرَ إِلَى السَّمَاءِ، فَتَلَا هَذِهِ الآيَةَ، ثُمَّ رَجَعَ فَتَسَوَّكَ، فَتَوَضَّأَ، ثُمَّ قَامَ فَصَلَّى."],"takhrij":"صحيح: رواه مسلم في الطهارة (256)، عن عبد بن حميد، حدثنا أبو نعيم، حدثنا إسماعيل بن مسلم، حدثنا أبو المتوكل، أنَّ ابن عباس حدَّثه.. فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (256).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās, may Allah be pleased with them, reported: He spent a night with the Prophet ﷺ. During the latter part of the night, the Prophet of Allah ﷺ arose, went outside, looked toward the sky, and recited the verse from Āl ʿImrān: “Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for people of understanding…” until he reached: “…so protect us from the punishment of the Fire.” [Sūrat Āl ʿImrān 3:190–191] He then returned to the house, used the siwāk, performed wuḍūʾ, stood and prayed, then lay down. Thereafter, he arose again, went outside, looked toward the sky and recited these verses. He then returned, used the siwāk, performed wuḍūʾ, stood, and prayed."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (256)."},{"num":1374,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِاللَّيْلِ رَكْعَتَيْنِ رَكْعَتَيْنِ، ثُمَّ يَنْصَرِفُ فَيَسْتَاكُ."],"takhrij":"صحيح: رواه ابن ماجه (288)، وأحمد (1881)، والحاكم (514) كلهم من طريق عثّام بن علي العامري، حدثنا الأعمش، عن حبيب بن أبي ثابت، عن سعيد بن جبير، عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (288), Aḥmad (1881), and al-Ḥākim (514). The wording is that of Aḥmad.","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: The Messenger of Allah ﷺ would pray two rakʿahs during the night, then turn away and use the siwāk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (288)، وأحمد (1881)، والحاكم (514). واللفظ لأحمد."},{"num":1375,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوضَعُ لَهُ وَضُوءُهُ وَسِوَاكُهُ، فَإِذَا قَامَ مِنَ اللَّيْلِ تَخَلَّى ثُمَّ اسْتَاكَ."],"takhrij":"حسن: أخرجه أبو داود (56)، عن موسى بن إسماعيل، حدَّثنا حمَّاد، أخبرنا بهز بن حكيم، عن زرارة بن أوفى، عن سعد بن هشام، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في السواك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (56).","chapter_en":"What Has Been Reported Concerning the Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":22,"content":{"translation":{"en":["The Mother of the Believers ʿĀʾishah, may Allah be pleased with her, reported: The Prophet ﷺ would have his water for purification and his siwāk prepared for him. When he arose during the night, he would relieve himself and then use the siwāk."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (56)."},{"num":1376,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّهُ كَانَ يَجْتَنِي سِوَاكًا مِنَ الْأَرَاكِ وَكَانَ دَقِيقَ السَّاقَيْنِ، فَجَعَلَتْ الرِّيحُ تَكْفَؤُهُ، فَضَحِكَ الْقَوْمُ مِنْهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِمَّ تَضْحَكُونَ؟ قَالُوا: يَا نَبِيَّ اللَّهِ، مِنْ دِقَّةِ سَاقَيْهِ، فَقَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَهُمَا أَثْقَلُ فِي الْمِيزَانِ مِنْ أُحُدٍ."],"takhrij":"حسن: رواه أحمد (3991) وأبو يعلى (5310) والبزار – كشف الأستار (2678) والطبراني في الكبير (8452) كلهم من طريق عاصم، عن زَرّ بن حُبيش عن ابن مسعود فذكره. وصحَّحه ابن حبَّان (7069) فرواه من هذا الوجه.","grade":"حسن","chapter_ar":"باب ما جاء في السواك من الأراك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (3991), Abū Yaʿlā (5310), al-Bazzār in Kashf al-Astār (2678), and al-Ṭabarānī in al-Muʿjam al-Kabīr (8452); it was authenticated by Ibn Ḥibbān (7069).","chapter_en":"What Has Been Reported Concerning Using Siwāk From the Arāk Tree","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Ibn Masʿūd, may Allah be pleased with him, was gathering siwāk sticks from the arāk tree. His legs were thin, and the wind began to sway him, so the people laughed at him. The Messenger of Allah ﷺ said: “What are you laughing at?” They replied: “O Prophet of Allah, at the thinness of his legs.” He said: “By the One in Whose Hand is my soul, those two legs are heavier on the Scale than Mount Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16232],"tks":"حسن: رواه أحمد (3991)، وأبو يعلى (5310)، والبزار في كشف الأستار (2678)، والطبراني في الكبير (8452)، وصححه ابن حبان (7069)."},{"num":1377,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ قُرَّةَ، عَنْ أَبِيهِ، أَنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ رَقَى فِي شَجَرَةٍ يَجْتَنِي مِنْهَا سِوَاكًا، فَوَضَعَ رِجْلَيْهِ عَلَيْهَا، فَضَحِكَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ دِقَّةِ سَاقَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَهُمَا أَثْقَلُ فِي الْمِيزَانِ مِنْ أُحُدٍ."],"takhrij":"حسن: رواه البزار – الكشف (2677) والطبراني في الكبير في الكبير (19/ح 59) كلاهما من طريق سهل بن حماد أبي عتاب الدلال، ثنا شعبة، عن معاوية بن قرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في السواك من الأراك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (2677) and al-Ṭabarānī in al-Muʿjam al-Kabīr (19, no. 59).","chapter_en":"What Has Been Reported Concerning Using Siwāk From the Arāk Tree","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["Muʿāwiyah ibn Qurrah reported from his father, may Allah be pleased with him,: ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, climbed a tree to gather siwāk from it and placed his legs upon it. The Companions of the Messenger of Allah ﷺ laughed at the thinness of his legs, so the Messenger of Allah ﷺ said: “Those two legs are heavier on the Scale than Mount Uḥud.”"]},"buhuth":{"en":["Al-Haythamī said in al-Majmaʿ (9/289): “The narrators of both chains are narrators of the Ṣaḥīḥ.” Al-Ḥākim authenticated it (3/317). The author said: It is as they stated; the narrators of the chain are narrators of the Ṣaḥīḥ, except that Sahl ibn Ḥammād, despite being among Muslim’s narrators, is subject to disagreement, though his hadith is ḥasan."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10265],"tks":"حسن: رواه البزار في كشف الأستار (2677)، والطبراني في الكبير (19، رقم 59)."},{"num":1378,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ يَقُولُ: أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ابْنَ مَسْعُودٍ فَصَعِدَ عَلَى شَجَرَةٍ، أَمَرَهُ أَنْ يَأْتِيَهُ مِنْهَا بِشَيْءٍ، فَنَظَرَ أَصْحَابُهُ إِلَى سَاقِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ حِينَ صَعِدَ الشَّجَرَةَ، فَضَحِكُوا مِنْ حُمُوشَةِ سَاقَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تَضْحَكُونَ؟ لَرِجْلُ عَبْدِ اللَّهِ أَثْقَلُ فِي الْمِيزَانِ يَوْمَ الْقِيَامَةِ مِنْ أُحُدٍ."],"takhrij":"حسن: رواه أحمد (920) وأبو يعلى (539) والطبراني في الكبير (8516) كلهم من طريق مغيرة، عن أم موسى قال: سمعت علياً فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في السواك من الأراك","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (920), Abū Yaʿlā (539), and al-Ṭabarānī (8516).","chapter_en":"What Has Been Reported Concerning Using Siwāk From the Arāk Tree","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":23,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib, may Allah be pleased with him, reported: The Prophet ﷺ instructed Ibn Masʿūd, may Allah be pleased with him, to climb a tree and bring him something from it. His Companions saw the leg of ʿAbdullāh ibn Masʿūd as he climbed the tree and laughed at the thinness of his legs. The Messenger of Allah ﷺ said: “What are you laughing at? The leg of ʿAbdullāh will be heavier on the Scale on the Day of Resurrection than Mount Uḥud.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (920)، وأبو يعلى (539)، والطبراني (8516)."},{"num":1379,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ وَمَعَهُ سِوَاكٌ يَسْتَنُّ بِهِ فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ لَهُ: أَعْطِنِي هَذَا السِّوَاكَ يَا عَبْدَ الرَّحْمَنِ، فَأَعْطَانِيهِ فَقَصَمْتُهُ، ثُمَّ مَضَغْتُهُ فَأَعْطَيْتُهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاسْتَنَّ بِهِ وَهُوَ مُسْتَسْنِدٌ إِلَى صَدْرِي."],"takhrij":"صحيح: رواه البخاري في الجمعة (890) عن إسماعيل، قال: حدَّثني سليمان ابن بلال، قال: قال هشام بن عروة: أخبرني أبي، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب من تسوك بسواك غيره","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (890).","chapter_en":"Using Another Person’s Siwāk","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":24,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: ʿAbd al-Raḥmān ibn Abī Bakr, may Allah be pleased with them, entered while carrying a siwāk with which he was cleaning his teeth. The Messenger of Allah ﷺ looked at it, so I said: “Give me that siwāk, O ʿAbd al-Raḥmān.” He gave it to me. I broke and softened it, then chewed its end and gave it to the Messenger of Allah ﷺ. He used it to clean his teeth while leaning against my chest."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (890)."},{"num":1380,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَنْثِرْ، وَمَنِ اسْتَجْمَرَ فَلْيُوتِرْ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (2)، عن أبي الزناد، عن الأعرج، عن أبي هريرة.. فذكره. ومن طريقه أخرجه البخاري في الوضوء (162) وجمعه بحديث وإذا استيقظ أحدكم من نومه فليغسل يده قبل أن يدخلها في وضوئه، فإن أحدَكم لا يدري أين باتت يده، لأجل اتحاد السند.","grade":"متفق عليه","chapter_ar":"باب الإيتار في الاستجمار والاستنثار","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ṭahārah (2).","chapter_en":"Using an Odd Number When Cleaning With Stones and When Expelling Water From the Nose","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “When one of you performs wuḍūʾ, let him put water into his nose and then expel it; and whoever cleans himself with stones should use an odd number.”"]},"buhuth":{"en":["Through Mālik’s route, al-Bukhārī narrated it in al-Wuḍūʾ (162), combining it with the hadith, “When one of you wakes from sleep, let him wash his hand before putting it into his water for wuḍūʾ, for none of you knows where his hand spent the night,” because the chain is the same. Muslim narrated it in al-Ṭahārah (237) through another route from Sufyān, from Abū al-Zinād. Mālik also narrated it from Ibn Shihāb, from Abū Idrīs al-Khawlānī, from Abū Hurayrah, with the wording: “Whoever performs wuḍūʾ should expel the water from his nose, and whoever uses stones for cleansing should do so an odd number of times.” Muslim also narrated it through this route. Al-Bukhārī (161) narrated it through Yūnus, from al-Zuhrī, with similar wording. Muslim narrated it through Yūnus as well, but joined Abū Saʿīd with Abū Hurayrah. Al-Ḥumaydī narrated in his Musnad (957), from Sufyān ibn ʿUyaynah, from Abū al-Zinād, from al-Aʿraj, from Abū Hurayrah, that the Messenger of Allah ﷺ said: “When one of you cleans himself with stones, let him do so an odd number of times; and when he expels water from his nose, let him do so an odd number of times.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)."},{"num":1381,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا اسْتَجْمَرَ أَحَدُكُمْ، فَلْيُوتِرْ."],"takhrij":"صحيح: رواه مسلم في الطهارة (239) وأحمد (14128)، وعبد الرزاق (9273)، كلهم من طريق عبد الرزاق، نا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يقول: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الإيتار في الاستجمار والاستنثار","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (239).","chapter_en":"Using an Odd Number When Cleaning With Stones and When Expelling Water From the Nose","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported that the Messenger of Allah ﷺ said: “When one of you cleans himself with stones, let him use an odd number.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (239)."},{"num":1382,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الِاسْتِجْمَارُ تَوٌّ، وَرَمْيُ الْجِمَارِ تَوٌّ، وَالسَّعْيُ بَيْنَ الصَّفَا، وَالْمَرْوَةِ تَوٌّ، وَالطَّوَافُ تَوٌّ، وَإِذَا اسْتَجْمَرَ أَحَدُكُمْ فَلْيَسْتَجْمِرْ بِتَوٍّ."],"takhrij":"صحيح: رواه مسلم في الحجّ (1300) والبيهقيّ (9331) كلاهما من طريق سلمة بن شبيب، حدّثنا الحسن بن أعين، حدثنا مَعْقل (وهو ابن عبيدالله الجزريّ)، عن أبي الزّبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب الإيتار في الاستجمار والاستنثار","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥajj (1300).","chapter_en":"Using an Odd Number When Cleaning With Stones and When Expelling Water From the Nose","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “Cleaning oneself with stones is performed in an odd number; throwing the pebbles is in an odd number; walking between al-Ṣafā and al-Marwah is in an odd number; ṭawāf is in an odd number; and when one of you cleans himself with stones, let him do so an odd number of times.”"]},"buhuth":{"en":["Regarding the word “taw,” it means odd or single. “It came taw” means singly. A taw is also a rope twisted as a single strand without being made into a tightly plied cord; its plural is atwāʾ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5024],"tks":"صحيح: رواه مسلم (1300)."},{"num":1383,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ قَيْسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا تَوَضَّأْتَ فَانْتَثِرْ، وَإِذَا اسْتَجْمَرْتَ فَأَوْتِرْ."],"takhrij":"صحيح: رواه الترمذي (27) والنسائي (89) وابن ماجه (406) وأحمد (18987)، والحميدي (879) والطبراني في الكبير (6313) كلهم من حديث منصور، عن هلال بن يساف، عن سلمة بن قيس به.","grade":"صحيح","chapter_ar":"باب الإيتار في الاستجمار والاستنثار","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (27), al-Nasāʾī (89), and Ibn Mājah (406).","chapter_en":"Using an Odd Number When Cleaning With Stones and When Expelling Water From the Nose","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":25,"content":{"translation":{"en":["Salamah ibn Qays, may Allah be pleased with him, reported that the Messenger of Allah ﷺ said: “When you perform wuḍūʾ, expel the water from your nose; and when you clean yourself with stones, do so an odd number of times.”"]},"buhuth":{"en":["Its chain is ṣaḥīḥ, and Ibn Ḥibbān authenticated it (1436). Manṣūr is Ibn al-Muʿtamir ibn ʿAbd Allāh al-Sahmī, Abū ʿAttāb al-Kūfī. Abū Ḥātim said: “Trustworthy.” Al-ʿIjlī said: “A Kūfan, trustworthy and precise in hadith; he was among the most reliable of the people of Kūfah. His hadith was like a straight arrow over which no one differed. He was devoted to worship, a righteous man, was compelled to serve as judge for two months, and had a slight inclination toward tashayyuʿ without extremism.” He is among the narrators used by the major hadith compilers. Al-Tirmidhī said: “The hadith of Salamah ibn Qays is ḥasan ṣaḥīḥ.” The phrase “fa-intathir” means: draw water into the nose and then expel it so that what is inside comes out; al-nathrah is the nasal passage. Also in this chapter are the hadith of ʿAbd Allāh ibn Zayd ibn ʿĀṣim describing the Prophet’s ﷺ wuḍūʾ, and the hadith of ʿĀṣim ibn Laqīṭ ibn Ṣabirah in the chapter on interlacing the fingers during wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (27)، والنسائي (89)، وابن ماجه (406)."},{"num":1384,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ الْفَارِسِيِّ قَالَ: قِيلَ لَهُ: قَدْ عَلَّمَكُمْ نَبِيُّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ؟ قَالَ: فَقَالَ: أَجَلْ لَقَدْ نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ بِغَائِطٍ، أَوْ بَوْلٍ، أَوْ أَنْ نَسْتَنْجِيَ بِالْيَمِينِ، أَوْ أَنْ نَسْتَنْجِيَ بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ، أَوْ أَنْ نَسْتَنْجِيَ بِرَجِيعٍ أَوْ بِعَظْمٍ."],"takhrij":"صحيح: رواه مسلم في الطهارة (262) والبيهقيّ (430) كلاهما من طريق الأعمش، عن إبراهيم، عن عبدالرحمن بن يزيد، عن سلمان.. فذكر الحديث.","grade":"صحيح","chapter_ar":"باب في بيان كيفية الاستطابة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ṭahārah (262).","chapter_en":"Explaining the Proper Manner of Cleansing Oneself After Relieving Oneself","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":26,"content":{"translation":{"en":["Salmān al-Fārisī, may Allah be pleased with him, was told: “Your Prophet ﷺ has taught you everything, even how to relieve yourselves!” He replied: “Yes. He prohibited us from facing the qiblah while defecating or urinating, from cleaning ourselves with the right hand, from cleaning ourselves with fewer than three stones, and from cleaning ourselves with dung or bone.”"]},"buhuth":{"en":["In another narration, some of the polytheists said mockingly: “I see that your companion teaches you everything, even how to relieve yourselves!” He replied: “Yes,” then mentioned the hadith. Concerning al-khirāʾah, al-Khaṭṭābī said that it is pronounced with kasrah on the khāʾ and a lengthened alif and means going apart and sitting to relieve oneself. He added that most narrators pronounce the khāʾ with fatḥah and without lengthening the alif. Al-Jawharī said in al-Ṣiḥāḥ that al-kharāʾah is pronounced with fatḥah and a long alif."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (262)."},{"num":1385,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا شَرِبَ أَحَدُكُمْ فَلَا يَتَنَفَّسْ فِي الْإِنَاءِ، وَإِذَا أَتَى الْخَلَاءَ فَلَا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ، وَلَا يَتَمَسَّحْ بِيَمِينِهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (153) ومسلم في الطهارة (267) كلاهما من طريق يحيى بن أبي كثير، عن عبدالله بن أبي قتادة به مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن الاستنجاء باليمين","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (153) and Muslim in al-Ṭahārah (267).","chapter_en":"The Prohibition of Cleansing Oneself With the Right Hand","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Qatādah reported from his father, may Allah be pleased with him, that the Messenger of Allah ﷺ said: “When one of you drinks, let him not breathe into the vessel. When one of you goes to relieve himself, let him not touch his private part with his right hand and let him not wipe himself with his right hand.”"]},"buhuth":{"en":["In a narration in Muslim: “and that he should not cleanse himself with his right hand.” The phrase “and he should not wipe himself with his right hand” means that he should not perform istinjāʾ with it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (153)، ومسلم (267)."},{"num":1386,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةُ زَوْجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْعَلُ يَمِينَهُ لِطَعَامِهِ وَشَرَابِهِ وَثِيَابِهِ، وَيَجْعَلُ شِمَالَهُ لِمَا سِوَى ذَلِكَ."],"takhrij":"حسن: رواه أبو داود (32) عن محمد بن آدم بن سليمان المصيصي، حدثنا ابن أبي زائدة، قال: حدثني أبو أيوب – يعني الإفريقي – عن عاصم، عن المسيب بن رافع ومعبد، أن حارثة بن وهب الخزاعي قال: حدثتني حفصة، فذكرته.","grade":"حسن","chapter_ar":"باب النهي عن الاستنجاء باليمين","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (32).","chapter_en":"The Prohibition of Cleansing Oneself With the Right Hand","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":27,"content":{"translation":{"en":["Ḥafṣah, the wife of the Prophet ﷺ, may Allah be pleased with her reported: The Prophet ﷺ used his right hand for his food, drink, and clothing, and used his left hand for other matters."]},"buhuth":{"en":["Ibn Ḥibbān (5227) and al-Ḥākim (4/109) authenticated it, and al-Ḥākim said: “This hadith is ṣaḥīḥ, though they did not include it.” Al-Dhahabī objected: “There is an unknown narrator in its chain.” The author said: It is not clear to me whom he meant, for all of its narrators are known, ranging from trustworthy to ṣadūq, except Abū Ayyūb al-Ifrīqī—ʿAbd Allāh ibn ʿAlī al-Ifrīqī—whom Abū Zurʿah considered somewhat weak, saying: “There is objectionable material in his hadith; he is not firm.” Ibn Maʿīn, however, said: “There is no harm in him.” A narrator such as this does not cause the hadith to fall below the level of ḥasan when he does not contradict stronger narrators. ʿĀṣim is Ibn Bahdalah, Abū Bakr al-Muqriʾ, a ṣadūq narrator who had some errors. As for the report from ʿĀʾishah that the Messenger of Allah ﷺ used his right hand for purification and food and his left hand for the privy and removing harm, it is disconnected. Abū Dāwūd (33) narrated it through Abū Tawbah al-Rabīʿ ibn Nāfiʿ, from ʿĪsā ibn Yūnus, from Ibn Abī ʿArūbah, from Abū Maʿshar, from Ibrāhīm, from her. Abū Maʿshar is Ziyād ibn Kulayb al-Ḥanẓalī; Abū Ḥātim criticized him while others declared him trustworthy. Ibrāhīm is Ibn Yazīd al-Nakhaʿī, the jurist, and he did not hear from ʿĀʾishah, because he was born in 46 AH while ʿĀʾishah died in 57 AH according to the sound view."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (32)."},{"num":1387,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ قَالَ: أَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْغَائِطَ، فَأَمَرَنِي أَنْ آتِيَهُ بِثَلَاثَةِ أَحْجَارٍ، فَوَجَدْتُ حَجَرَيْنِ وَالْتَمَسْتُ الثَّالِثَ فَلَمْ أَجِدْهُ، فَأَخَذْتُ رَوْثَةً فَأَتَيْتُهُ بِهَا، فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى الرَّوْثَةَ، وَقَالَ: هَذَا رِكْسٌ."],"takhrij":"صحيح: رواه البخاري في الوضوء (156)، عن أبي نعيم، قال: حدَّثنا زهير، عن أبي إسحاق، قال: ليس أبو عبيدة ذكره ولكن عبد الرحمن بن الأسود، عن أبيه، أنَّه سمع عبدالله (هو ابن مسعود) يقول: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب لا يستنجى بروث ولا عظم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-Wuḍūʾ (156).","chapter_en":"One Must Not Clean Oneself With Dung or Bone","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd, may Allah be pleased with him, reported: The Prophet ﷺ went to relieve himself and instructed me to bring him three stones. I found two stones but could not find a third, so I took a piece of dung and brought it to him. He took the two stones, threw away the dung, and said: “This is impure.”"]},"buhuth":{"en":["Al-Bukhārī said: Ibrāhīm ibn Yūsuf reported from his father, from Abū Isḥāq: “ʿAbd al-Raḥmān narrated to me.”","The word “riks” is used in the sense of “rijs,” meaning impurity. Abū ʿUbayd said it resembles excrement; one says rakastu or arkastuhu when something is returned or cast back. Al-Nasāʾī (42) said: “Riks is the food of the jinn.” In another narration of al-Nasāʾī (39): “He forbade anyone from cleansing himself with a bone or dung.” In its chain is Abū ʿUthmān ibn Sannah al-Khuzāʿī, the narrator from Ibn Masʿūd; he is acceptable because he was corroborated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (156)."},{"num":1388,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ قَالَ: أَنَا سَأَلْتُ ابْنَ مَسْعُودٍ فَقُلْتُ: هَلْ شَهِدَ أَحَدٌ مِنْكُمْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ الْجِنِّ؟ قَالَ: لَا، وَلَكِنَّا كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَفَقَدْنَاهُ، فَالْتَمَسْنَاهُ فِي الأَوْدِيَةِ وَالشِّعَابِ، فَقُلْنَا اسْتُطِيرَ أَوِ اغْتِيلَ قَالَ: فَبِتْنَا بِشَرِّ لَيْلَةٍ بَاتَ بِهَا قَوْمٌ، فَلَمَّا أَصْبَحْنَا إِذَا هُوَ جَاءٍ مِنْ قِبَلِ حِرَاءٍ، قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّهِ، فَقَدْنَاكَ فَطَلَبْنَاكَ فَلَمْ نَجِدْكَ فَبِتْنَا بِشَرِّ لَيْلَةٍ بَاتَ بِهَا قَوْمٌ، فَقَالَ: أَتَانِي دَاعِي الْجِنِّ، فَذَهَبْتُ مَعَهُ فَقَرَأْتُ عَلَيْهِمُ الْقُرْآنَ، قَالَ: فَانْطَلَقَ بِنَا فَأَرَانَا آثَارَهُمْ وَآثَارَ نِيرَانِهِمْ، وَسَأَلُوهُ الزَّادَ، فَقَالَ: لَكُمْ كُلُّ عَظْمٍ ذُكِرَ اسْمُ اللَّهِ عَلَيْهِ يَقَعُ فِي أَيْدِيكُمْ أَوْفَرَ مَا يَكُونُ لَحْمًا، وَكُلُّ بَعْرَةٍ عَلَفٌ لِدَوَابِّكُمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَلَا تَسْتَنْجُوا بِهِمَا، فَإِنَّهُمَا طَعَامُ إِخْوَانِكُمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (450)، عن محمد بن المثنى، حدَّثنا عبد الأعلى، عن داود، عن عامر، قال: سألت علقمة: هل كان ابن مسعود شهد مع رسول الله صلى الله عليه وسلم ليلة الجنِّ؟ قال: فقال علقمة.. فذكر مثله.","grade":"صحيح","chapter_ar":"باب لا يستنجى بروث ولا عظم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (450).","chapter_en":"One Must Not Clean Oneself With Dung or Bone","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["ʿAlqamah reported: I asked Ibn Masʿūd, may Allah be pleased with him,: “Did any of you accompany the Messenger of Allah ﷺ on the Night of the Jinn?” He replied: “No. But one night we were with the Messenger of Allah ﷺ and then could not find him. We searched for him in the valleys and mountain passes and said, ‘Has he been carried away or assassinated?’ We spent the worst night a people could spend. When morning came, he approached us from the direction of Ḥirāʾ. We said: ‘O Messenger of Allah, we could not find you. We searched for you but did not find you, and we spent the worst night a people could spend.’ He said: ‘A caller from the jinn came to me, so I went with him and recited the Qurʾān to them.’ He then took us and showed us their tracks and the traces of their fires. They had asked him for provisions, so he said: ‘Every bone over which the name of Allah has been mentioned will be yours; when it comes into your hands, it will have the fullest amount of meat upon it. And every piece of dung is fodder for your animals.’ The Messenger of Allah ﷺ then said: ‘Do not cleanse yourselves with either of them, for they are the food of your brothers.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (450)."},{"num":1389,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: اتَّبَعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَخَرَجَ لِحَاجَتِهِ، فَكَانَ لَا يَلْتَفِتُ، فَدَنَوْتُ مِنْهُ، فَقَالَ: ابْغِنِي أَحْجَارًا أَسْتَنْفِضْ بِهَا أَوْ نَحْوَهُ، وَلَا تَأْتِنِي بِعَظْمٍ وَلَا رَوْثٍ، فَأَتَيْتُهُ بِأَحْجَارٍ بِطَرَفِ ثِيَابِي فَوَضَعْتُهَا إِلَى جَنْبِهِ وَأَعْرَضْتُ عَنْهُ، فَلَمَّا قَضَى أَتْبَعَهُ بِهِنَّ."],"takhrij":"صحيح: رواه البخاري في الوضو (155)، ورواه في كتاب المناقب، باب ذكر الجن (3860)، من طريق عمرو بن يحيى بن سعيد، قال: أخبرني جدِّي، ( أي سعيد بن عمرو بن سعيد بن أبي العاص ) عن أبي هريرة. وفيه قال أبو هريرة: فقلت: ما بال العظم والروثة؟ فقال: هما طعام الجن، وإنه أتاني وفد من جن نصيبين، ونعم الجن، فسألوني الزاد، فدعوت الله أن لا يمروا بعظْم ولا بروثةٍ إلا وجدوا عليها طعاماً.","grade":"صحيح","chapter_ar":"باب لا يستنجى بروث ولا عظم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (155, 3860).","chapter_en":"One Must Not Clean Oneself With Dung or Bone","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: I followed the Prophet ﷺ when he went out to relieve himself. He would not turn around. I came near him, and he said: “Find me some stones with which I may clean myself—or words to that effect—and do not bring me a bone or dung.” So I brought him some stones in the edge of my garment, placed them beside him, and turned away from him. When he had finished, he used them to cleanse himself."]},"buhuth":{"en":["In the narration, Abū Hurayrah, may Allah be pleased with him, said:","I asked:","“Why not a bone or dung?”","He replied:","“They are among the food of the jinn. A delegation of the jinn of Naṣībīn came to me—and excellent jinn they were—and asked me for provisions. So I supplicated Allah for them that they would not pass by a bone or a piece of dung except that they would find food upon it.”","Al-Dāraquṭnī (1/56) added through another chain from Abū Ḥāzim, from Abū Hurayrah, that the Prophet ﷺ forbade cleansing oneself with a bone or dung and said: “They do not purify.” Al-Dāraquṭnī then said: “Its chain is ṣaḥīḥ.” Ibn ʿAdī, however, criticized one of its narrators, Salamah ibn Rajāʾ, noting that his reports include solitary and unusual narrations for which he is not corroborated.","The expression “astanfiḍ bihā” comes from istinfāḍ, meaning removing harm and cleansing oneself; the root meaning of nafaḍa is movement and removal."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (155، 3860)."},{"num":1390,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُتَمَسَّحَ بِعَظْمٍ أَوْ بِبَعْرٍ."],"takhrij":"صحيح: رواه مسلم في الطهارة (263) وأبو يعلى في مسنده (3739) كلاهما من طريق أبو الزبير أنه سمع جابرا يقول، فذكره.","grade":"صحيح","chapter_ar":"باب لا يستنجى بروث ولا عظم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (263).","chapter_en":"One Must Not Clean Oneself With Dung or Bone","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: The Messenger of Allah ﷺ prohibited cleansing oneself with a bone or with dung."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (263)."},{"num":1391,"demo":false,"sanad":"","matn":["عَنْ شَيْبَانَ الْقِتْبَانِيِّ قَالَ: إِنَّ مَسْلَمَةَ بْنَ مُخَلَّدٍ اسْتَعْمَلَ رُوَيْفِعَ بْنَ ثَابِتٍ عَلَى أَسْفَلِ الْأَرْضِ، قَالَ شَيْبَانُ: فَسِرْنَا مَعَهُ مِنْ كَوْمِ شَرِيكٍ إِلَى عَلْقَمَاءَ، أَوْ مِنْ عَلْقَمَاءَ إِلَى كُومِ شَرِيكٍ يُرِيدُ عَلْقَامَ . فَقَالَ رُوَيْفِعٌ: إِنْ كَانَ أَحَدُنَا فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَأْخُذُ نِضْوَ أَخِيهِ عَلَى أَنَّ لَهُ النِّصْفَ مِمَّا يَغْنَمُ وَلَنَا النِّصْفُ . وَإِنْ كَانَ أَحَدُنَا لَيَطِيرُ لَهُ النَّصْلُ وَالرِّيشُ وَلِلْآخَرِ الْقِدْحُ، ثُمَّ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رُوَيْفِعُ! لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي، فَأَخْبِرِ النَّاسَ أَنَّهُ مَنْ عَقَدَ لِحْيَتَهُ أَوْ تَقَلَّدَ وَتَرًا أَوِ اسْتَنْجَى بِرَجِعِ دَابَّةٍ أَوْ عَظْمٍ، فَإِنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ بَرِيءٌ."],"takhrij":"حسن: أخرجه أبو داود (36) عن عَيَاش بن عباس القِتْباني، أن شُيَيْم بن بَيْتان أخبره، عن شَيبان القِتْباني، فذكر الحديث.","grade":"حسن","chapter_ar":"باب لا يستنجى بروث ولا عظم","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (36).","chapter_en":"One Must Not Clean Oneself With Dung or Bone","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":28,"content":{"translation":{"en":["Shaybān al-Qitbānī reported that Maslamah ibn Mukhallad appointed Ruwayfiʿ ibn Thābit, may Allah be pleased with him, over the lower region. Shaybān said: We traveled with him from Kawm Sharīk to ʿAlqamāʾ—or from ʿAlqamāʾ to Kawm Sharīk; he meant ʿAlqām. Ruwayfiʿ said: During the time of the Messenger of Allah ﷺ, one of us would take his brother’s worn riding camel on the condition that he would receive half of whatever booty was gained and we would receive half. One of us might receive the arrowhead and feathers, while the other received the shaft. Then he said: The Messenger of Allah ﷺ said to me: “O Ruwayfiʿ, perhaps you will live for a long time after me. Inform the people that whoever knots his beard, wears a bowstring around his neck, or cleans himself with animal dung or a bone, then Muḥammad ﷺ is free of him.”"]},"buhuth":{"en":["Shaybān is Ibn Umayyah, known as Abū Ḥudhayfah. Ibn Ḥajar said in al-Taqrīb that he is unknown. Al-Nasāʾī (5067) narrated from ʿAyyāsh ibn ʿAbbās al-Qitbānī that Shuyaym ibn Baytān told him that he heard Ruwayfiʿ ibn Thābit narrate the marfūʿ portion. Shuyaym’s hearing from Ruwayfiʿ is established, and Ibn Maʿīn and others declared him trustworthy, so the chain is sound without Shaybān al-Qitbānī.","Some scholars judged the report inconsistent because of differences in its chains. This can be reconciled by treating it as transmitted from both Ruwayfiʿ and ʿAbd Allāh ibn ʿAmr, and by understanding that Shuyaym first heard it through Shaybān and later directly from Ruwayfiʿ.","“Whoever knots his beard” was explained as the practice of knotting the beard in war or manipulating the hair so that it becomes curled and knotted. “Wears a bowstring” refers to a cord bearing an amulet or beads intended to ward off the evil eye or harm. “Muḥammad is free of him” is a severe warning and emphatic deterrent."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (36)."},{"num":1392,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْخَلَاءَ، فَأَتَيْتُهُ بِتَوْرٍ فِيهِ مَاءٌ فَاسْتَنْجَى، ثُمَّ مَسَحَ بيَدَهُ فِي الْأَرْضِ ثُمَّ غَسَلَهَا، ثُمَّ أَتَيْتُهُ بِتَوْرٍ آخَرَ، فَتَوَضَّأَ بِهِ."],"takhrij":"حسن: رواه أبو داود (45)، والنسائي (50)، وابن ماجه (358)، وأحمد (8104)، وصحّحه ابن حبان (1405) كلهم من حديث شريك، عن إبراهيم بن جرير، عن أبي زرعة بن عمرو بن جرير، عن أبي هريرة فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب دلك اليد بالأرض بعد الاستنجاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (45), al-Nasāʾī (50), Ibn Mājah (358), and Aḥmad (8104), and authenticated by Ibn Ḥibbān (1405). The wording is that of Aḥmad.","chapter_en":"Rubbing the Hand on the Ground After Istinjāʾ","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ entered the place of relieving himself. I brought him a tawr containing water. He cleansed himself, then rubbed his hand on the ground and washed it. I then brought him another vessel from which he performed wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (45)، والنسائي (50)، وابن ماجه (358)، وأحمد (8104)، وصححه ابن حبان (1405)، واللفظ لأحمد."},{"num":1393,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ يَقُولُ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ لِحَاجَتِهِ أَجِيءُ أَنَا وَغُلَامٌ مَعَنَا إِدَاوَةٌ مِنْ مَاءٍ، يَعْنِي يَسْتَنْجِي بِهِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (150) واللفظ له، ومسلم في الطهارة (271) كلاهما من طريق شعبة عن أبي معاذ، وهو عطاء بن أبي ميمونة، أنه سمع أنس بن مالك يقول، فذكر الحديث. ولفظ مسلم: كان رسول الله صلى الله عليه وسلم يدخل الخلاءَ، فأحمل أنا وغلام نحوي إداوةً من ماءٍ وعَنَزةً، فيستنجي بالماء.","grade":"متفق عليه","chapter_ar":"باب الاستنجاء بالماء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (150), whose wording is cited here, and Muslim in al-Ṭahārah (271).","chapter_en":"Cleansing Oneself With Water","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: When the Prophet ﷺ went out to relieve himself, I and another boy would bring a small leather vessel containing water for him, meaning that he would cleanse himself with it."]},"buhuth":{"en":["Muslim’s wording states:","“When the Messenger of Allah ﷺ went to relieve himself, I and a boy about my age would carry a vessel of water and a short spear for him, and he would cleanse himself with the water.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (150)، واللفظ له، ومسلم (271)."},{"num":1394,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: مُرْنَ أَزْوَاجَكُنَّ أَنْ يَسْتَطِيبُوا بِالْمَاءِ فَإِنِّي أَسْتَحْيِيهِمْ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَفْعَلُهُ."],"takhrij":"صحيح: رواه الترمذي (19) والنسائي (46) كلاهما عن قتيبة، قال: حدثنا أبو عوانة، عن قتادة، عن معاذة، عنها.","grade":"صحيح","chapter_ar":"باب الاستنجاء بالماء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (19) and al-Nasāʾī (46).","chapter_en":"Cleansing Oneself With Water","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":30,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, said: “Tell your husbands to cleanse themselves with water, for I feel shy to tell them directly. Indeed, the Messenger of Allah ﷺ used to do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (19)، والنسائي (46)."},{"num":1395,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنَّ يَخْرُجْنَ بِاللَّيْلِ إِذَا تَبَرَّزْنَ إِلَى الْمَنَاصِعِ وَهُوَ صَعِيدٌ أَفْيَحُ، فَكَانَ عُمَرُ يَقُولُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْجُبْ نِسَاءَكَ، فَلَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ، فَخَرَجَتْ سَوْدَةُ بِنْتُ زَمْعَةَ زَوْجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ اللَّيَالِي عِشَاءً، وَكَانَتِ امْرَأَةً طَوِيلَةً، فَنَادَاهَا عُمَرُ: أَلَا قَدْ عَرَفْنَاكِ يَا سَوْدَةُ، حِرْصًا عَلَى أَنْ يَنْزِلَ الْحِجَابُ، فَأَنْزَلَ اللَّهُ آيَةَ الْحِجَابِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (146) ومسلم في السلام (2170/18) كلاهما من حديث ابن شهاب، عن عروة، عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب خروج النساء إلى البراز","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (146) and Muslim (2170).","chapter_en":"Women Going Out to Relieve Themselves","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["ʿĀʾishah, may Allah be pleased with her, reported: The wives of the Prophet ﷺ used to go out at night when they needed to relieve themselves, going to al-Manāṣiʿ, which was a broad open area. ʿUmar, may Allah be pleased with him, used to say to the Prophet ﷺ: “Have your wives observe screening.” But the Messenger of Allah ﷺ had not yet done so. One night after ʿIshāʾ, Sawdah bint Zamʿah may Allah be pleased with her, the wife of the Prophet ﷺ, went out. She was a tall woman. ʿUmar called out: “We have recognized you, O Sawdah!” He did so out of eagerness that the ruling of ḥijāb be revealed. Then Allah revealed the verse of ḥijāb."]}},"tuhfa":{},"full":1,"rep":[13093],"tks":"متفق عليه: رواه البخاري (146)، ومسلم (2170)."},{"num":1396,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَدْ أُذِنَ أَنْ تَخْرُجْنَ فِي حَاجَتِكُنَّ، قَالَ هِشَامٌ: يَعْنِي الْبَرَازَ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (147) هكذا مختصرا عن زكريا قال: حدثنا أبو أسامة، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرت الحديث. ورواه في التفسير bukhari(4795) مفصلا بالإسناد السابق،، وزكريا هو: ابن يحيى، قالت فيه عائشة: خرجَتْ سودة بعد ما ضُرب الحجابُ لحاجتها، وكانت امرأة جسيمة لا تخفى على من يعرفها، فرآها عمر بن الخطاب فقال: يا سَودة! أما والله ما تَخْفَينَ علينا، فانظري كيف تَخْرُجين، قالت: فانكفأتْ راجعة، ورسول الله صلى الله عليه وسلم في بيتي، وإنه ليتعشَّى وفي يده عَرْقٌ، فدخلت فقالت: يا رسول الله! إني خرجتُ لبعض حاجتي، فقال لي عمر كذا وكذا، قالت: فأوحى الله إليه، ثم رفع عنه، وإن العرْق في يده ما وضعه، فقال: إنه قد أُذِن لكُنّ أن تخرجْن لحاجتكنّ.","grade":"متفق عليه","chapter_ar":"باب خروج النساء إلى البراز","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Wuḍūʾ (147) and Muslim (2170).","chapter_en":"Women Going Out to Relieve Themselves","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":31,"content":{"translation":{"en":["The Mother of the Believers ʿĀʾishah, may Allah be pleased with her, reported that the Prophet ﷺ said: “You have been permitted to go out for your needs.” Hishām said: He meant going out to relieve themselves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (147)، ومسلم (2170)."},{"num":1397,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ قَالَ: أَرْدَفَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ خَلْفَهُ، فَأَسَرَّ إِلَيَّ حَدِيثًا، لَا أُحَدِّثُ بِهِ أَحَدًا مِنَ النَّاسِ، وَكَانَ أَحَبَّ مَا اسْتَتَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحَاجَتِهِ، هَدَفٌ، أَوْ حَائِشُ نَخْلٍ، قَالَ ابْنُ أَسْمَاءَ فِي حَدِيثِهِ: يَعْنِي حَائِطَ نَخْلٍ."],"takhrij":"صحيح: أخرجه مسلم في الحيض (342) من طريق مهدي بن ميمون، ثنا محمد ابن عبدالله بن أبي يعقوب، عن الحسن بن سعد، عن عبدالله بن جعفر فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الاستتار عند قضاء الحاجة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Ḥayḍ (342).","chapter_en":"Concealing Oneself When Relieving Oneself","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["ʿAbdullāh ibn Jaʿfar, may Allah be pleased with them, reported: One day the Messenger of Allah ﷺ seated me behind him on his mount and confided something to me that I would not disclose to anyone. The thing behind which the Messenger of Allah ﷺ most liked to conceal himself when relieving himself was a raised mound or a cluster of palm trees. In another wording: “A wall or enclosure of palm trees.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (342)."},{"num":1398,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ، فِي حَدِيثِهِ الطَّوِيلِ: سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى نَزَلْنَا وَادِيًا أَفْيَحَ، فَذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْضِي حَاجَتَهُ، فَاتَّبَعْتُهُ بِإِدَاوَةٍ مِنْ مَاءٍ، فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَرَ شَيْئًا يَسْتَتِرُ بِهِ، فَإِذَا شَجَرَتَانِ بِشَاطِئِ الْوَادِي، فَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى إِحْدَاهُمَا، فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ: انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ، فَانْقَادَتْ مَعَهُ كَالْبَعِيرِ الْمَخْشُوشِ الَّذِي يُصَانِعُ قَائِدَهُ حَتَّى أَتَى الشَّجَرَةَ الْأُخْرَى، فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ: انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ، فَانْقَادَتْ مَعَهُ كَذَلِكَ حَتَّى إِذَا كَانَ بِالْمَنْصَفِ مِمَّا بَيْنَهُمَا لَأَمَ بَيْنَهُمَا يَعْنِي جَمَعَهُمَا، فَقَالَ: الْتَئِمَا عَلَيَّ بِإِذْنِ اللَّهِ، فَالْتَأَمَتَا... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الزهد (3012: 74) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حَزْرة، عن عبادة بن الوليد بن عبادة بن الصامت قال: خرجتُ أنا وأبي نطلب العلم حتى أتينا جابر بن عبدالله فذكره في حديث طويل، وهو مخرج في دلائل النبوة.","grade":"صحيح","chapter_ar":"باب الاستتار عند قضاء الحاجة","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Zuhd (3012:74).","chapter_en":"Concealing Oneself When Relieving Oneself","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":32,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported in his lengthy narration: We traveled with the Messenger of Allah ﷺ until we came to a broad valley. The Messenger of Allah ﷺ went to relieve himself, and I followed him carrying a vessel of water. He looked around but saw nothing behind which he could conceal himself. There were two trees at the edge of the valley. He went to one of them, took hold of one of its branches and said: “Come along with me by Allah’s permission.” It followed him like a camel led by a nose-rope that complies with its handler. He then came to the other tree, took hold of one of its branches and said: “Come along with me by Allah’s permission.” It likewise followed him. When he reached the midpoint between them, he brought them together and said: “Join together over me by Allah’s permission.” So the two trees joined together over him… the remainder of the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3012: 74)."},{"num":1399,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا ذَهَبَ الْمَذْهَبَ أَبْعَدَ."],"takhrij":"حسن: رواه أبو داود (1) والترمذي (20) والنسائي الصغرى (17) وابن ماجه (331) كلّهم من طريق محمد بن عمرو، عن أبي سلمة، عن المغيرة بن شعبة به.","grade":"حسن","chapter_ar":"باب التباعد للبراز في الفضاء","chapter_ur":"","part_ar":"كتاب الطهارة","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (1), al-Tirmidhī (20), al-Nasāʾī (17), and Ibn Mājah (331).","chapter_en":"Going Far Away to Relieve Oneself in an Open Area","part_en":"The Book of Purification","group_ar":"","group_en":"","part_no":4,"group_no":0,"chapter_no":33,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported: When the Prophet ﷺ went to relieve himself, he would go far away."]},"buhuth":{"en":["Al-Nasāʾī adds that while he was on one of his journeys he went to relieve himself and said: “Bring me water for wuḍūʾ.” Water was brought to him, and he performed wuḍūʾ and wiped over his leather socks. Al-Tirmidhī said: ḥasan ṣaḥīḥ. Ibn Khuzaymah (50) and al-Ḥākim (1/140) also authenticated it; al-Ḥākim said: “Ṣaḥīḥ according to the condition of Muslim.” Its chain is ḥasan because of Muḥammad ibn ʿAmr ibn ʿAlqamah al-Laythī, whom al-Nasāʾī declared trustworthy and from whom Muslim narrated in corroboration.","The expression “when he went to al-madhhab” uses al-madhhab as a name for the place of defecation; it is also called al-khalāʾ, al-mirfaq, and al-mirḥāḍ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1)، والترمذي (20)، والنسائي (17)، وابن ماجه (331)."}]);